// Flashcard content. Each card is [topic, question, answer, source, flag or null, figure or null, id]. The id (C1, C2, ...) stays with the card for good: never change or reuse one, and give a new card the next unused number.
// NRC exam categories and their topics, in bank order. PSAR topics are grouped by their "PSAR: " prefix.
const TOPIC_GROUPS = {"Components":["Valves","Sensors and Detectors","Controllers and Positioners","Pumps","Motors and Generators","Heat Exchangers and Condensers","Demineralizers and Ion Exchangers","Breakers, Relays, and Disconnects"],"Reactor Theory":["Neutrons","Neutron Life Cycle","Reactor Kinetics and Neutron Sources","Reactivity Coefficients","Control Rods","Fission Product Poisons","Fuel Depletion and Burnable Poisons","Reactor Operational Physics"],"Thermodynamics":["Thermodynamic Units and Properties","Basic Energy Concepts","Steam","Thermodynamic Processes","Thermodynamic Cycles","Fluid Statics and Dynamics","Heat Transfer and Heat Exchangers","Thermal Hydraulics","Core Thermal Limits","Brittle Fracture and Vessel Thermal Stress"]};

const CARDS = [
  // Atomic and nuclear physics (DOE-HDBK-1019)
  ["Neutrons", "What is the atomic number Z, and how is it related to the number of electrons?", "Z is the number of protons. In a neutral atom the number of electrons also equals Z.", "DOE-1015-V1 (DOE-HDBK-1015/1-93), Characteristics of Atoms, CH-01 p. 3", null, null, "C1"],
  ["Neutrons", "Given the mass number A and atomic number Z, how many neutrons are in the nucleus?", "A - Z neutrons. A is the total of protons and neutrons (nucleons).", "DOE-1019-V1 (DOE-HDBK-1019/1-93), Atomic Nature of Matter, NP-01 p. 4", null, null, "C2"],
  ["Neutrons", "What are isotopes?", "Nuclides with the same Z (same element) but different numbers of neutrons, so different A.", "DOE-1019-V1 (DOE-HDBK-1019/1-93), Atomic Nature of Matter, NP-01 p. 10", null, null, "C3"],
  ["Neutrons", "What three forces act inside the nucleus, and which is short-range?", "Electrostatic repulsion (long-range), the nuclear force (short-range attraction between all nucleons), and gravity (negligible).", "DOE-1019-V1 (DOE-HDBK-1019/1-93), Atomic Nature of Matter, NP-01 p. 10", null, null, "C4"],
  ["Neutrons", "What is mass defect, and how is binding energy found from it?", "Mass defect is the difference between the atom's mass and the sum of its parts. Binding energy = mass defect x 931.5 MeV per amu.", "DOE-1019-V1 (DOE-HDBK-1019/1-93), Mass Defect and Binding Energy, NP-01 p. 21", null, null, "C5"],
  ["Neutrons", "What happens to Z and A in alpha decay?", "Z drops by 2 and A drops by 4. An alpha is 2 protons plus 2 neutrons.", "DOE-1019-V1 (DOE-HDBK-1019/1-93), Modes of Radioactive Decay, NP-01 p. 29", null, null, "C6"],
  ["Neutrons", "What happens in beta-minus decay?", "A neutron becomes a proton plus an ejected electron. Z goes up by 1, A is unchanged.", "DOE-1019-V1 (DOE-HDBK-1019/1-93), Modes of Radioactive Decay, NP-01 p. 29", null, null, "C7"],
  ["Neutrons", "What happens in beta-plus decay?", "A proton becomes a neutron plus an ejected positron. Z goes down by 1, A is unchanged.", "DOE-1019-V1 (DOE-HDBK-1019/1-93), Modes of Radioactive Decay, NP-01 p. 29", null, null, "C8"],
  ["Neutrons", "What is electron capture?", "The nucleus captures an inner-shell electron, which combines with a proton to form a neutron.", "DOE-1019-V1 (DOE-HDBK-1019/1-93), Modes of Radioactive Decay, NP-01 p. 25", null, null, "C9"],
  ["Neutrons", "What is an isomeric transition?", "An excited nucleus drops to a lower energy level by emitting a gamma ray.", "DOE-1019-V1 (DOE-HDBK-1019/1-93), Modes of Radioactive Decay, NP-01 p. 26", null, null, "C10"],
  ["Neutrons", "How does an alpha particle deposit energy in matter?", "Large mass and charge: it deposits a lot of energy over a very short distance.", "DOE-1019-V1 (DOE-HDBK-1019/1-93), Energy Release From Fission, NP-01 p. 64", null, null, "C11"],
  ["Neutrons", "Which gamma interaction transfers all of the gamma's energy to an electron?", "The photoelectric effect. Compton scattering transfers only part of it.", "DOE-1019-V1 (DOE-HDBK-1019/1-93), Energy Release From Fission, NP-01 p. 67", null, null, "C12"],
  ["Neutrons", "What does positron annihilation produce?", "Two gamma rays, each 0.51 MeV (the electron's rest-mass energy).", "DOE-1019-V1 (DOE-HDBK-1019/1-93), Energy Release From Fission, NP-01 p. 67", null, null, "C13"],
  ["Neutrons", "What are the three neutron scattering and absorption outcomes listed for neutron-nucleus interactions?", "Elastic scattering (KE conserved), inelastic scattering (KE goes into target excitation), and absorption (radiative capture or particle ejection).", "DOE-1019-V1 (DOE-HDBK-1019/1-93), Neutron Interactions, NP-01 p. 47", null, {"f": "images/doe-1019-v1-np-01-fig17.png", "alt": "Inelastic scattering: a neutron enters the nucleus, then a lower energy neutron and a gamma ray leave.", "cap": "Figure 17. Inelastic Scattering. Source: DOE-1019-V1 (DOE-HDBK-1019/1-93), NP-01 p. 45.", "at": "a"}, "C14"],
  ["Neutrons", "What is radiative capture?", "A neutron is absorbed, the nucleus is excited, and it releases the excitation energy as a gamma ray.", "DOE-1019-V1 (DOE-HDBK-1019/1-93), Neutron Interactions, NP-01 p. 47", null, null, "C15"],
  ["Reactor Kinetics and Neutron Sources", "Name two intrinsic neutron sources.", "Spontaneous fission of heavy nuclides in fuel (U-238, U-235, Pu-239), and the B-11 alpha-n reaction in fuel. Deuterium in coolant (gamma-n) is also listed.", "DOE-1019-V1 (DOE-HDBK-1019/1-93), Neutron Sources, NP-02 p. 4", null, null, "C16"],
  ["Reactor Kinetics and Neutron Sources", "What is an installed neutron source? Give one example.", "A material placed in the reactor just to produce neutrons, such as Cf-252 (spontaneous fission) or Be-9 with an alpha or gamma source.", "DOE-1019-V1 (DOE-HDBK-1019/1-93), Neutron Sources, NP-02 p. 3", null, null, "C17"],
  ["Neutrons", "Where do most fission product mass numbers cluster?", "Near 95 and 140. Most fission products decay by beta-minus emission.", "DOE-1019-V1 (DOE-HDBK-1019/1-93), Energy Release From Fission, NP-01 p. 62", null, null, "C18"],
  ["Neutrons", "What is enriched uranium?", "Uranium with U-235 above its natural 0.7 percent. Depleted uranium is below 0.7 percent.", "DOE-1019-V1 (DOE-HDBK-1019/1-93), Chart of the Nuclides, NP-01 p. 16", null, null, "C19"],
  ["Neutrons", "When are prompt neutrons emitted, and what is their typical energy?", "Essentially at the moment of fission. They are born between about 0.1 and 10 MeV, averaging about 2 MeV.", "DOE-1019-V1 (DOE-HDBK-1019/1-93), Neutron Flux Spectrum, NP-02 p. 37", null, null, "C20"],
  ["Reactor Kinetics and Neutron Sources", "What are delayed neutrons, and what fraction of fission neutrons are they?", "Delayed neutrons are released from the decay of fission products that are called delayed neutron precursors. Delayed neutron precursors are grouped according to half-life. Half-lives vary from fractions of a second to almost a minute. The fraction of neutrons born as delayed neutrons is different for different fuel materials. Following are values for some common fuel materials. Uranium-235 0.0065 Plutonium-239 0.0021", "DOE-1019-V1 (DOE-HDBK-1019/1-93), Prompt and Delayed Neutrons, NP-02 p. 32", "An earlier answer said delayed neutrons come 'seconds to minutes' after fission. The handbook gives precursor half-lives of fractions of a second to almost a minute.", null, "C21"],
  ["Neutrons", "What shape does a fast reactor's neutron spectrum follow?", "Fast reactors have a neutron energy spectrum that has the same shape as the prompt neutron energy spectrum.", "DOE-1019-V1 (DOE-HDBK-1019/1-93), Neutron Flux Spectrum, NP-02 p. 37", "An earlier answer added that fast reactors have no moderator. The handbook says only that fast reactor design minimizes thermalization, and the NRC training notes sodium is slightly moderating.", null, "C22"],

  // Neutron life cycle and kinetics
  ["Neutron Life Cycle", "Define k-infinity.", "Neutrons produced by fission in one generation divided by neutrons lost to absorption in the preceding generation.", "DOE-1019-V2 (DOE-HDBK-1019/2-93), Neutron Life Cycle, NP-03 p. 2", null, null, "C23"],
  ["Neutron Life Cycle", "Define keff.", "Neutrons produced by fission in one generation divided by neutrons lost to absorption and leakage in the preceding generation.", "DOE-1019-V2 (DOE-HDBK-1019/2-93), Neutron Life Cycle, NP-03 p. 15", null, null, "C24"],
  ["Neutron Life Cycle", "Define critical, subcritical and supercritical.", "Critical: population is steady. Subcritical: population decreases each generation. Supercritical: population increases each generation.", "DOE-1019-V2 (DOE-HDBK-1019/2-93), Neutron Life Cycle, NP-03 p. 15", null, null, "C25"],
  ["Reactor Kinetics and Neutron Sources", "What is the reactor period?", "The time for reactor power to change by a factor of e (2.718).", "DOE-1019-V2 (DOE-HDBK-1019/2-93), Reactor Kinetics, NP-04 p. 11", null, null, "C26"],
  ["Reactor Kinetics and Neutron Sources", "What is doubling time, and how does it relate to the period?", "Time for power to double. It equals ln(2) times the period, about 0.69 times the period.", "DOE-1019-V2 (DOE-HDBK-1019/2-93), Reactor Kinetics, NP-04 p. 21", null, null, "C27"],
  ["Reactor Operational Physics", "What is the reactor startup rate?", "The number of factors of ten that reactor power changes in one minute.", "DOE-1019-V2 (DOE-HDBK-1019/2-93), Reactor Kinetics, NP-04 p. 17", null, null, "C28"],
  ["Reactor Kinetics and Neutron Sources", "What is the effective delayed neutron fraction, beta-eff?", "The average delayed neutron fraction multiplied by an importance factor that accounts for delayed neutrons being born at lower energy.", "DOE-1019-V2 (DOE-HDBK-1019/2-93), Reactor Kinetics, NP-04 p. 21", null, null, "C29"],
  ["Reactor Kinetics and Neutron Sources", "Why do delayed neutrons make reactor power changes controllable?", "They have a long mean generation time compared with prompt neutrons, which lengthens the effective generation time.", "DOE-1019-V1 (DOE-HDBK-1019/1-93), Prompt and Delayed Neutrons, NP-02 p. 31", null, null, "C30"],
  ["Reactor Kinetics and Neutron Sources", "Without delayed neutrons, what happens when positive reactivity is added to a critical reactor?", "Power rises in an uncontrollable way, because prompt neutrons alone give generation times too short for controls to act.", "DOE-1019-V1 (DOE-HDBK-1019/1-93), Prompt and Delayed Neutrons, NP-02 p. 31", null, null, "C31"],
  ["Reactor Kinetics and Neutron Sources", "What is subcritical multiplication?", "Fissions increase the effective source strength of a subcritical core. Steady neutron level N = S / (1 - keff).", "DOE-1019-V2 (DOE-HDBK-1019/2-93), Subcritical Multiplication, NP-04 p. 2", null, null, "C32"],
  ["Reactor Kinetics and Neutron Sources", "How do count rates change with reactivity addition in a subcritical core?", "CR1 / CR2 = (1 - k2) / (1 - k1), so count rate rises as keff approaches 1.", "DOE-1019-V2 (DOE-HDBK-1019/2-93), Subcritical Multiplication, NP-04 p. 9", null, null, "C33"],
  ["Reactor Operational Physics", "What is a 1/M plot used for?", "Predicting the point of criticality during startup, from count rates as rods are withdrawn.", "DOE-1019-V2 (DOE-HDBK-1019/2-93), Subcritical Multiplication, NP-04 p. 7", null, null, "C34"],
  ["Reactor Kinetics and Neutron Sources", "What is an installed source for in a startup?", "It raises the neutron population to a level that can be monitored through the startup, with subcritical multiplication.", "DOE-1019-V2 (DOE-HDBK-1019/2-93), Reactor Operation, NP-04 p. 33", null, null, "C35"],

  // Reactivity
  ["Neutron Life Cycle", "Define reactivity in terms of keff.", "rho = (keff - 1) / keff, the fractional change in neutron population per generation.", "DOE-1019-V2 (DOE-HDBK-1019/2-93), Reactivity, NP-03 p. 18", null, null, "C36"],
  ["Neutron Life Cycle", "How many pcm equal one percent delta k/k?", "1,000 pcm. One pcm is 0.00001 delta k/k.", "DOE-1019-V2 (DOE-HDBK-1019/2-93), Reactivity, NP-03 p. 19", null, null, "C37"],
  ["Reactivity Coefficients", "What is a reactivity coefficient?", "The change in reactivity per unit change in a parameter, such as per degree of temperature.", "DOE-1019-V2 (DOE-HDBK-1019/2-93), Reactivity, NP-03 p. 22", null, null, "C38"],
  ["Reactivity Coefficients", "What is a reactivity defect?", "The total reactivity change from a parameter change: coefficient x size of the change.", "DOE-1019-V2 (DOE-HDBK-1019/2-93), Reactivity, NP-03 p. 22", null, null, "C39"],
  ["Reactivity Coefficients", "Why is a negative temperature coefficient desirable?", "It makes the reactor self-regulating. Higher power raises temperature, which adds negative reactivity and slows the rise.", "DOE-1019-V2 (DOE-HDBK-1019/2-93), Reactivity Coefficients, NP-03 p. 26", null, null, "C40"],
  ["Reactivity Coefficients", "What is the Doppler effect in fuel?", "Resonance absorption peaks broaden as fuel heats up, so fuel captures more neutrons over a wider energy range. This adds negative reactivity.", "DOE-1019-V2 (DOE-HDBK-1019/2-93), Reactivity Coefficients, NP-03 p. 26", null, {"f": "images/doe-1019-v2-np-03-fig3.png", "alt": "Resonance absorption peak at two fuel temperatures: the hotter peak is lower and wider.", "cap": "Figure 3. Effect of Fuel Temperature on Resonance Absorption Peaks. Source: DOE-1019-V2 (DOE-HDBK-1019/2-93), NP-03 p. 27.", "at": "a"}, "C42"],
  ["Reactivity Coefficients", "Which isotopes give the negative fuel temperature feedback near end of core life?", "U-238 and Pu-240, from their resonance absorption (per the NRC bank key).", "DOE-1019-V2 (DOE-HDBK-1019/2-93), Reactivity Coefficients, NP-03 p. 26", null, null, "C43"],

  // Heat transfer and heat generation
  ["Heat Transfer and Heat Exchangers", "State Fourier's law of conduction, in words.", "Conduction heat transfer is proportional to thermal conductivity, the area, and the temperature gradient.", "DOE-1012-V2 (DOE-HDBK-1012/2-92), Heat Transfer Terminology, HT-02 p. 3", null, null, "C45"],
  ["Heat Transfer and Heat Exchangers", "Define heat flux.", "Heat transfer rate divided by the heat transfer area.", "DOE-1012-V2 (DOE-HDBK-1012/2-92), Conduction Heat Transfer, HT-02 p. 17", null, null, "C46"],
  ["Heat Transfer and Heat Exchangers", "What is the convection equation?", "Q = h x A x delta T, where h is the convective heat transfer coefficient.", "DOE-1012-V2 (DOE-HDBK-1012/2-92), Convection Heat Transfer, HT-02 p. 19", null, null, "C47"],
  ["Heat Transfer and Heat Exchangers", "What separates natural from forced convection?", "The term natural convection is used if this motion and mixing is caused by density variations resulting from temperature differences within the fluid. The term forced convection is used if this motion and mixing is caused by an outside force, such as a pump.", "DOE-1012-V2 (DOE-HDBK-1012/2-92), Convection Heat Transfer, HT-02 p. 18", "An earlier answer also named a fan as an example. The handbook names only a pump.", null, "C48"],
  ["Heat Transfer and Heat Exchangers", "What is emissivity?", "A measure of how far a body departs from an ideal black body in emitting radiation.", "DOE-1012-V2 (DOE-HDBK-1012/2-92), Radiation Heat Transfer, HT-02 p. 29", null, null, "C49"],
  ["Heat Transfer and Heat Exchangers", "Which heat exchanger arrangement removes more heat for the same area?", "Counter flow. Parallel flow has a large delta T at the inlet and a small one at the outlet.", "DOE-1012-V2 (DOE-HDBK-1012/2-92), Heat Exchangers, HT-02 p. 39", null, null, "C50"],
  ["Heat Transfer and Heat Exchangers", "What is the heat exchanger equation?", "Q = U x A x delta T_lm, using the log-mean temperature difference.", "DOE-1012-V2 (DOE-HDBK-1012/2-92), Heat Exchangers, HT-02 p. 37", null, null, "C51"],
  ["Heat Exchangers and Condensers", "What is a regenerative heat exchanger?", "One that returns energy to the system, improving efficiency. A non-regenerative one rejects heat to the surroundings.", "DOE-1012-V2 (DOE-HDBK-1012/2-92), Heat Exchangers, HT-02 p. 39", null, null, "C52"],
  ["Core Thermal Limits", "Define linear power density.", "Total thermal power divided by the active length of the fuel rods.", "DOE-1012-V2 (DOE-HDBK-1012/2-92), Heat Generation, HT-02 p. 51", null, null, "C53"],
  ["Core Thermal Limits", "What is the nuclear heat flux hot channel factor?", "The ratio of the maximum heat flux at any location to the average heat flux for the core.", "DOE-1012-V2 (DOE-HDBK-1012/2-92), Heat Generation, HT-02 p. 47", null, null, "C54"],
  ["Core Thermal Limits", "What is the nuclear enthalpy rise hot channel factor?", "The total kW of the fuel rod with the highest total kW, divided by the total kW of an average rod.", "DOE-1012-V2 (DOE-HDBK-1012/2-92), Heat Generation, HT-02 p. 51", null, null, "C55"],
  ["Reactor Operational Physics", "What determines the amount of decay heat after shutdown?", "The reactor's power history. It comes from decay of fission products.", "DOE-1012-V2 (DOE-HDBK-1012/2-92), Decay Heat, HT-02 p. 53", null, null, "C56"],
  ["Thermal Hydraulics", "What are the two general categories of decay heat removal?", "Closed loop systems, which circulate coolant through a heat exchanger, and once-through systems, which inject coolant and discharge it.", "DOE-1012-V2 (DOE-HDBK-1012/2-92), Decay Heat, HT-02 p. 56", null, null, "C57"],
  ["Thermal Hydraulics", "What drives natural circulation?", "Density differences caused by temperature differences. The warm fluid rises and the cold fluid sinks.", "DOE-1012-V3 (DOE-HDBK-1012/3-92), Natural Circulation, HT-03 p. 40", null, null, "C58"],
  ["Thermal Hydraulics", "What three things must be present for natural circulation?", "A heat source, a heat sink (with the source below it), and flowpaths between warm and cold fluid.", "DOE-1012-V3 (DOE-HDBK-1012/3-92), Natural Circulation, HT-03 p. 40", null, null, "C59"],

  // Thermodynamics
  ["Thermodynamic Units and Properties", "Define specific volume and density.", "Specific volume is volume per unit mass. Density is mass per unit volume.", "DOE-1012-V1 (DOE-HDBK-1012/1-92), Thermodynamic Properties, HT-01 p. 3", null, null, "C60"],
  ["Thermodynamic Units and Properties", "What is the difference between intensive and extensive properties?", "Intensive properties do not depend on the amount of mass. Extensive properties vary directly with mass.", "DOE-1012-V1 (DOE-HDBK-1012/1-92), Thermodynamic Properties, HT-01 p. 5", null, null, "C61"],
  ["Thermodynamic Units and Properties", "Convert 100 degrees C to Fahrenheit.", "212 degrees F, using F = 32 + (9/5) C.", "DOE-1012-V1 (DOE-HDBK-1012/1-92), Temperature and Pressure Measurements, HT-01 p. 7", null, null, "C62"],
  ["Thermodynamic Units and Properties", "What is absolute pressure?", "Atmospheric pressure plus gauge pressure: Pabs = Patm + Pgauge.", "DOE-1012-V1 (DOE-HDBK-1012/1-92), Temperature and Pressure Measurements, HT-01 p. 10", null, null, "C63"],
  ["Thermodynamic Units and Properties", "Define specific enthalpy.", "h = u + P x v, where u is specific internal energy, P is pressure and v is specific volume.", "DOE-1012-V1 (DOE-HDBK-1012/1-92), Energy, Work, and Heat, HT-01 p. 18", null, null, "C64"],
  ["Thermodynamic Units and Properties", "What is the difference between sensible and latent heat?", "Sensible heat changes temperature. Latent heat changes phase only.", "DOE-1012-V1 (DOE-HDBK-1012/1-92), Energy, Work, and Heat, HT-01 p. 25", null, null, "C65"],
  ["Thermodynamic Processes", "What are the three system types?", "Isolated (no mass or energy crosses the boundary), closed (only energy crosses), and open (both cross).", "DOE-1012-V1 (DOE-HDBK-1012/1-92), Thermodynamic Systems and Processes, HT-01 p. 27", null, null, "C66"],
  ["Thermodynamic Processes", "What is steady state?", "Properties at any point in the system are constant over time, and neither mass nor energy is accumulating.", "DOE-1012-V1 (DOE-HDBK-1012/1-92), Thermodynamic Systems and Processes, HT-01 p. 30", null, null, "C67"],
  ["Thermodynamic Processes", "State the first law of thermodynamics for a component at steady state.", "Energy is conserved. Energy entering a component equals energy leaving it.", "DOE-1012-V1 (DOE-HDBK-1012/1-92), First Law of Thermodynamics, HT-01 p. 68", null, null, "C68"],
  ["Thermodynamic Cycles", "What is the Carnot efficiency?", "(T_H - T_C) / T_H, with absolute temperatures. It is the maximum possible efficiency for a closed cycle between those temperatures.", "DOE-1012-V1 (DOE-HDBK-1012/1-92), Second Law of Thermodynamics, HT-01 p. 74", null, null, "C69"],
  ["Thermodynamic Processes", "How does an isentropic process appear on a T-s or h-s diagram?", "As a vertical line.", "DOE-1012-V1 (DOE-HDBK-1012/1-92), Second Law of Thermodynamics, HT-01 p. 96", null, null, "C70"],
  ["Thermodynamic Processes", "What is the work for a constant-pressure process?", "W = P x delta V.", "DOE-1012-V1 (DOE-HDBK-1012/1-92), Compression Processes, HT-01 p. 100", null, null, "C71"],

  // Fluid flow and components
  ["Fluid Statics and Dynamics", "What does laminar flow look like in a pipe?", "A parabolic velocity profile, with the average about half the maximum velocity.", "DOE-1012-V3 (DOE-HDBK-1012/3-92), Laminar and Turbulent Flow, HT-03 p. 20", null, {"f": "images/doe-1012-v3-ht-03-fig5.png", "alt": "Velocity profiles in a pipe: a parabola for laminar flow and a flatter curve for turbulent flow, with smooth and rough pipe walls compared.", "cap": "Figure 5. Laminar and Turbulent Flow Velocity Profiles. Source: DOE-1012-V3 (DOE-HDBK-1012/3-92), HT-03 p. 18.", "at": "a"}, "C72"],
  ["Fluid Statics and Dynamics", "What does turbulent flow look like in a pipe?", "A flat profile across the center, with the average close to the centerline velocity.", "DOE-1012-V3 (DOE-HDBK-1012/3-92), Laminar and Turbulent Flow, HT-03 p. 20", null, {"f": "images/doe-1012-v3-ht-03-fig5.png", "alt": "Velocity profiles in a pipe: a parabola for laminar flow and a flatter curve for turbulent flow, with smooth and rough pipe walls compared.", "cap": "Figure 5. Laminar and Turbulent Flow Velocity Profiles. Source: DOE-1012-V3 (DOE-HDBK-1012/3-92), HT-03 p. 18.", "at": "a"}, "C73"],
  ["Fluid Statics and Dynamics", "What is viscosity?", "The fluid property that measures resistance to deforming under shear. For most fluids it falls as temperature rises.", "DOE-1012-V3 (DOE-HDBK-1012/3-92), Laminar and Turbulent Flow, HT-03 p. 19", null, null, "C74"],
  ["Fluid Statics and Dynamics", "What assumptions does Bernoulli's equation make?", "Steady flow with no work done on or by the fluid, no heat transfer, and no change in internal energy.", "DOE-1012-V3 (DOE-HDBK-1012/3-92), Bernoulli’S Equation, HT-03 p. 22", null, null, "C75"],
  ["Fluid Statics and Dynamics", "How does a venturi measure flow?", "Volumetric flow is proportional to the square root of the differential pressure across the venturi.", "DOE-1012-V3 (DOE-HDBK-1012/3-92), Bernoulli’S Equation, HT-03 p. 30", null, null, "C76"],
  ["Fluid Statics and Dynamics", "What is head loss?", "The reduction in total head (potential, velocity and pressure) caused by friction in the fluid's motion.", "DOE-1012-V3 (DOE-HDBK-1012/3-92), Head Loss, HT-03 p. 36", null, null, "C77"],
  ["Fluid Statics and Dynamics", "What causes minor losses?", "Bends, elbows, joints, valves and any change in direction or cross-section.", "DOE-1012-V3 (DOE-HDBK-1012/3-92), Head Loss, HT-03 p. 36", null, null, "C78"],
  ["Fluid Statics and Dynamics", "How is the friction factor found for pipe flow?", "From a Moody chart, using Reynolds number and relative roughness.", "DOE-1012-V3 (DOE-HDBK-1012/3-92), Head Loss, HT-03 p. 36", null, null, "C79"],
  ["Thermal Hydraulics", "What are the three types of two-phase flow?", "Bubbly (vapor bubbles in liquid), slug (coalesced bullet-shaped bubbles), and annular (a liquid film on the wall with droplets in a vapor core).", "DOE-1012-V3 (DOE-HDBK-1012/3-92), Two-Phase Fluid Flow, HT-03 p. 46", null, null, "C80"],
  ["Pumps", "What is net positive suction head?", "The difference between pump suction pressure and the saturation pressure of the fluid.", "DOE-1012-V3 (DOE-HDBK-1012/3-92), Centrifugal Pumps, HT-03 p. 56", null, null, "C81"],
  ["Pumps", "What is cavitation?", "Vapor bubbles form when local pressure drops below saturation, then collapse on the impeller as pressure recovers.", "DOE-1012-V3 (DOE-HDBK-1012/3-92), Centrifugal Pumps, HT-03 p. 56", null, null, "C82"],
  ["Pumps", "Using the pump laws, what happens to flow, head and power when pump speed doubles?", "Flow doubles, head quadruples, and power goes up eightfold.", "DOE-1012-V3 (DOE-HDBK-1012/3-92), Centrifugal Pumps, HT-03 p. 49", null, null, "C83"],
  ["Pumps", "What happens when two identical centrifugal pumps run in parallel? In series?", "Parallel: flows add at a given head. Series: heads add at a given flow.", "DOE-1012-V3 (DOE-HDBK-1012/3-92), Centrifugal Pumps, HT-03 p. 56", null, {"f": "images/doe-1012-v3-ht-03-fig13.png", "alt": "Curves for one pump and two pumps in series: at each flow, the series curve has twice the head.", "cap": "Figure 13. Pump Characteristic Curve for Two Identical Centrifugal Pumps Used in Series. Source: DOE-1012-V3 (DOE-HDBK-1012/3-92), HT-03 p. 54.", "at": "a"}, "C84"],
  ["Valves", "What are the four basic ways a valve controls flow?", "Moving a disc or plug against an orifice (globe, needle), sliding a surface across it (gate, plug), rotating a disc (butterfly, ball), or moving a flexible material into the passage (diaphragm, pinch).", "DOE-1018-V2 (DOE-HDBK-1018/2-93), Valve Functions and Basic Parts, ME-04 p. 6", null, null, "C85"],
  ["Valves", "When is a gate valve used?", "When a fully open path with low resistance is needed and the flow does not need throttling.", "DOE-1018-V2 (DOE-HDBK-1018/2-93), Types of Valves, ME-04 p. 43", null, null, "C86"],
  ["Valves", "When is a globe valve used?", "When good throttling and low seat leakage are needed, and a higher head loss when open is acceptable.", "DOE-1018-V2 (DOE-HDBK-1018/2-93), Types of Valves, ME-04 p. 43", null, null, "C87"],
  ["Valves", "What does a check valve do?", "Opens automatically to allow flow in one direction and seats to prevent reverse flow.", "DOE-1018-V2 (DOE-HDBK-1018/2-93), Types of Valves, ME-04 p. 43", null, null, "C88"],
  ["Valves", "What is the function of a safety/relief valve?", "Automatic overpressure protection for a system.", "DOE-1018-V2 (DOE-HDBK-1018/2-93), Types of Valves, ME-04 p. 43", null, null, "C89"],
  ["Valves", "What are the five common valve actuator types?", "Manual (handwheel), electric motor, pneumatic (air on a diaphragm), hydraulic (liquid on a piston), and solenoid.", "DOE-1018-V2 (DOE-HDBK-1018/2-93), Valve Actuators, ME-04 p. 50", null, null, "C90"],
  ["Heat Exchangers and Condensers", "What are the three heat exchanger flow arrangements?", "Parallel flow (same direction), counter flow (opposite directions), and cross flow (90 degrees).", "DOE-1018-V1 (DOE-HDBK-1018/1-93), Types of Heat Exchangers, ME-02 p. 11", null, null, "C91"],
  ["Heat Exchangers and Condensers", "What is the difference between single-pass and multi-pass heat exchangers?", "Single-pass fluids cross each other once. Multi-pass fluids cross more than once, using U-tubes and baffles.", "DOE-1018-V1 (DOE-HDBK-1018/1-93), Types of Heat Exchangers, ME-02 p. 11", null, {"f": "images/doe-1018-v1-me-02-fig6.png", "alt": "Single-pass unit with straight tubes, and multi-pass unit with fluid reversing through U bends and shell baffles.", "cap": "Figure 6. Single and Multi-Pass Heat Exchangers. Source: DOE-1018-V1 (DOE-HDBK-1018/1-93), ME-02 p. 9.", "at": "a"}, "C92"],
  ["Heat Exchangers and Condensers", "What is the purpose of a condenser?", "Remove latent heat, condensing vapor to liquid. Condensers run under vacuum to maximize the temperature difference and efficiency.", "DOE-1018-V1 (DOE-HDBK-1018/1-93), Heat Exchanger Applications, ME-02 p. 18", null, null, "C93"],
  ["Motors and Generators", "How many crankshaft rotations does a four-stroke diesel take per cycle?", "Two: intake and compression on the first, power and exhaust on the second.", "DOE-1018-V1 (DOE-HDBK-1018/1-93), Diesel Engines, ME-01 p. 28", null, null, "C94"],
  ["Motors and Generators", "How does a diesel engine ignite its fuel?", "Fuel is injected into air heated by compression above the fuel's ignition temperature.", "DOE-1018-V1 (DOE-HDBK-1018/1-93), Diesel Engines, ME-01 p. 28", null, null, "C95"],
  // Added 2026-11-01 from DOE-HDBK-1019 (Nuclear Physics and Reactor Theory)
  ["Neutrons", "What is internal conversion?", "A gamma ray emitted by an excited nucleus interacts with one of the innermost electrons of the same atom, and that electron is ejected.", "DOE-HDBK-1019/1-93, Modes of Radioactive Decay, NP-01 p. 29", null, null, "C96"],
  ["Neutrons", "What is pair production, and what gamma energy does it require?", "A gamma ray interacts with the electric field of a nucleus and is converted into an electron-positron pair. The gamma must have more than 1.02 MeV.", "DOE-HDBK-1019/1-93, Interaction of Radiation with Matter, NP-01 p. 67", null, null, "C97"],
  ["Neutrons", "What is critical energy in fission?", "The minimum excitation energy a nucleus must have before it can fission.", "DOE-HDBK-1019/1-93, Nuclear Fission, NP-01 p. 55", null, null, "C98"],
  ["Neutrons", "What is fertile material?", "Material that can undergo transmutation to become fissile material.", "DOE-HDBK-1019/1-93, Nuclear Fission, NP-01 p. 55", null, null, "C99"],
  ["Neutrons", "What is self-shielding?", "Depression of the local neutron flux inside a material because neutrons are absorbed near its surface.", "DOE-HDBK-1019/1-93, Nuclear Cross Sections and Neutron Flux, NP-02 p. 17", null, null, "C101"],
  ["Control Rods", "What is differential control rod worth, and where in the core is it highest?", "The reactivity change per unit movement of a control rod. It is highest at the center of the core, where neutron flux is highest, giving a bell-shaped curve.", "DOE-HDBK-1019/2-93, Control Rods, NP-03 p. 58", null, null, "C102"],
  ["Reactor Kinetics and Neutron Sources", "How much positive reactivity, in dollars, makes a reactor prompt critical?", "One dollar. That is why measuring reactivity in dollars is useful for judging whether a reactor is prompt critical.", "DOE-HDBK-1019/2-93, Reactor Kinetics, NP-04 p. 22", null, null, "C103"],
  ["Reactor Kinetics and Neutron Sources", "What is prompt jump?", "The small, immediate power increase after a positive reactivity insertion, caused by the increase in the prompt neutron population.", "DOE-HDBK-1019/2-93, Reactor Kinetics, NP-04 p. 22", null, null, "C104"],
  ["Neutron Life Cycle", "Why is the stuck rod criterion applied to shutdown margin?", "To ensure that the failure of a single control rod will not prevent the control rod system from shutting down the reactor.", "DOE-HDBK-1019/2-93, Reactor Operation, NP-04 p. 34", null, null, "C105"],
  ["Reactor Operational Physics", "What three methods are used to shape or flatten core power distribution?", "Reflectors, neutron poisons, and axial or radial variation of fuel enrichment.", "DOE-HDBK-1019/2-93, Reactor Operation, NP-04 p. 34", null, null, "C106"],
  ["Reactor Operational Physics", "What is power tilt?", "A non-symmetrical variation of core power in one quadrant of the core relative to the other quadrants.", "DOE-HDBK-1019/2-93, Reactor Operation, NP-04 p. 34", null, null, "C107"],
  // Added 2026-11-01 from DOE-HDBK-1012 (Thermodynamics, Heat Transfer, and Fluid Flow)
  ["Thermodynamic Processes", "What is an adiabatic process?", "A process in which there is no heat transfer across the system boundaries.", "DOE-HDBK-1012/1-92, Thermodynamic Systems and Processes, HT-01 p. 30", null, null, "C108"],
  ["Thermodynamic Processes", "What is a control volume?", "A fixed region of space that is studied as a thermodynamic system.", "DOE-HDBK-1012/1-92, Thermodynamic Systems and Processes, HT-01 p. 30", null, null, "C109"],
  ["Basic Energy Concepts", "State Planck's statement of the Second Law of Thermodynamics.", "It is impossible to build an engine that works in a complete cycle and produces no other effect except raising a weight and cooling a heat reservoir.", "DOE-HDBK-1012/1-92, Second Law of Thermodynamics, HT-01 p. 70", null, null, "C110"],
  ["Heat Transfer and Heat Exchangers", "What does the Second Law of Thermodynamics imply about the direction of heat transfer?", "Heat will not transfer from a colder body to a hotter body without some external source of energy.", "DOE-HDBK-1012/2-92, Heat Transfer Terminology, HT-02 p. 5", null, null, "C111"],
  ["Heat Transfer and Heat Exchangers", "What is the bulk temperature of a fluid?", "The temperature that best represents the majority of the fluid, which is not physically connected to the heat transfer site.", "DOE-HDBK-1012/2-92, Heat Transfer Terminology, HT-02 p. 5", null, null, "C112"],
  ["Thermal Hydraulics", "What is the average volumetric thermal source strength?", "The heat generation rate divided by the volume of fuel.", "DOE-HDBK-1012/2-92, Heat Generation, HT-02 p. 50", null, null, "C113"],
  ["Heat Transfer and Heat Exchangers", "What does the radiation configuration factor account for?", "The emittance and relative geometry of two objects.", "DOE-HDBK-1012/2-92, Radiant Heat Transfer, HT-02 p. 29", null, null, "C114"],
  ["Heat Transfer and Heat Exchangers", "What does the local heat transfer coefficient measure?", "The ability to transfer heat through a stagnant film layer.", "DOE-HDBK-1012/2-92, Heat Transfer Terminology, HT-02 p. 5", null, null, "C115"],
  ["Fluid Statics and Dynamics", "What does Pascal's law state?", "Pressure applied to a confined fluid is transmitted undiminished throughout the confining vessel of a system.", "DOE-HDBK-1012/3-92, Continuity Equation, HT-03 p. 16", null, null, "C116"],
  ["Fluid Statics and Dynamics", "What is an ideal fluid?", "A fluid that is incompressible and has no viscosity.", "DOE-HDBK-1012/3-92, Laminar and Turbulent Flow, HT-03 p. 19", null, null, "C117"],
  ["Fluid Statics and Dynamics", "In fluid systems, what is head?", "The term used to describe pressure exerted on or by a fluid.", "DOE-HDBK-1012/3-92, Bernoulli’s Equation, HT-03 p. 30", null, null, "C118"],
  ["Fluid Statics and Dynamics", "What is frictional loss?", "The part of the total head loss that occurs as fluid flows through straight pipes.", "DOE-HDBK-1012/3-92, Head Loss, HT-03 p. 31", null, null, "C119"],
  ["Thermal Hydraulics", "What is thermal driving head?", "The driving force for natural circulation, caused by the difference in density between two areas of fluid.", "DOE-HDBK-1012/3-92, Natural Circulation, HT-03 p. 40", null, null, "C120"],
  ["Fluid Statics and Dynamics", "How do density changes in a fluid relate to temperature changes?", "They are inversely proportional: as temperature rises, density falls.", "DOE-HDBK-1012/3-92, Continuity Equation, HT-03 p. 16", null, null, "C121"],
  // Added 2026-11-01 from DOE-HDBK-1018 (Mechanical Science)
  ["Pumps", "What is the shutoff head of a centrifugal pump?", "The maximum head the pump can develop while operating at a set speed.", "DOE-HDBK-1018/1-93, Centrifugal Pump Operation, ME-03 p. 14", null, {"f": "images/doe-1018-v1-me-03-fig11.png", "alt": "Pump head against flow: head is highest at zero flow, at shutoff head, and falls in a downward curve to the runout flow.", "cap": "Figure 11. Centrifugal Pump Characteristic Curve. Source: DOE-1018-V1 (DOE-HDBK-1018/1-93), ME-03 p. 14.", "at": "a"}, "C122"],
  ["Pumps", "What are three indications that a centrifugal pump is cavitating?", "Noise, fluctuating discharge pressure and flow, and fluctuating pump motor current.", "DOE-HDBK-1018/1-93, Centrifugal Pump Operation, ME-03 p. 16", null, null, "C123"],
  ["Pumps", "What is slippage in a positive displacement pump?", "The rate at which liquid leaks from the pump discharge back to the pump suction.", "DOE-HDBK-1018/1-93, Positive Displacement Pumps, ME-03 p. 28", null, {"f": "images/doe-1018-v1-me-03-fig21.png", "alt": "Pump head against flow rate: the ideal curve is a vertical line, and the real curve leans toward lower flow at high head, showing slippage.", "cap": "Figure 21. Positive Displacement Pump Characteristic Curve. Source: DOE-1018-V1 (DOE-HDBK-1018/1-93), ME-03 p. 27.", "at": "a"}, "C124"],
  ["Pumps", "How is a positive displacement pump protected from overpressurization?", "By a relief valve on the upstream side of the pump discharge valve.", "DOE-HDBK-1018/1-93, Positive Displacement Pumps, ME-03 p. 28", null, null, "C125"],
  ["Pumps", "What does the volute of a centrifugal pump do?", "It collects liquid leaving the impeller at high velocity and slows it by increasing the flow area, converting velocity head to static head.", "DOE-HDBK-1018/1-93, Centrifugal Pumps, ME-03 p. 10", null, {"f": "images/doe-1018-v1-me-03-fig10.png", "alt": "Pump cross section labeling the casing, shaft, impeller, volute, stuffing box, gland, packing, lantern ring, and impeller and casing wearing rings.", "cap": "Figure 10. Centrifugal Pump Components. Source: DOE-1018-V1 (DOE-HDBK-1018/1-93), ME-03 p. 8.", "at": "a"}, "C126"],
  ["Motors and Generators", "What protective alarms and trips do most mid-sized to large diesel engines have, as a minimum?", "Engine overspeed alarm/trip, high water jacket temperature alarm, high exhaust temperature alarm, low lube oil pressure alarm and/or trip, and high crankcase pressure alarm.", "DOE-HDBK-1018/1-93, Diesel Engine Speed, Fuel Controls, and Protection, ME-01 p. 40", null, null, "C127"],
  ["Heat Exchangers and Condensers", "How do regenerative and non-regenerative heat exchangers differ in the fluids they use?", "Regenerative heat exchangers use the same fluid for heating and cooling. Non-regenerative heat exchangers use separate fluids.", "DOE-HDBK-1018/1-93, Types of Heat Exchangers, ME-02 p. 11", null, {"f": "images/doe-1018-v1-me-02-fig7.png", "alt": "Two process diagrams: in the regenerative unit the outgoing fluid heats the returning fluid, and in the non-regenerative unit a separate cooling system removes the heat.", "cap": "Figure 7. Regenerative and Non-Regenerative Heat Exchangers. Source: DOE-1018-V1 (DOE-HDBK-1018/1-93), ME-02 p. 10.", "at": "a"}, "C128"],
  ["Valves", "What is a stop check valve?", "A combination of a lift check valve and a globe valve that has the characteristics of both.", "DOE-HDBK-1018/2-93, Types of Valves, ME-04 p. 43", null, null, "C129"],
  ["Valves", "When are diaphragm and pinch valves used?", "In systems where the entire operating mechanism should be completely isolated from the fluid.", "DOE-HDBK-1018/2-93, Types of Valves, ME-04 p. 43", null, null, "C130"],
  ["Valves", "What advantages do butterfly valves offer?", "Significant advantages in weight, space, and cost for large valve applications.", "DOE-HDBK-1018/2-93, Types of Valves, ME-04 p. 43", null, null, "C131"],
  ["Valves", "How is valve stem leakage usually controlled?", "By properly compressing the packing around the valve stem.", "DOE-HDBK-1018/2-93, Valve Functions and Basic Parts, ME-04 p. 7", null, null, "C132"],
  ["Thermodynamic Processes", "What are the advantages of cooling compressed air?", "Cool air takes less space and holds less moisture, which reduces corrosion and allows more air to be compressed into a given volume.", "DOE-HDBK-1018/2-93, Air Compressors, ME-05 p. 9", null, null, "C133"],
  ["Demineralizers and Ion Exchangers", "What is a duplex strainer, and why is it used in fuel oil and lube oil lines?", "Two sides with a basket in each, only one in service at a time. Flow can be shifted to the other basket while one is cleaned, so oil flow is never interrupted.", "DOE-HDBK-1018/2-93, Filters and Strainers, ME-05 p. 48", null, null, "C134"],
  // Added 2026-11-01 from ML24088A065 (Kemmerer Unit 1 PSAR, Rev. 0)
  ["PSAR: Fundamental Safety Functions", "How are Natrium Energy Island SSCs (salt storage tanks, steam generator, turbine) safety-classified?", "Non-safety-related with no special treatment (NST).", "PSAR Rev 1, ML25276A288, Sec. 1.1.3, p. 1.1-2", null, null, "C135"],
  ["PSAR: Fundamental Safety Functions", "For the fuel, what is the first safety-related radionuclide retention barrier in the Natrium functional containment strategy?", "The fuel cladding.", "PSAR Rev 1, ML25276A288, Sec. 1.3.2.1, p. 1.3-2", null, null, "C136"],
  ["PSAR: Nuclear Heat Supply Systems", "What protects the Natrium reactor from sodium-air reactions if the reactor vessel leaks?", "The inert gas-filled annulus between the reactor vessel and the guard vessel.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.1.2, p. 1.1-3", null, null, "C137"],
  ["PSAR: Reactor Auxiliary Systems", "How is sodium leakage from the reactor vessel into the guard vessel detected?", "Argon in the RV-GV annulus is recirculated and monitored for sodium buildup through absolute filter differential pressure changes, oxygen concentration, and radiation levels.", "PSAR Rev 1, ML25276A288, Sec. 7.2.3.2.1, p. 7.2-28", null, null, "C138"],
  ["PSAR: Fundamental Safety Functions", "What inherent property keeps the Natrium core covered by subcooled sodium during licensing basis events?", "The high boiling point of sodium, which keeps the core covered by subcooled sodium at near-atmospheric pressure.", "PSAR Rev 1, ML25276A288, Sec. 1.3.2.1, p. 1.3-3", null, null, "C139"],
  ["PSAR: Reactor Auxiliary Systems", "What actuation or operator action does the Reactor Air Cooling System need to remove decay heat?", "None. It is continuously in operation and needs no automatic or manual actuation or operator action.", "PSAR Rev 1, ML25276A288, Sec. 7.2.1.1, p. 7.2-1", null, null, "C140"],
  ["PSAR: Reactor Auxiliary Systems", "How does heat get from the reactor vessel into the Reactor Air Cooling System air?", "The reactor vessel radiates heat across the argon gap to the guard vessel. The guard vessel convects heat to the air and also radiates to the collector cylinder, which convects heat to the air.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.1.3, p. 1.1-4", null, null, "C141"],
  ["PSAR: Reactor Auxiliary Systems", "How many control rod drive mechanisms and control rod assemblies does the Natrium Control Rod Drive System have?", "Thirteen CRDMs, controlling nine primary and four secondary control rod assemblies.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.1.9, p. 1.1-6", null, null, "C142"],
  ["PSAR: Fundamental Safety Functions", "Under PDC 11, what must the net effect of prompt inherent nuclear feedback do in the power operating range?", "Tend to compensate for a rapid increase in reactivity.", "PSAR Rev 1, ML25276A288, Sec. 3.12.2, p. 3.12-3", null, null, "C143"],
  ["PSAR: Integrated Controls Systems", "Are the Natrium RPS manual scram and ESF actuation functions credited in the safety analysis?", "No. They can be initiated from the Main Control Room and are diverse from the automatic RPS logic, but they are not credited in the safety analysis.", "PSAR Rev 1, ML25276A288, Sec. 7.6.3.1, p. 7.6-18", null, null, "C144"],
  ["PSAR: Nuclear Heat Supply Systems", "What protects the reactor vessel from overfill if an intermediate heat exchanger leaks?", "An intermediate sodium pump trip initiated by abnormal level in the IHT expansion tank or in the primary sodium pool.", "PSAR Rev 1, ML25276A288, Sec. 7.1.4.3, p. 7.1-81", null, null, "C145"],
  ["PSAR: Fundamental Safety Functions", "What sources of decay heat does the Natrium decay heat generation rate methodology include?", "Fission products, activated non-fissionable materials, and actinides produced within the fuel.", "PSAR Rev 1, ML25276A288, Sec. 3.12.1.5, p. 3.12-2", null, null, "C146"],
  ["PSAR: Reactor Auxiliary Systems", "In the primary Sodium Processing System, what do the cold traps and the cesium trap remove?", "Cold traps remove oxides and hydrogen impurities. The cesium trap removes cesium released to the coolant from fuel pin failures.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.1.8, p. 1.1-6", null, null, "C147"],
  ["PSAR: Nuclear Heat Supply Systems", "What type of reactor is Kemmerer Unit 1, and what is its thermal power?", "An 840 MWt pool-type sodium fast reactor (SFR).", "PSAR Rev 1, ML25276A288, Sec. 1.1.3, p. 1.1-1", null, null, "C148"],
  // Introduction (ML19148A756)
  ["Thermal Hydraulics", "Why don't liquid-metal-cooled fast reactors need a high-pressure injection system?", "Their heat transport systems are unpressurized, so there is no LOCA and no need for high-pressure injection.", "ML19148A756, Introduction, slide 7", null, null, "C149"],
  ["Thermal Hydraulics", "What core coolant temperature rise does the NRC training give for SFRs, and why does it matter for natural circulation?", "About 150 °C in normal operation (over 300 °C in accidents). This gives a significant sodium inlet/outlet density difference and a large buoyancy force.", "ML19148A756, Introduction, slide 7", null, null, "C150"],
  ["Reactor Operational Physics", "What is the key concept on which all fast reactor safety is based?", "Defense in depth.", "ML19148A756, Introduction, slide 9", null, null, "C151"],
  // Historical Perspective for Fast Reactors (ML19148A764)
  ["Reactor Operational Physics", "Which reactor generated the first ever electrical power, and where did that power go?", "EBR-I. It fed into the power system for Arco, Idaho.", "ML19148A764, Historical Perspective for Fast Reactors, slide 2", null, null, "C152"],
  ["Reactor Operational Physics", "How many commercial SFRs has the United States operated?", "One: Fermi-1.", "ML19148A764, Historical Perspective for Fast Reactors, slide 5", null, null, "C153"],
  // Fast Reactor Physics 1 (ML19148A793)
  ["Neutrons", "At what energy does U-238 threshold fission begin, and how much of fast reactor fission does it supply?", "About 1 MeV. It supplies about 10% of the total fission rate in a fast reactor.", "ML19148A793, Fast Reactor Physics 1, slide 8", null, null, "C156"],
  ["Neutrons", "How does the neutron diffusion length in a fast reactor compare with an LWR, and what follows from it?", "About 10-20 cm, compared with 2 cm in an LWR, because all materials have lower absorption cross sections. Neutron leakage increases (over 20% in typical designs).", "ML19148A793, Fast Reactor Physics 1, slide 14", null, null, "C157"],
  ["Thermal Hydraulics", "Typical coolant pressure and outlet temperature: PWR vs SFR?", "PWR about 15.5 MPa and 329 °C outlet. SFR about 0.1 MPa and 499 °C outlet.", "ML19148A793, Fast Reactor Physics 1, slide 16", null, null, "C158"],
  // Fast Reactor Physics 2 (ML19148A801)
  ["Reactor Kinetics and Neutron Sources", "Why does a low delayed neutron fraction matter?", "It indicates sensitivity: at low values, the response to small reactivity changes is magnified and power can change more quickly.", "ML19148A801, Fast Reactor Physics 2, slide 5", null, null, "C159"],
  ["Reactivity Coefficients", "What does axial fuel expansion do to control rod reactivity in a fast reactor?", "It effectively inserts the control rods, which remain stationary.", "ML19148A801, Fast Reactor Physics 2, slide 6", null, null, "C160"],
  ["Reactivity Coefficients", "What is the main source of the fast reactor Doppler coefficient?", "U-238 resonance broadening. It is enhanced by high U-238 content and reduced in high-enrichment burner designs.", "ML19148A801, Fast Reactor Physics 2, slide 8", null, null, "C161"],
  ["Reactivity Coefficients", "What are the three components of the sodium density reactivity effect in a fast reactor?", "Spectral (less moderation; positive in the fast regime), leakage (more leakage; negative in peripheral regions), and capture (less sodium capture; relatively minor).", "ML19148A801, Fast Reactor Physics 2, slide 10", null, null, "C162"],
  ["Thermal Hydraulics", "Why is it hard to conceive SFR transients that reach sodium boiling?", "Low pressure system, over 300 °C margin to boiling, and other feedbacks are negative on the way to voiding.", "ML19148A801, Fast Reactor Physics 2, slide 12", null, null, "C163"],
  // Fast Reactor Fuels (ML19149A371)
  ["Core Thermal Limits", "What fills the fuel-cladding gap and the fission gas plenum in SFR oxide and metal fuel?", "Oxide fuel: helium in the gap; plenum helium-filled when made. Metal fuel: sodium in the gap; plenum argon-filled when made.", "ML19149A371, Fast Reactor Fuels, slide 4", null, null, "C164"],
  ["Core Thermal Limits", "What does fuel-cladding chemical interaction (FCCI) limit in a metallic fuel core?", "It puts an operational limit on coolant outlet temperature.", "ML19149A371, Fast Reactor Fuels, slide 11", null, null, "C165"],
  ["Core Thermal Limits", "Why do damaged metal fuel pins remain coolable?", "Metal fuel cladding generally fails below the coolant boiling point.", "ML19149A371, Fast Reactor Fuels, slide 22", null, null, "C166"],
  ["Core Thermal Limits", "How do oxide and metal fuel differ in compatibility with sodium coolant?", "Oxide fuel chemically reacts with sodium. Metal fuel is compatible with sodium, so minor clad failures can be tolerated.", "ML19149A371, Fast Reactor Fuels, slide 22", null, null, "C167"],
  ["Core Thermal Limits", "Which has more margin to melting during accidents, oxide or metal fuel?", "They are similar, despite the big difference in melting point.", "ML19149A371, Fast Reactor Fuels, slide 22", null, null, "C168"],
  // SFR Technology Overview (ML19149A378)
  ["Reactor Operational Physics", "In a pool-type SFR, what sits in the sodium pool, and what does that do for leaks?", "The core, primary piping, IHX and primary pumps. Primary coolant stays within the reactor vessel, which much reduces the risk of leaks.", "ML19149A378, SFR Technology Overview, slide 5", null, null, "C169"],
  ["Reactor Operational Physics", "What does the guard vessel do in an SFR?", "If the reactor vessel fails, the guard vessel wraps it and keeps the sodium level high enough to keep the core covered and decay heat removal working.", "ML19149A378, SFR Technology Overview, slide 12", null, null, "C170"],
  ["Thermal Hydraulics", "What are typical SFR core outlet temperatures and margins to boiling?", "About 500-550 °C, depending on cladding material, with a margin to boiling of 330-380 °C.", "ML19149A378, SFR Technology Overview, slide 14", null, null, "C171"],
  ["Pumps", "Why can SFRs use electromagnetic pumps, and what extra feature do they need?", "Sodium has very high electrical conductivity. They need a supplementary flow coastdown feature (such as an inertia-driven generator) to avoid an abrupt stop in loss-of-flow accidents.", "ML19149A378, SFR Technology Overview, slide 15", null, null, "C172"],
  ["Sensors and Detectors", "Why are SFR flux detectors usually outside the reactor vessel?", "It is feasible because fast neutrons have a longer mean free path, and it protects the instruments from irradiation damage.", "ML19149A378, SFR Technology Overview, slide 23", null, null, "C173"],
  ["Sensors and Detectors", "How is failed fuel detected and located in an SFR?", "Detected by sensing fission products (xenon isotopes) in the cover gas. Located by gas tagging, with unique xenon and krypton mixtures for each subassembly set.", "ML19149A378, SFR Technology Overview, slide 25", null, null, "C174"],
  ["Reactor Operational Physics", "Why is nitrogen used to inert sodium cells but argon used as cover gas inside vessels?", "Nitrogen isn't suitable above 400 °C because of nitriding problems with steel. Argon does not react with structural materials and is inexpensive.", "ML19149A378, SFR Technology Overview, slide 26", null, null, "C175"],
  ["Sensors and Detectors", "Why is sodium leak detection important?", "Primary sodium is radioactive, liquid sodium burns in air, and loss of sodium could impair heat transport systems.", "ML19149A378, SFR Technology Overview, slide 25", null, null, "C176"],
  ["Thermal Hydraulics", "How is normal shutdown heat removed in an SFR, and what backs it up?", "Through the balance of plant, diverting steam from the turbine to a heat sink via a bypass (usually not safety-grade). If that path is unavailable, redundant safety-grade decay heat removal systems take over.", "ML19149A378, SFR Technology Overview, slide 18", null, null, "C177"],
  // Operational Considerations (ML19149A433)
  ["Demineralizers and Ion Exchangers", "Why are cesium traps needed in addition to cold traps?", "Cold traps are inefficient at removing cesium, an alkali metal like sodium. Carbon (RVC) or graphite filters have been used to capture it.", "ML19149A433, Operational Considerations, slide 11", null, null, "C178"],
  ["Sensors and Detectors", "What typically recognizes when a fuel pin failure has occurred in an SFR?", "Delayed neutron detectors sampling the cover gas, detecting xenon and krypton.", "ML19149A433, Operational Considerations, slide 17", null, null, "C179"],
  ["Brittle Fracture and Vessel Thermal Stress", "What is the 'leak before break' idea for SFR sodium piping?", "Because the systems are at low pressure, sodium leaks are generally small and can be detected before larger piping breaks occur.", "ML19149A433, Operational Considerations, slide 21", null, null, "C180"],
  ["Heat Exchangers and Condensers", "What happens when a sodium/water reaction is detected in a steam generator?", "Steam generator isolation valves close on both the sodium and water sides, and the contents are discharged to a dump tank. Rupture disks relieve pressure spikes to protect intermediate piping such as the IHX.", "ML19149A433, Operational Considerations, slide 25", null, null, "C181"],
  ["Thermal Hydraulics", "Why can thermal stratification occur in sodium systems, and why does it matter?", "Even with sodium's high thermal conductivity, stratification can occur at low flow. It can affect heat transfer in heat exchangers and the development of natural circulation.", "ML19149A433, Operational Considerations, slide 27", null, null, "C182"],
  ["Core Thermal Limits", "What is the cumulative damage fraction (CDF) used in metal fuel criteria?", "A method for predicting creep failure at elevated temperature. It is not a probability of failure; failure is assumed when CDF = 1.0 on average.", "ML19149A433, Operational Considerations, slide 8", null, null, "C183"],
  // Sodium Technology Infrastructure (ML19149A388)
  ["Sensors and Detectors", "Why is ultrasonic waveguide technology being developed for sodium reactor inspection?", "Molten sodium is opaque. Ultrasonic waveguides suit opaque liquid metals and high-temperature, corrosive, radioactive media.", "ML19149A388, Sodium Technology Infrastructure, slide 9", null, null, "C184"],
  // Overview of Past U.S. SFR Operations Experience (ML19149A438)
  ["Core Thermal Limits", "What assembly design lesson came from the Fermi-1 fuel melting?", "Inlet nozzles since Fermi-1 have multiple coolant inlet passages, so complete external blockage is 'impossible' by design.", "ML19149A438, Overview of Past U.S. SFR Operations Experience, slide 8", null, null, "C185"],
  ["Reactivity Coefficients", "What did the SEFOR reactor confirm about reactivity feedback?", "Core thermal expansion provides negative reactivity feedback during a transient.", "ML19149A438, Overview of Past U.S. SFR Operations Experience, slide 4", null, null, "C186"],
  ["Heat Exchangers and Condensers", "Where did the PFR steam generator gas-space leaks originate?", "All of them at the welds between the tubes and the tubeplates.", "ML19149A438, Overview of Past U.S. SFR Operations Experience, slide 13", null, null, "C187"],
  ["Heat Exchangers and Condensers", "What caused cracks in Phenix's 304 stainless steel steam generators?", "Thermal striping.", "ML19149A438, Overview of Past U.S. SFR Operations Experience, slide 15", null, null, "C188"],
  ["Sensors and Detectors", "What caused the 1995 Monju sodium leak?", "Flow-induced vibration in a thermowell caused an intermediate sodium leak spilling several hundred kilograms of sodium.", "ML19149A438, Overview of Past U.S. SFR Operations Experience, slide 20", null, null, "C189"],
  // U.S. SFR Testing Experience (ML19149A534)
  ["Reactivity Coefficients", "What was EBR-II's landmark inherent safety demonstration test?", "A station blackout without scram on April 3, 1986, from full power and full flow.", "ML19149A534, U.S. SFR Testing Experience, slide 6", null, null, "C190"],
  ["Reactivity Coefficients", "How does a gas expansion module (GEM) reduce reactivity?", "It is an empty assembly sealed at the top and open at the bottom. With pumps on, sodium rises above the core. When the pumps stop, the level drops, and the sodium displacement increases neutron leakage.", "ML19149A534, U.S. SFR Testing Experience, slide 8", null, null, "C191"],
  ["Core Thermal Limits", "Below about what temperature was no liquid-phase fuel-cladding interaction seen in metal fuel furnace tests?", "About 700-725 °C.", "ML19149A534, U.S. SFR Testing Experience, slide 13", null, null, "C192"],
  // Fast Reactor Safety Design Approach (ML19149A590)
  ["Reactor Operational Physics", "What replaced the LWR-focused Appendix A GDC for SFRs?", "SFR design criteria developed by DOE and NRC, incorporated into ANS standard 54.1, and used as the basis for the SFR-DC in Reg. Guide 1.232.", "ML19149A590, Fast Reactor Safety Design Approach, slide 2", null, null, "C193"],
  ["Reactor Operational Physics", "What do U.S. SFR design principles say about the intermediate coolant?", "Use sodium-compatible materials and keep it at higher pressure than the primary coolant.", "ML19149A590, Fast Reactor Safety Design Approach, slide 4", null, null, "C194"],
  ["Reactor Operational Physics", "What must SFR designs prevent sodium from contacting, and how?", "Air, water, or concrete. Monitor for sodium leaks and provide sodium fire protection.", "ML19149A590, Fast Reactor Safety Design Approach, slide 4", null, null, "C195"],
  // Fast Reactor Safety (ML19149A618)
  ["Reactor Operational Physics", "What is an 'unprotected' event in SFR safety analysis?", "A DBA combined with failure of the reactor shutdown system, such as ULOF, UTOP or ULOHS.", "ML19149A618, Fast Reactor Safety, slide 28", null, null, "C197"],
  ["Thermal Hydraulics", "How does the margin to coolant boiling in an SFR compare with a PWR?", "About 350 °C in an SFR versus about 20 °C in a PWR.", "ML19149A618, Fast Reactor Safety, slide 8", null, null, "C198"],
  ["Reactor Operational Physics", "What three basic principles does inherent/passive safety use?", "Favorable reactivity feedback, sufficient natural circulation cooling for decay heat removal, and appropriate selection of fuel and cladding materials.", "ML19149A618, Fast Reactor Safety, slide 12", null, null, "C199"],
  ["Reactor Operational Physics", "How does a sodium catch pan and fire suppression deck limit a sodium fire?", "Air must pass through small holes in a steel plate, slowing oxygen transport to the pool. Sodium oxide buildup eventually plugs the openings and ends the fire.", "ML19149A618, Fast Reactor Safety, slide 25", null, null, "C200"],
  ["Thermal Hydraulics", "Why must pump coast-down be slow enough in an SFR loss-of-flow accident?", "To avoid coolant boiling in the early phase, when the power-to-flow ratio is greater than 1.", "ML19149A618, Fast Reactor Safety, slide 17", null, null, "C201"],
  ["Core Thermal Limits", "Where do metal fuel failures occur, and do they cause blockages?", "Predictably near the top of the fuel column. Scenarios that melt the fuel or fail the cladding do not result in blockages.", "ML19149A618, Fast Reactor Safety, slide 19", null, null, "C202"],
  ["Reactor Operational Physics", "Why do SFR containments act only as a barrier, and what pressure challenge must they still handle?", "The primary coolant is low pressure and single-phase. Containment should still have some pressure-retaining capability against the heat and pressure from a sodium fire.", "ML19149A618, Fast Reactor Safety, slide 16", null, null, "C203"],
  // Mechanistic Source Term (ML19150A389)
  ["Neutrons", "What isotope is natural sodium, and what activation products form in a reactor?", "Natural sodium is entirely Na-23. Irradiation produces Na-24 (half-life about 15 hours) and Na-22 (about 2.6 years).", "ML19150A389, Mechanistic Source Term, slide 7", null, null, "C204"],
  ["Reactor Operational Physics", "Why is containment pressure loading lower for SFR accidents than for LWRs?", "Postulated SFR accidents do not involve rupture of a high-pressure boundary and produce no hydrogen.", "ML19150A389, Mechanistic Source Term, slide 14", null, null, "C205"],
  ["Fission Product Poisons", "Where does most xenon and krypton go in metal fuel during irradiation?", "Most migrates to the fission gas plenum once the fuel porosity interconnects, around 1-2% burnup.", "ML19150A389, Mechanistic Source Term, slide 19", null, null, "C206"],
  // U.S. Fast Reactor Design and Analysis Tools (ML19150A397)
  ["Reactor Operational Physics", "Which system analysis codes have traditionally supported fast reactor licensing?", "SAS4A/SASSYS-1, SAM, and modified LWR codes (RELAP, TRACE).", "ML19150A397, U.S. Fast Reactor Design and Analysis Tools, slide 4", null, null, "C207"],
  ["Reactor Kinetics and Neutron Sources", "In a fast reactor system analysis code, what model captures changes in core power level?", "A point-kinetics model.", "ML19150A397, U.S. Fast Reactor Design and Analysis Tools, slide 4", null, null, "C208"],
  // Probabilistic Risk Assessment (ML19150A414)
  ["Reactor Operational Physics", "How does the ASME/ANS non-LWR PRA standard differ from LWR PRA standards?", "It is a single comprehensive standard rather than separate Level 1, 2, 3 and low power/shutdown standards, and it uses offsite consequence rather than CDF or LRF (intermediate metrics are permitted).", "ML19150A414, Probabilistic Risk Assessment, slide 8", null, null, "C209"],
  // FFTF Operating Experience with Sodium Natural Circulation (HEDL-SA-2325)
  ["Thermal Hydraulics", "Name two FFTF design features that aided sustained sodium natural circulation.", "Progressive elevation differences between the reactor, IHX and dump heat exchanger to give thermal driving head, and a long above-core 'chimney' to enhance thermal head.", "HEDL-SA-2325 (FFTF natural circulation, 1981), PDF p. 6", null, null, "C210"],
  ["Thermal Hydraulics", "At FFTF, what normally provided forced circulation for decay heat removal?", "The main coolant pumps driven at low speed by pony motors.", "HEDL-SA-2325 (FFTF natural circulation, 1981), PDF p. 6", null, null, "C211"],
  ["Thermal Hydraulics", "What was the first FFTF scram to natural circulation, and what did it show?", "It was performed from 5% power and 75% flow. It showed a rapid and smooth transition to natural circulation, with continuous positive flow indication throughout.", "HEDL-SA-2325 (FFTF natural circulation, 1981), PDF p. 14", null, null, "C212"],
  ["Thermal Hydraulics", "What happens if the last FFTF dump heat exchanger module freezes?", "Studies showed decay heat would by then be low enough that primary loop piping heat loss provides an adequate heat sink.", "HEDL-SA-2325 (FFTF natural circulation, 1981), PDF p. 12", null, null, "C213"],
  // ALIP Pumps (LP-ALIP-PUMPS)
  ["Pumps", "What is an annular linear induction pump (ALIP)?", "An electromagnetic pump that moves liquid without impellers or rotating shafts. It uses electromagnetic induction to propel the liquid through a circular channel.", "LP-ALIP-PUMPS, slide 1.1 ALIP Intro", null, null, "C214"],
  ["Pumps", "Why does an ALIP with stator windings on both sides of the channel need an inner core?", "A solid conductive inner core bridges the gap to maintain a strong magnetic field in the channel.", "LP-ALIP-PUMPS, slide 1.3 ALIP Parts", null, null, "C215"],
  ["Pumps", "What are the disadvantages of annular linear induction pumps?", "Lower flow rates for a given power input, lower net efficiency at higher flows, and harder heat removal from the stator.", "LP-ALIP-PUMPS, slide 1.4 ALIP, How It Works!", null, null, "C216"],
  ["Pumps", "In an ALIP, what is the air gap power (Pgap)?", "The amount of power transferred from the stator to the rotor. It is calculated from the applied power and the pump efficiency.", "LP-ALIP-PUMPS, slide 1.4 ALIP, How It Works!", null, null, "C217"],
  // Sodium Leak Detectors (LP-SODIUM-LEAK-DETECTORS)
  ["Sensors and Detectors", "How do spark plug type sodium leak detectors work?", "Leaking fluid completes an open circuit.", "LP-SODIUM-LEAK-DETECTORS, slide 1.5 Knowledge Check 1", null, null, "C218"],
  // Failed Fuel Detectors (LP-FAILED-FUEL-DETECTORS)
  ["Sensors and Detectors", "Which fill gases do most radiation detectors use, and which gas do neutron detectors use?", "Most use argon and helium. Detectors designed to measure neutrons use boron trifluoride.", "DOE-1013-V2 (DOE-HDBK-1013/2-92), Proportional Counter, IC-06 p. 19", null, null, "C219"],
  ["Sensors and Detectors", "What does a pulse-height discriminator do in a BF3 detector?", "It sifts through the signals to determine which are generated by neutrons and which by other interactions.", "LP-FAILED-FUEL-DETECTORS, slide 1.5 BF3 Chamber", null, null, "C220"],
  ["Sensors and Detectors", "How does loss of voltage affect a radiation or neutron detector?", "It fails the detector low. Other circuitry issues can fail it low or high, depending on the malfunction.", "LP-FAILED-FUEL-DETECTORS, slide 1.7 Malfunctions", null, null, "C221"],
  ["Sensors and Detectors", "Why do BF3 detectors eventually have to be replaced?", "The boron trifluoride fill gas burns out over time.", "LP-FAILED-FUEL-DETECTORS, slide 1.7 Malfunctions", null, null, "C222"],
  // Core Thermal Limits (LP-CORE-THERMAL-LIMITS-WORD)
  ["Core Thermal Limits", "What is fuel cladding chemical interaction (FCCI)?", "Swollen metal fuel touching the cladding reacts at high temperature to form a eutectic, a mixture with a lower melting point than either the fuel slug or the cladding. It thins the cladding wall and is not reversible.", "ML19149A371, Fast Reactor Fuels, slide 24", null, null, "C223"],
  // Source Neutrons (LP-SOURCE-NEUTRONS)
  ["Reactor Kinetics and Neutron Sources", "Are source neutrons needed to start the chain reaction?", "No. Spontaneous fission of U-238 in the fuel provides more than enough neutrons; it only takes one.", "LP-SOURCE-NEUTRONS, slide 1.9 Knowledge Check #1", null, null, "C226"],
  ["Reactor Kinetics and Neutron Sources", "What is the difference between an installed and an intrinsic neutron source?", "Installed: an external source that supplements the neutron supply so source range count rate is visible when shut down. Intrinsic: an internal source from spontaneous fissions and neutron-producing reactions in the core.", "LP-SOURCE-NEUTRONS, slide 1.14 Drag and Drop", null, null, "C227"],
  ["Reactor Kinetics and Neutron Sources", "Do source neutrons add reactivity in the power range?", "No. In the power range, source neutron strength is negligible compared with fission neutron strength.", "LP-SOURCE-NEUTRONS, slide 1.15 Knowledge Check #2", null, null, "C228"],
  ["Reactor Kinetics and Neutron Sources", "What is subcritical multiplication?", "The process that lets fission rate rise even in a reactor that has not yet reached a critical state.", "LP-SOURCE-NEUTRONS, slide 1.2 This module", null, null, "C229"],
  // Pressure Detectors (LP-PRESSURE-DETECTORS)
  ["Sensors and Detectors", "What are the functions of pressure detectors?", "Indication, alarm, and control.", "DOE-1013-V1 (DOE-HDBK-1013/1-92), Pressure Detector Functional Uses, IC-02 p. 5", null, null, "C230"],
  ["Sensors and Detectors", "Why does a Bourdon tube straighten as pressure increases?", "Greater force acts on the outer radius of the tube because of its larger surface area.", "LP-PRESSURE-DETECTORS, slide 1.11 MC 3", null, null, "C231"],
  ["Sensors and Detectors", "How does a pressure detector fail on overpressurization, and on a sensing element leak or rupture?", "Overpressurization: fails high. Sensing element leak or rupture: fails low.", "LP-PRESSURE-DETECTORS, slide 1.16 Pressure Detector Failures", null, null, "C232"],
  ["Sensors and Detectors", "What is measured in a variable capacitance pressure detector?", "The change in capacitance, which is proportional to the change in pressure.", "DOE-1013-V1 (DOE-HDBK-1013/1-92), Pressure Detection Circuitry, IC-02 p. 11", null, null, "C233"],
  // Temperature Detectors (LP-TEMPERATURE-DETECTORS)
  ["Sensors and Detectors", "On what principle does a resistance temperature detector (RTD) work?", "Its resistance to current increases as temperature goes up.", "DOE-1013-V1 (DOE-HDBK-1013/1-92), Objectives, IC-01 p. 4", null, null, "C234"],
  ["Sensors and Detectors", "How is a thermocouple constructed?", "Two dissimilar metal wires joined together at a measuring junction.", "DOE-1013-V1 (DOE-HDBK-1013/1-92), Thermocouples, IC-01 p. 7", null, {"f": "images/doe-1013-v1-ic-01-fig5.png", "alt": "Thermocouple in a rigid sheath, with the measuring junction at the bottom and magnesium oxide around the wires.", "cap": "Figure 5. Internal Construction of a Typical Thermocouple. Source: DOE-1013-V1 (DOE-HDBK-1013/1-92), IC-01 p. 6.", "at": "a"}, "C235"],
  ["Sensors and Detectors", "How does a bimetallic strip thermometer work?", "It has two strips of metal that expand differently at the same temperature.", "LP-TEMPERATURE-DETECTORS, slide 1.27 Quiz", null, null, "C236"],
  ["Sensors and Detectors", "In an RTD circuit, what does a balanced bridge circuit do?", "It uses a galvanometer to compare RTD resistance to a fixed resistor.", "DOE-1013-V1 (DOE-HDBK-1013/1-92), Temperature Detection Circuitry, IC-01 p. 13", null, {"f": "images/doe-1013-v1-ic-01-fig10.png", "alt": "Balanced bridge with a slide wire, fixed resistor, RTD, and galvanometer.", "cap": "Figure 10. Balanced Bridge Circuit. Source: DOE-1013-V1 (DOE-HDBK-1013/1-92), IC-01 p. 13.", "at": "a"}, "C237"],
  ["Sensors and Detectors", "Which is more accurate, an RTD or a thermocouple?", "RTDs are more accurate than thermocouples.", "LP-TEMPERATURE-DETECTORS, slide 1.23 Fill in the Blank Q4", null, null, "C238"],
  // Fuel Depletion (LP-FUEL-DEPLETION)
  ["Fuel Depletion and Burnable Poisons", "Why does core temperature fall over a fuel cycle if rods are NOT moved?", "U-235 burns out without enough replacement fissile fuel being created.", "LP-FUEL-DEPLETION, slide 1.3 Fuel Depletion", null, null, "C239"],
  ["Fuel Depletion and Burnable Poisons", "Which fissile fuels are created from U-238 during a fuel cycle, and what is the net reactivity effect?", "Pu-239 and Pu-241. They are created more slowly than U-235 is depleted, so the overall effect is adding negative reactivity.", "LP-FUEL-DEPLETION, slide 1.5 Fuel Depletion Terms", null, null, "C240"],
  // Demineralizers and Ion Exchangers (LP-DEMINERALIZERS-AND-ION-EXCHANGERS)
  ["Demineralizers and Ion Exchangers", "What is demineralizer leakage, as opposed to breakthrough?", "Leakage is small amounts of impurities passing through during normal operation. Breakthrough is the point at which impurities begin to appear in the effluent, before exhaustion.", "DOE-1015-V2 (DOE-HDBK-1015/2-93), Water Treatment Processes, CH-04 p. 24", null, null, "C243"],
  ["Demineralizers and Ion Exchangers", "Inlet conductivity is 50 μmho/cm and outlet conductivity is 0.5 μmho/cm. What percent of impurities is removed?", "99%, from ((50 - 0.5) / 50) x 100.", "LP-DEMINERALIZERS-AND-ION-EXCHANGERS, slide 1.41 What is the percent of impurities removed if the inlet conductivity is 50 μmho/cm and the outlet conductivity is 0.5 μmho/cm?", null, null, "C244"],
  ["Demineralizers and Ion Exchangers", "At about what temperature does cation exchange resin begin thermal decomposition?", "Above about 250 °F.", "DOE-1015-V2 (DOE-HDBK-1015/2-93), Water Treatment Processes, CH-04 p. 25", null, null, "C245"],
  // DISTRIBUTED CONTROL SYSTEMS (DCS) (LP-DISTRIBUTED-CONTROL-SYSTEMS-DCS)
  ["Controllers and Positioners", "Is a turbine overspeed trip important for reactor safety?", "No. An overspeed trip is important for personnel safety but not reactor safety.", "LP-DISTRIBUTED-CONTROL-SYSTEMS-DCS, slide 2.2 Review Question 1", null, null, "C246"],
  // 191002 GFES Electrical Test Equipment (LP-ELECTRICAL-TEST-EQUIPMENT)
  ["Sensors and Detectors", "How is a voltmeter connected, and what is the loading effect?", "In parallel with the load. The meter draws current, causing a voltage drop across its resistance that it subtracts from the measured voltage; that reduction is the loading effect.", "DOE-1011-V4 (DOE-HDBK-1011/4-92), Voltmeters, ES-14 p. 6", null, {"f": "images/doe-1011-v4-es-14-fig4.png", "alt": "A simple DC voltmeter: a meter movement in series with multiplier resistor Rs, connected across a load.", "cap": "Figure 4. Simple DC Voltmeter. Source: DOE-1011-V4 (DOE-HDBK-1011/4-92), ES-14 p. 5.", "at": "a"}, "C247"],
  ["Sensors and Detectors", "How do manufacturers limit voltmeter loading effect?", "By building the meter movement with an extremely high resistance to limit current through the voltmeter.", "DOE-1011-V4 (DOE-HDBK-1011/4-92), Voltmeters, ES-14 p. 6", null, null, "C248"],
  ["Sensors and Detectors", "How must an ammeter be connected, and how does it affect the circuit?", "In series with the circuit. It increases circuit resistance by the meter's internal resistance.", "DOE-1011-V4 (DOE-HDBK-1011/4-92), Ammeters, ES-14 p. 10", null, {"f": "images/doe-1011-v4-es-14-fig6.png", "alt": "An ammeter placed in series with a circuit, shown without and with the meter.", "cap": "Figure 6. Ammeter. Source: DOE-1011-V4 (DOE-HDBK-1011/4-92), ES-14 p. 10.", "at": "a"}, "C249"],
  ["Sensors and Detectors", "What does a ground detector measure?", "Conductor insulation resistance to ground, in ohms.", "DOE-1011-V4 (DOE-HDBK-1011/4-92), Other Electrical Measuring Devices, ES-14 p. 24", null, null, "C250"],
  ["Sensors and Detectors", "What is a synchroscope used for?", "Aligning main generator frequency with the distribution grid before connection, to prevent phase mismatch.", "DOE-1011-V3 (DOE-HDBK-1011/3-92), Ac Generator Operation, ES-10 p. 10", null, null, "C251"],
  // Plugging Temperature Indicators (LP-PLUGGING-TEMPERATURE-INDICATORS)
  ["Sensors and Detectors", "What is the plugging temperature?", "The sodium temperature measured at the moment flow past the orifice begins to decrease, when impurities such as oxygen and hydrogen start to precipitate and deposit on the orifice.", "LP-PLUGGING-TEMPERATURE-INDICATORS, slide 1.7 Plugging Temperature Indicator", null, null, "C252"],
  ["Sensors and Detectors", "How does the plugging temperature relate to the level of impurities in sodium?", "The more impurities, the higher the temperature at which the flow decrease is detected.", "LP-PLUGGING-TEMPERATURE-INDICATORS, slide 1.5 Sodium Purity Monitoring Theory", null, null, "C253"],
  ["Demineralizers and Ion Exchangers", "Why is sodium coolant purity important?", "Pure sodium prevents corrosion, enhances heat transfer efficiency, minimizes radiation hazards, and ensures stable reactor performance.", "LP-PLUGGING-TEMPERATURE-INDICATORS, slide 1.4 Why is it important to ensure the purity of sodium coolant in a liquid sodium fast reactor? (Select all that apply)", null, null, "C254"],
  ["Sensors and Detectors", "Does a plugging temperature indicator identify which impurity is present?", "No. It does not discriminate the species of the plugging impurity, but it does detect its presence.", "LP-PLUGGING-TEMPERATURE-INDICATORS, slide 1.11 Advantages of PTI Fill-in-blank", null, null, "C255"],
  ["Demineralizers and Ion Exchangers", "How does a cold trap work, and how can a PTI help with it?", "It cools a small fraction of the main flow to just above sodium's freezing point so impurities precipitate. PTIs show how effective cold traps are and when to place them in service if not run continuously.", "LP-PLUGGING-TEMPERATURE-INDICATORS, slide 1.8 Cold Trap", null, null, "C256"],
  // Level Detectors (LP-LEVEL-DETECTORS)
  ["Sensors and Detectors", "What are the advantages and the main disadvantage of a float switch level detector?", "Advantages: simplicity, accuracy, and reliability. Disadvantage: level is indicated only at specific points, not between them.", "LP-LEVEL-DETECTORS, slide 1.1 Introduction and float switch", null, null, "C257"],
  ["Sensors and Detectors", "What is the pressure at a depth in a liquid?", "The pressure applied to the liquid surface plus density times height times gravity, where height is from the liquid surface to the measurement point.", "DOE-1012-V3 (DOE-HDBK-1012/3-92), Continuity Equation, HT-03 p. 4", null, {"f": "images/doe-1012-v3-ht-03-fig1.png", "alt": "Tank of liquid with outlets at different depths; liquid leaves the lower outlets at higher velocity.", "cap": "Figure 1. Pressure Versus Depth. Source: DOE-1012-V3 (DOE-HDBK-1012/3-92), HT-03 p. 3.", "at": "a"}, "C258"],
  ["Sensors and Detectors", "How does indicated level respond to differential pressure in wet and dry reference leg level detectors?", "Wet reference leg: a D/P drop makes indicated level rise. Dry reference leg: a D/P rise makes indicated level rise.", "LP-LEVEL-DETECTORS, slide 1.8 The most important slide of this section!!", null, null, "C259"],
  // Breakers, Relays, and Disconnects Part 1 (LP-BREAKERS-RELAYS-AND-DISCONNECTS-PART-1)
  ["Breakers, Relays, and Disconnects", "At what voltage is an undervoltage relay generally set to trip the breaker?", "When voltage drops to 60 to 70 percent of normal value.", "LP-BREAKERS-RELAYS-AND-DISCONNECTS-PART-1, slide 1.19 Breaker Protective Relays", null, null, "C260"],
  ["Breakers, Relays, and Disconnects", "What does a reverse-power relay protect against?", "Generator damage from motoring, by tripping the generator output breaker.", "DOE-1011-V3 (DOE-HDBK-1011/3-92), Ac Generator Operation, ES-10 p. 10", null, null, "C261"],
  ["Breakers, Relays, and Disconnects", "What does an instantaneous trip device respond to?", "The high currents produced by short circuits; it trips the breaker quickly.", "DOE-1011-V4 (DOE-HDBK-1011/4-92), Circuit Breakers, ES-15 p. 8", null, null, "C262"],
  ["Breakers, Relays, and Disconnects", "Why are fuses inherently reliable, and what do fuses and overloads protect against?", "A fusible link melts if too much current passes. Fuses and overloads protect only against overcurrent.", "LP-BREAKERS-RELAYS-AND-DISCONNECTS-PART-1, slide 1.15 Design Options for Protective Features", null, null, "C263"],
  ["Breakers, Relays, and Disconnects", "When working on energized equipment, should you ground your body with a metal strap?", "No. It would be unsafe to ground your body with a metal strap.", "LP-BREAKERS-RELAYS-AND-DISCONNECTS-PART-1, slide 1.23 Knowledge Check", null, null, "C264"],
  // Breakers, Relays, and Disconnects Part 2 (LP-BREAKERS-RELAYS-AND-DISCONNECTS-PART-2)
  ["Breakers, Relays, and Disconnects", "How do you reset a breaker in the TRIP FREE position?", "Position it to OPEN first.", "LP-BREAKERS-RELAYS-AND-DISCONNECTS-PART-2, slide 1.41 Resetting a Breaker", null, null, "C265"],
  // AC Generator Theory and Operation (LP-AC-GENERATOR-THEORY-AND-OPERATION)
  ["Motors and Generators", "What is reactive power, and how is it measured?", "Power that does no useful work but is essential for maintaining magnetic and electric fields through inductors and capacitors. It is measured in volt-amps reactive (VAR).", "DOE-1011-V3 (DOE-HDBK-1011/3-92), Power Triangle, ES-09 p. 3", null, null, "C266"],
  ["Motors and Generators", "What is apparent power, and how is it measured?", "The total power supplied to a circuit, a combination of true and reactive power, measured in volt-amps (VA).", "DOE-1011-V3 (DOE-HDBK-1011/3-92), Power Triangle, ES-09 p. 1", null, null, "C267"],
  ["Motors and Generators", "What is true power, and how is it measured?", "The actual power consumed to do useful work such as heat or motion, measured in watts and dependent on the resistive loads.", "DOE-1011-V3 (DOE-HDBK-1011/3-92), Power Triangle, ES-09 p. 3", null, null, "C268"],
  // Position Indicators (LP-POSITION-INDICATORS)
  ["Sensors and Detectors", "When is a limit switch used as a position detector?", "When you only need to know whether a component, such as a valve, is in a single position, open or closed.", "LP-POSITION-INDICATORS, slide 1.2 Switch type detectors", null, null, "C269"],
  ["Sensors and Detectors", "What is a reed switch?", "A thin conductor that bends to make or break electrical contact in response to a magnetic field.", "LP-POSITION-INDICATORS, slide 1.3 Reed switch control rod position detector", null, null, "C270"],
  ["Sensors and Detectors", "How does an LVDT valve position detector work, and why is it very reliable?", "A metal extension on the valve stem changes the coupling between two secondary coils, and the differential changes linearly with valve position. It needs no physical contact.", "DOE-1013-V1 (DOE-HDBK-1013/1-92), Variable Output Devices, IC-05 p. 9", null, {"f": "images/doe-1013-v1-ic-05-fig6.png", "alt": "Valve with its extension shaft moving between the primary and secondary windings of a transformer.", "cap": "Figure 6. Linear Variable Differential Transformer. Source: DOE-1013-V1 (DOE-HDBK-1013/1-92), IC-05 p. 9.", "at": "a"}, "C271"],
  ["Sensors and Detectors", "How do stuck reed switches affect position indication?", "Stuck shut: the indication stays lit regardless of valve position. Stuck open: that switch's indication stays out regardless of valve position.", "DOE-1013-V1 (DOE-HDBK-1013/1-92), Switches, IC-05 p. 7", null, {"f": "images/doe-1013-v1-ic-05-fig4.png", "alt": "Reed switches beside a valve stem extension carrying a permanent magnet.", "cap": "Figure 4. Reed Switches. Source: DOE-1013-V1 (DOE-HDBK-1013/1-92), IC-05 p. 6.", "at": "a"}, "C272"],
  ["Sensors and Detectors", "How does a potentiometer valve position indicator fail on an electrical short or open?", "The indication fails at one extreme or the other.", "DOE-1013-V1 (DOE-HDBK-1013/1-92), Variable Output Devices, IC-05 p. 8", null, {"f": "images/doe-1013-v1-ic-05-fig5.png", "alt": "Valve stem connected to a variable resistor in a circuit with an indicator.", "cap": "Figure 5. Potentiometer Valve Position Indicator. Source: DOE-1013-V1 (DOE-HDBK-1013/1-92), IC-05 p. 8.", "at": "a"}, "C273"],
  ["Sensors and Detectors", "How can sodium aerosols affect position detectors?", "Sodium aerosol deposits may cause moving components to stick. Sodium is electrically conductive and is a solid below about 210 °F.", "LP-POSITION-INDICATORS, slide 1.9 How changes in the enviroment effect position detectors", null, null, "C274"],
  // Heat Exchangers (LP-HEAT-EXCHANGERS)
  ["Heat Exchangers and Condensers", "In a tube and shell heat exchanger with very different fluid pressures, which side holds the higher-pressure fluid, and why?", "The tubes, because it is less costly to design tubes to withstand higher pressure than the shell.", "DOE-1018-V1 (DOE-HDBK-1018/1-93), Types of Heat Exchangers, ME-02 p. 2", null, {"f": "images/doe-1018-v1-me-02-fig1.png", "alt": "Tube and shell heat exchanger cut open, labeling the tube sheet, support plates, steam inlet, feedwater connections, and water box.", "cap": "Figure 1. Tube and Shell Heat Exchanger. Source: DOE-1018-V1 (DOE-HDBK-1018/1-93), ME-02 p. 3.", "at": "a"}, "C275"],
  ["Heat Exchangers and Condensers", "How do parallel flow and counter flow compare for the hottest cold-fluid temperature?", "Parallel flow: always less than the coldest hot-fluid temperature. Counter flow: can actually be greater than the coldest hot-fluid temperature.", "DOE-1018-V1 (DOE-HDBK-1018/1-93), Types of Heat Exchangers, ME-02 p. 4", null, null, "C276"],
  ["Heat Exchangers and Condensers", "In what order is a heat exchanger secured?", "First stop the hot fluid by shutting its discharge valve, then stop the colder fluid flow.", "LP-HEAT-EXCHANGERS, slide 1.25 Heat Exchanger Startup & Operation", null, null, "C277"],
  ["Heat Exchangers and Condensers", "Why vent a heat exchanger before placing it in service?", "To remove air and noncondensable gases. Gas pockets decrease the cooling surface area and can disrupt flow.", "LP-HEAT-EXCHANGERS, slide 1.25 Heat Exchanger Startup & Operation", null, null, "C278"],
  ["Heat Exchangers and Condensers", "What is thermal shock, and where is it most severe?", "A severe stress from a sudden, unequally distributed temperature change. It is most severe where different metals are joined.", "LP-HEAT-EXCHANGERS, slide 1.24 Heat Exchanger Startup & Operation", null, null, "C279"],
  ["Heat Exchangers and Condensers", "Which method of dealing with heat exchanger fouling is the most effective?", "Operating practices, such as maintaining a minimum, somewhat turbulent flow. Hydrolancing and chemical cleaning are other methods.", "LP-HEAT-EXCHANGERS, slide 1.28 Fouling of Heat Exchange Surfaces", null, null, "C280"],
  ["Heat Exchangers and Condensers", "What is a regenerative heat exchanger?", "One in which the same fluid is both the cooling fluid and the cooled fluid.", "DOE-1018-V1 (DOE-HDBK-1018/1-93), Types of Heat Exchangers, ME-02 p. 9", null, {"f": "images/doe-1018-v1-me-02-fig7.png", "alt": "Two process diagrams: in the regenerative unit the outgoing fluid heats the returning fluid, and in the non-regenerative unit a separate cooling system removes the heat.", "cap": "Figure 7. Regenerative and Non-Regenerative Heat Exchangers. Source: DOE-1018-V1 (DOE-HDBK-1018/1-93), ME-02 p. 10.", "at": "a"}, "C281"],
  // Neutrons (LP-NEUTRONS)
  ["Neutrons", "Why ISN'T neutrino energy counted in the 200 MeV per fission?", "Neutrinos rarely interact in the reactor, so no heat is gained from their roughly 10 MeV.", "LP-NEUTRONS, slide 1.49 Energy Release Per Fission", null, null, "C282"],
  ["Neutrons", "Are all fission fragments delayed neutron precursors?", "No. Not all fission fragments are delayed neutron precursors, but all delayed neutron precursors are fission fragments.", "LP-NEUTRONS, slide 1.60 Delayed Neutron Precursors", null, null, "C283"],
  ["Neutrons", "Does an isotope's delayed neutron fraction change over core life?", "No. It is the fraction of neutrons born delayed for a given isotope; for U-235 it stays 0.0065.", "LP-NEUTRONS, slide 1.64 Delayed Neutron Fraction (β)", null, null, "C284"],
  ["Neutrons", "Why can't a neutron directly ionize anything?", "It has no charge, so detectors need something else, such as a boron reaction, to cause ionizations.", "DOE-1013-V2 (DOE-HDBK-1013/2-92), Ionization Chamber, IC-06 p. 31", null, null, "C285"],
  ["Neutrons", "How many neutrons are normally produced per fission?", "Between two and three fast neutrons; most are prompt and some are delayed.", "DOE-1019-V1 (DOE-HDBK-1019/1-93), Prompt and Delayed Neutrons, NP-02 p. 32", null, null, "C286"],
  ["Neutrons", "What is neutron flux?", "Neutron density times velocity.", "DOE-1019-V1 (DOE-HDBK-1019/1-93), Neutron Sources, NP-02 p. 15", null, null, "C287"],
  // Subcritical Multiplication (LP-SUBCRITICAL-MULTIPLICATION)
  ["Reactor Kinetics and Neutron Sources", "What is the subcritical multiplication factor M?", "The factor by which source neutrons are multiplied to get the neutron population: M = 1 / (1 - keff).", "DOE-1019-V2 (DOE-HDBK-1019/2-93), Subcritical Multiplication, NP-04 p. 2", null, null, "C288"],
  ["Reactor Kinetics and Neutron Sources", "How does the time to reach a new equilibrium count rate change as criticality is approached?", "It takes longer, because more cycles of fission neutron multiplication are needed.", "DOE-1019-V2 (DOE-HDBK-1019/2-93), Subcritical Multiplication, NP-04 p. 7", null, null, "C289"],
  ["Reactor Kinetics and Neutron Sources", "Is the source range count rate by itself a good representation of neutron activity?", "No. Count rate comparisons or ratios are more useful for gauging response to reactivity changes and the approach to criticality.", "LP-SUBCRITICAL-MULTIPLICATION, slide 1.18 Count Rates and Keff", null, null, "C290"],
  ["Reactor Kinetics and Neutron Sources", "When the core is first built, what count rate must the installed neutron sources produce?", "At least 1 count per second.", "LP-SUBCRITICAL-MULTIPLICATION, slide 1.4 Building the core", null, null, "C291"],
  // Delayed Neutron Importance (LP-DELAYED-NEUTRON-IMPORTANCE)
  ["Reactor Kinetics and Neutron Sources", "How do power changes differ at end of core life compared with beginning of life?", "They are quicker at end of life for the same reactivity insertion; less rod motion gives the same startup rate later in core life.", "LP-DELAYED-NEUTRON-IMPORTANCE, slide 1.19 Delayed Neutron effect over core life", null, null, "C292"],
  ["Reactor Kinetics and Neutron Sources", "Why does the average delayed neutron fraction drop slowly over core life?", "Pu-239 concentration and its fission rate rise. Refueling adds U-235 and raises it again.", "LP-DELAYED-NEUTRON-IMPORTANCE, slide 1.15 Average Delayed Neutron Fraction", null, null, "C293"],
  ["Reactor Kinetics and Neutron Sources", "How does U-238 fission compare with Pu-239 fission for producing delayed neutrons?", "Each U-238 fission is about 7 times more likely to eventually produce a delayed neutron.", "LP-DELAYED-NEUTRON-IMPORTANCE, slide 1.14 Delayed neutron Fraction", null, null, "C294"],
  ["Reactor Kinetics and Neutron Sources", "What is the average effective delayed neutron fraction, and what relates it to the average delayed neutron fraction?", "The fraction of fissions caused by delayed neutrons over all fissions. The importance factor relates the two.", "DOE-1019-V2 (DOE-HDBK-1019/2-93), Reactor Kinetics, NP-04 p. 12", null, null, "C295"],
  ["Reactor Kinetics and Neutron Sources", "How many delayed neutron precursor isotopes are there, and what are their half-lives?", "Over 100 fission fragment isotopes, with half-lives from about 1/4 second to 56 seconds.", "DOE-1019-V1 (DOE-HDBK-1019/1-93), Prompt and Delayed Neutrons, NP-02 p. 32", null, null, "C296"],
  ["Reactor Kinetics and Neutron Sources", "What value of the effective delayed neutron precursor decay constant is used when the reactor is supercritical?", "0.1 inverse seconds.", "DOE-1019-V2 (DOE-HDBK-1019/2-93), Reactor Kinetics, NP-04 p. 13", null, null, "C297"],
  // Reactor Neutrons (LP-REACTOR-NEUTRONS)
  ["Neutron Life Cycle", "What is excess reactivity (k-excess)?", "The reactivity from fuel loaded beyond the minimum needed for criticality at beginning of core life, to allow longer operation between refuelings.", "LP-REACTOR-NEUTRONS, slide 1.21 Excess Reactivity", null, null, "C298"],
  ["Neutron Life Cycle", "Define shutdown margin.", "The instantaneous reactivity by which the reactor is, or would be, subcritical from its present condition, assuming all rods fully inserted except the most reactive rod fully withdrawn.", "DOE-1019-V2 (DOE-HDBK-1019/2-93), Reactor Operation, NP-04 p. 28", null, null, "C299"],
  ["Neutron Life Cycle", "Does reducing power using only control rods change shutdown margin?", "No. Inserting control rods does not affect SDM, and the reactor returns to exactly critical.", "LP-REACTOR-NEUTRONS, slide 1.44 Knowledge Check 15", null, null, "C300"],
  ["Neutron Life Cycle", "How does fast non-leakage in a sodium fast reactor compare with a light water reactor?", "Because of core size and shape, fast non-leakage can affect keff more than in an LWR.", "LP-REACTOR-NEUTRONS, slide 1.31 Factors Affecting Fast Fission", null, null, "C302"],
  // Heat Transfer (LP-HEAT-TRANSFER)
  ["Heat Exchangers and Condensers", "Match: regenerative heat exchanger, and parallel flow heat exchanger.", "Regenerative: conserves energy. Parallel flow: the cold fluid temperature never exceeds the hot fluid temperature.", "LP-HEAT-TRANSFER, slide 1.32 DRAG-AND-DROP", null, null, "C303"],
  // Thermal Hydraulics (LP-THERMAL-HYDRAULICS)
  ["Thermal Hydraulics", "How does wire wrapping on fuel pins affect heat transfer?", "The wire breaks up the laminar boundary layer by making the surface rough instead of smooth.", "LP-THERMAL-HYDRAULICS, slide 1.7 Wire Wrapped Fuel Pins", null, null, "C304"],
  ["Thermal Hydraulics", "About what fraction of core flow is bypass flow, and what does it cool?", "Usually about 5% to 10% of total flow. It cools components other than the fuel, such as control rods, reflectors and shield assemblies.", "LP-THERMAL-HYDRAULICS, slide 1.16 Bypass Flow", null, null, "C305"],
  ["Thermal Hydraulics", "How can operators enhance natural circulation after a scram, and what must they watch for?", "Remove more heat at the heat sink, while avoiding freezing the sodium, which would block flow. A new equilibrium can take 30 minutes or more.", "LP-THERMAL-HYDRAULICS, slide 1.38 Enhancing Natural Circulation", null, null, "C308"],
  // Thermodynamics (LP-THERMODYNAMICS)
  ["Thermodynamic Processes", "What defines a throttling (isenthalpic) process?", "No change in enthalpy (h1 = h2), no work (W = 0), and adiabatic (Q = 0).", "DOE-1012-V1 (DOE-HDBK-1012/1-92), Thermodynamic Systems and Processes, HT-01 p. 29", null, null, "C310"],
  ["Basic Energy Concepts", "What is the sign convention for work in a thermodynamic system?", "Work into the system (such as a pump on the fluid) is negative. Work out of the system (such as turning the turbine) is positive.", "LP-THERMODYNAMICS, slide 1.22 Heat Transferred Into or Out of System", null, null, "C311"],
  ["Thermodynamic Cycles", "State Carnot's principle about engine efficiency.", "No engine can be more efficient than a reversible engine operating between the same heat source and heat sink temperatures.", "DOE-1012-V1 (DOE-HDBK-1012/1-92), Second Law of Thermodynamics, HT-01 p. 72", null, null, "C312"],
  ["Thermodynamic Processes", "What factors make real processes irreversible?", "Friction, unrestrained expansion of a fluid, heat transfer through a finite temperature difference, and mixing of two different substances.", "DOE-1012-V1 (DOE-HDBK-1012/1-92), Thermodynamic Systems and Processes, HT-01 p. 29", null, null, "C313"],
  ["Thermodynamic Processes", "What does the second law of thermodynamics say about converting heat to work?", "No device operating in a cycle can convert all the heat supplied to it into mechanical work.", "DOE-1012-V1 (DOE-HDBK-1012/1-92), Second Law of Thermodynamics, HT-01 p. 70", null, null, "C314"],
  // Thermo Units and Properties (LP-THERMO-UNITS-AND-PROPERTIES)
  ["Thermodynamic Units and Properties", "What is latent heat?", "The heat added or removed to produce a phase change without a temperature change.", "DOE-1012-V1 (DOE-HDBK-1012/1-92), Energy, Work, and Heat, HT-01 p. 21", null, null, "C315"],
  ["Thermodynamic Units and Properties", "What is heat, in thermodynamics?", "Energy in transition caused by a difference in temperature.", "DOE-1012-V2 (DOE-HDBK-1012/2-92), Heat Transfer Terminology, HT-02 p. 2", null, null, "C316"],
  ["Thermodynamic Units and Properties", "If matter is divided into two equal parts, what happens to its intensive and extensive properties?", "Each part keeps the same value of intensive properties and half the value of extensive properties.", "DOE-1012-V1 (DOE-HDBK-1012/1-92), Thermodynamic Properties, HT-01 p. 4", null, null, "C317"],
  ["Thermodynamic Units and Properties", "What conversion factors on the NRC equation sheet relate MW to BTU/hr, and BTU to ft-lbf?", "1 MW = 3.41 x 10^6 BTU/hr, and 1 BTU = 778 ft-lbf.", "LP-THERMO-UNITS-AND-PROPERTIES, slide 1.5 Typical Conversion Table", null, null, "C318"],
  // Basic Energy Concepts 6-11 (LP-BASIC-ENERGY-CONCEPTS-6-11)
  ["Basic Energy Concepts", "State the second law of thermodynamics as given in Basic Energy Concepts.", "No engine, actual or ideal, operating in a cycle can convert all the heat supplied to it into mechanical work; heat must be rejected.", "DOE-1012-V1 (DOE-HDBK-1012/1-92), Second Law of Thermodynamics, HT-01 p. 70", null, null, "C319"],
  ["Basic Energy Concepts", "Give three energy conversions that occur in plant systems.", "Velocity energy to pressure energy (water hammer), flow energy to internal energy (head loss), and heat energy to mechanical energy (turbine).", "LP-BASIC-ENERGY-CONCEPTS-6-11, slide 1.6 Laws of Thermodynamics Introduction", null, null, "C320"],
  ["Basic Energy Concepts", "What is entropy, and how can the entropy of a closed system be decreased?", "A measure of a system's inefficiency for doing work for a given heat transferred. The only way to decrease a closed system's entropy is to transfer heat from it.", "LP-BASIC-ENERGY-CONCEPTS-6-11, slide 1.8 Entropy", null, null, "C321"],
  ["Basic Energy Concepts", "How many properties fix the state of a substance, and when does that NOT work?", "Two properties fix the state, except at saturation temperature for a given pressure (under the dome).", "LP-BASIC-ENERGY-CONCEPTS-6-11, slide 1.16 TLO 1 Summary", null, null, "C322"],
  ["Basic Energy Concepts", "What is the specific heat of water?", "About 1.0 BTU/lbm-°F at low temperatures, rising to around 1.4 at higher reactor coolant system temperatures.", "LP-BASIC-ENERGY-CONCEPTS-6-11, slide 1.21 Specific Heat", null, null, "C323"],
  // Cold Traps and Sodium Coolant Purification (LP-COLD-TRAPS-AND-SODIUM-COOLANT-PURIFICATION)
  ["Demineralizers and Ion Exchangers", "What happens if cold trap sodium temperature is too high, or too low?", "Too high: impurities may not precipitate effectively, reducing removal capability. Too low: risk of sodium freezing and solidification.", "LP-COLD-TRAPS-AND-SODIUM-COOLANT-PURIFICATION, slide 1.12 Cold traps", null, null, "C324"],
  ["Demineralizers and Ion Exchangers", "Can RVC cesium filters be regenerated like cold traps?", "No. Their chemical adsorption is slow and irreversible, so regeneration is not effective and they need long-term disposal.", "LP-COLD-TRAPS-AND-SODIUM-COOLANT-PURIFICATION, slide 1.31 Long-Term immobilization and Storage", null, null, "C325"],
  ["Demineralizers and Ion Exchangers", "What hazard must be avoided when using cold traps?", "Condensing oxygen gas into the trap. Liquid oxygen is potentially explosive, especially if the trap has been used to trap solvents.", "LP-COLD-TRAPS-AND-SODIUM-COOLANT-PURIFICATION, slide 1.20 Cautions", null, null, "C326"],
  ["Demineralizers and Ion Exchangers", "Why must sodium hydroxide formation be avoided?", "It can lead to rapid and aggressive caustic stress corrosion cracking.", "LP-COLD-TRAPS-AND-SODIUM-COOLANT-PURIFICATION, slide 1.4 Importance of purifying sodium coolant", null, null, "C327"],
  // Flow Detectors (LP-FLOW-DETECTORS)
  ["Sensors and Detectors", "Match each head flow meter to its description: orifice, nozzle, venturi, pitot.", "Orifice: simplest and most economical. Nozzle: high-velocity flows. Venturi: most accurate. Pitot: high-pressure input at zero velocity.", "LP-FLOW-DETECTORS, slide 1.22 Match the Differential Flow Meter with the description.", null, null, "C328"],
  ["Sensors and Detectors", "How do these conditions affect a D/P flow indication: high-side leak, low-side leak, orifice erosion, vapor in liquid?", "High-side leak: lower than actual. Low-side leak: higher than actual. Orifice erosion: gradually lowering readings. Vapor in liquid: erratic indication.", "LP-FLOW-DETECTORS, slide 1.30 Match the following responses with the condition presented in the question below.", null, null, "C329"],
  ["Sensors and Detectors", "What does a pitot tube actually measure?", "Fluid velocity, not flow rate.", "DOE-1013-V1 (DOE-HDBK-1013/1-92), Head Flow Meters, IC-04 p. 6", null, {"f": "images/doe-1013-v1-ic-04-fig5.png", "alt": "Pipe with a pitot tube facing the flow and a pressure tap, connected to high and low pressure inputs.", "cap": "Figure 5. Pitot Tube. Source: DOE-1013-V1 (DOE-HDBK-1013/1-92), IC-04 p. 6.", "at": "a"}, "C330"],
  ["Sensors and Detectors", "On what principle does an electromagnetic (EM) flowmeter work?", "A conductive liquid flowing through a magnetic field generates a voltage directly proportional to fluid velocity.", "LP-FLOW-DETECTORS, slide 1.19 Sodium Flow Metering: EM Flow Meters", null, null, "C331"],
  // Fluid Statics and Dynamics - Part 1 (LP-FLUID-STATICS-AND-DYNAMICS-PART-1)
  ["Fluid Statics and Dynamics", "What is an ideal fluid?", "An incompressible fluid with no viscosity.", "DOE-1012-V3 (DOE-HDBK-1012/3-92), Laminar and Turbulent Flow, HT-03 p. 19", null, null, "C332"],
  ["Fluid Statics and Dynamics", "What is the principle of buoyancy?", "An object in a fluid is buoyed by a force equal to the weight of the fluid it displaces.", "DOE-1012-V3 (DOE-HDBK-1012/3-92), Continuity Equation, HT-03 p. 2", null, null, "C333"],
  ["Fluid Statics and Dynamics", "How does the maximum velocity compare with the average in laminar pipe flow?", "The profile is parabolic, and the maximum velocity at the center is about twice the average.", "DOE-1012-V3 (DOE-HDBK-1012/3-92), Laminar and Turbulent Flow, HT-03 p. 20", null, {"f": "images/doe-1012-v3-ht-03-fig5.png", "alt": "Velocity profiles in a pipe: a parabola for laminar flow and a flatter curve for turbulent flow, with smooth and rough pipe walls compared.", "cap": "Figure 5. Laminar and Turbulent Flow Velocity Profiles. Source: DOE-1012-V3 (DOE-HDBK-1012/3-92), HT-03 p. 18.", "at": "a"}, "C334"],
  ["Sensors and Detectors", "When is density compensation needed for a flow instrument?", "When measuring mass flow of a fluid with large pressure or temperature changes. It is unnecessary if the instrument measures volume.", "DOE-1013-V1 (DOE-HDBK-1013/1-92), Head Flow Meters, IC-04 p. 2", null, null, "C335"],
  // Fluid Statics and Dynamics - Part 2 (LP-FLUID-STATICS-AND-DYNAMICS-PART-2)
  ["Fluid Statics and Dynamics", "How does head loss change when system flow is raised?", "It goes up exponentially, because head loss varies with the square of velocity.", "LP-FLUID-STATICS-AND-DYNAMICS-PART-2, slide 1.57 What happens to head loss when the system flow is raised?", null, null, "C336"],
  ["Fluid Statics and Dynamics", "Why start smaller capacity pumps before larger ones?", "To raise system pressure gradually and reduce the risk of sudden pressure surges (water hammer).", "LP-FLUID-STATICS-AND-DYNAMICS-PART-2, slide 1.60 Why is it recommended to start smaller capacity pumps before larger capacity pumps to prevent water hammer?", null, null, "C337"],
  ["Pumps", "How does cavitation damage a pump?", "Collapsing bubbles cause cyclic stress on the impeller, casing or piping, leading to premature failure (usually bearing failure) and pitting.", "DOE-1018-V1 (DOE-HDBK-1018/1-93), Centrifugal Pump Operation, ME-03 p. 12", null, null, "C338"],
  ["Fluid Statics and Dynamics", "What is water hammer?", "A physical shock to fluid system components caused by the impact of high-velocity liquid.", "DOE-1012-V3 (DOE-HDBK-1012/3-92), Two-Phase Fluid Flow, HT-03 p. 43", null, null, "C339"],
  ["Fluid Statics and Dynamics", "How do minor losses vary with velocity in turbulent flow?", "They vary as the square of velocity, and they are often more important than pipe friction losses.", "DOE-1012-V3 (DOE-HDBK-1012/3-92), Head Loss, HT-03 p. 34", null, null, "C340"],
  // Pumps (LP-PUMPS)
  ["Pumps", "What happens to flow and pump head when a centrifugal pump's discharge valve is shut?", "Flow decreases and pump head increases.", "LP-PUMPS, slide 1.56 Knowledge Check Deadhead and Runout Operations 2", null, null, "C341"],
  ["Pumps", "Where is a pump system's operating point?", "In most cases, where the pump head equals the head loss in the system.", "DOE-1012-V3 (DOE-HDBK-1012/3-92), Centrifugal Pumps, HT-03 p. 52", null, {"f": "images/doe-1012-v3-ht-03-fig10.png", "alt": "Pump curve crossing two system curves; opening a valve moves the operating point to higher flow and lower head.", "cap": "Figure 10. Operating Point for a Centrifugal Pump. Source: DOE-1012-V3 (DOE-HDBK-1012/3-92), HT-03 p. 52.", "at": "a"}, "C342"],
  ["Pumps", "What does a centrifugal pump diffuser do?", "An increasing flow area reduces flow velocity, converting kinetic energy into pressure.", "DOE-1018-V1 (DOE-HDBK-1018/1-93), Centrifugal Pumps, ME-03 p. 3", null, {"f": "images/doe-1018-v1-me-03-fig3.png", "alt": "Impeller surrounded by a ring of stationary diffuser vanes inside the pump casing.", "cap": "Figure 3. Centrifugal Pump Diffuser. Source: DOE-1018-V1 (DOE-HDBK-1018/1-93), ME-03 p. 3.", "at": "a"}, "C343"],
  ["Pumps", "What is a lantern ring for?", "It receives cool, clean gland sealing water to cool and lubricate the packing; important when pump suction is under a vacuum.", "DOE-1018-V1 (DOE-HDBK-1018/1-93), Centrifugal Pumps, ME-03 p. 9", null, {"f": "images/doe-1018-v1-me-03-fig10.png", "alt": "Pump cross section labeling the casing, shaft, impeller, volute, stuffing box, gland, packing, lantern ring, and impeller and casing wearing rings.", "cap": "Figure 10. Centrifugal Pump Components. Source: DOE-1018-V1 (DOE-HDBK-1018/1-93), ME-03 p. 8.", "at": "a"}, "C344"],
  // Valve Fundamentals (LP-VALVE-FUNDAMENTALS)
  ["Valves", "Why aren't gate valves used to throttle flow?", "The turbulent flow through a partly open gate valve erodes the valve seat. Also, the first 25% of disk opening changes flow much more than the last 25%.", "DOE-1018-V2 (DOE-HDBK-1018/2-93), Types of Valves, ME-04 p. 10", null, null, "C345"],
  ["Valves", "Which valve types are good choices for throttling flow?", "Globe and needle valves.", "LP-VALVE-FUNDAMENTALS, slide 1.15 Globe and Needle Valves", null, null, "C346"],
  ["Valves", "What are the advantages of a ball valve?", "Generally the least expensive valve configuration, with low maintenance costs and the least frictional head loss.", "DOE-1018-V2 (DOE-HDBK-1018/2-93), Types of Valves, ME-04 p. 19", null, null, "C347"],
  ["Valves", "How does an electric solenoid valve actuator open and close the valve?", "Coil current creates a magnetic field that pulls the armature up, compressing the spring and opening the valve. When current stops, the spring shuts the valve.", "DOE-1013-V2 (DOE-HDBK-1013/2-92), Valve Actuators, IC-07 p. 58", null, {"f": "images/doe-1013-v2-ic-07-fig38.png", "alt": "Solenoid actuator with a coil, an armature, a spring, and a stem.", "cap": "Figure 38. Electric Solenoid Actuator. Source: DOE-1013-V2 (DOE-HDBK-1013/2-92), IC-07 p. 58.", "at": "a"}, "C348"],
  ["Valves", "How do safety valves and relief valves open differently?", "A safety valve pops fully open at its setpoint. A relief valve opens gradually as pressure rises above its setpoint.", "DOE-1018-V2 (DOE-HDBK-1018/2-93), Types of Valves, ME-04 p. 40", null, null, "C349"],
  ["Valves", "What is safety valve blowdown?", "The difference between the valve's setpoint and the pressure at which it reseats.", "DOE-1018-V2 (DOE-HDBK-1018/2-93), Types of Valves, ME-04 p. 40", null, null, "C350"],
  ["Valves", "What is a relief valve gagging device for?", "To prevent the valve from actuating during hydrostatic testing.", "LP-VALVE-FUNDAMENTALS, slide 1.91 Gagging Relief and Safety Valves", null, null, "C351"],
  ["Valves", "How does opening or closing a valve affect flow and upstream backpressure?", "Opening: flow increases, upstream backpressure decreases. Closing: flow decreases, upstream backpressure increases.", "LP-VALVE-FUNDAMENTALS, slide 1.63 Valve Position and Fluid Flow", null, null, "C352"],
  ["Valves", "What can cause thermal binding of a valve?", "Components of different materials and thicknesses cooling at different rates.", "LP-VALVE-FUNDAMENTALS, slide 1.57 Thermal Binding of Gate Valves", null, null, "C353"],
  // Variable Frequency Drives (LP-VARIABLE-FREQUENCY-DRIVES)
  ["Motors and Generators", "What do VFD harmonic (line) filters and output filters do?", "Line filters reduce electrical noise and distortion in the power supply. Output filters reduce voltage spikes and protect motor insulation.", "LP-VARIABLE-FREQUENCY-DRIVES, slide 1.42 Question 12", null, null, "C354"],
  ["Motors and Generators", "How is AC motor speed related to supply frequency?", "Directly proportional: synchronous speed = (120 × frequency) / number of poles.", "DOE-1011-V4 (DOE-HDBK-1011/4-92), Ac Motor Theory, ES-12 p. 6", null, null, "C355"],
  ["Motors and Generators", "How do VFDs improve energy efficiency?", "They let the motor run at the speed and torque the load needs instead of full speed.", "LP-VARIABLE-FREQUENCY-DRIVES, slide 1.26 Question 7", null, null, "C356"],
  // Controllers and Positioners (LP-CONTROLLERS-AND-POSITIONERS)
  ["Controllers and Positioners", "How are controller gain and proportional band related?", "Gain is the reciprocal of proportional band. Raising gain tightens (lowers) the proportional band.", "DOE-1013-V2 (DOE-HDBK-1013/2-92), Two Position Control Systems, IC-07 p. 21", null, null, "C357"],
  ["Controllers and Positioners", "What are the four common modes of automatic process control?", "Proportional; proportional-integral (proportional-plus-reset); proportional-derivative (proportional-plus-rate); and proportional-integral-derivative.", "DOE-1013-V2 (DOE-HDBK-1013/2-92), Pid Control Systems, IC-07 p. 43", null, null, "C358"],
  ["Controllers and Positioners", "What output does an integrator (reset) provide?", "A linear output whose rate of change is directly proportional to the magnitude of the input.", "DOE-1013-V2 (DOE-HDBK-1013/2-92), Reset (Integral) Control Systems, IC-07 p. 28", null, {"f": "images/doe-1013-v2-ic-07-fig19.png", "alt": "Integrator input step and the output ramp that rises at a constant rate.", "cap": "Figure 19. Integral Output for a Fixed Input. Source: DOE-1013-V2 (DOE-HDBK-1013/2-92), IC-07 p. 29.", "at": "a"}, "C359"],
  ["Controllers and Positioners", "What sets a pneumatic actuator's failure position, and what is a fail-open valve called?", "The spring. A valve that fails open on loss of air is air-to-close, spring-to-open.", "DOE-1013-V2 (DOE-HDBK-1013/2-92), Valve Actuators, IC-07 p. 56", null, {"f": "images/doe-1013-v2-ic-07-fig35.png", "alt": "Pneumatic actuator: supply air above a rubber diaphragm, a spring below, and a stem to the control valve.", "cap": "Figure 35. Pneumatic Actuator: Air-to-Close/Spring-to-Open. Source: DOE-1013-V2 (DOE-HDBK-1013/2-92), IC-07 p. 54.", "at": "a"}, "C360"],
  ["Controllers and Positioners", "What is isochronous mode for a diesel generator?", "Used when the D/G alone supplies an emergency bus: it runs at 60 Hz and adjusts fuel as loads start and stop to hold constant frequency.", "LP-CONTROLLERS-AND-POSITIONERS, slide 1.77 Knowledge Check", null, null, "C361"],
  ["Controllers and Positioners", "When is a PI controller chosen, and when a PD controller?", "PI: processes intolerant of continuous cycling or offset error. PD: processes needing more stability that can tolerate some offset.", "LP-CONTROLLERS-AND-POSITIONERS, slide 1.47 Proportional-Integral-Derivative", null, null, "C362"],
  // Sensors and Detectors Part 2 (LP-SENSORS-AND-DETECTORS-PART-2)
  ["Sensors and Detectors", "Why is a Geiger-Mueller counter more sensitive than a proportional counter?", "It produces many more electrons, making it ideal for detecting low-level gamma rays and beta particles.", "DOE-1013-V2 (DOE-HDBK-1013/2-92), Geiger-Müller Detector, IC-06 p. 43", null, null, "C363"],
  ["Sensors and Detectors", "In a scintillation detector, what does the amount of light produced indicate?", "The energy of the incoming particle; light output is proportional to it.", "DOE-1013-V2 (DOE-HDBK-1013/2-92), Scintillation Counter, IC-06 p. 47", null, null, "C364"],
  ["Sensors and Detectors", "What radiation does a self-reading pocket dosimeter measure, and what is its main advantage?", "Gamma; alpha and beta cannot pass through the metal casing. Its main advantage is an immediate reading of accumulated dose.", "LP-SENSORS-AND-DETECTORS-PART-2, slide 1.72 Self-Reading Pocket Dosimeter", null, null, "C365"],
  ["Sensors and Detectors", "Where should a self-reading pocket dosimeter be worn?", "Above the waist near the TLD, to measure radiation from the same sources.", "LP-SENSORS-AND-DETECTORS-PART-2, slide 1.75 Knowledge Check: Self-Reading Pocket Dosimeter 1", null, null, "C366"],
  ["Sensors and Detectors", "How low a dose can a TLD measure?", "As low as 1 millirem.", "LP-SENSORS-AND-DETECTORS-PART-2, slide 1.70 Thermoluminescent Dosimeter", null, null, "C367"],
  ["Sensors and Detectors", "Why do the source, intermediate and power range nuclear instruments overlap?", "To allow continuous reactor power monitoring under all conditions.", "LP-SENSORS-AND-DETECTORS-PART-2, slide 1.85 Nuclear Instrument Detectors", null, null, "C368"],
  ["Sensors and Detectors", "What do the source range nuclear instruments monitor, and when?", "Neutron flux level and its rate of change during shutdown and the initial phase of startup.", "LP-SENSORS-AND-DETECTORS-PART-2, slide 1.86 Nuclear Instrument Detectors - SR", null, null, "C369"],
  // Reactivity Coefficients Module 1 (LP-REACTIVITY-COEFFICIENTS-MODULE-1)
  ["Reactivity Coefficients", "What mainly determines the magnitude and sign of the SFR coolant temperature coefficient?", "Core size and fuel loading.", "LP-REACTIVITY-COEFFICIENTS-MODULE-1, slide 1.12 CTC Equation", null, null, "C371"],
  ["Reactivity Coefficients", "How is the excess reactivity of an SFR core balanced?", "Primarily by inserting control rods.", "LP-REACTIVITY-COEFFICIENTS-MODULE-1, slide 1.3 Reactivity Control Mechanisms", null, null, "C372"],
  // Reactivity Coefficients - Module 2 (LP-REACTIVITY-COEFFICIENTS-MODULE-2)
  ["Reactivity Coefficients", "How do U-238 content and moderation affect Doppler in a sodium fast reactor?", "Doppler is enhanced by high U-238 content but reduced by the lack of an effective moderator.", "LP-REACTIVITY-COEFFICIENTS-MODULE-2, slide 1.13 Doppler Effect", null, null, "C373"],
  // Reactivity Coefficients Module 3 (LP-REACTIVITY-COEFFICIENTS-MODULE-3)
  ["Reactivity Coefficients", "How does axial fuel expansion add negative reactivity?", "It reduces fuel density and causes more radial leakage.", "LP-REACTIVITY-COEFFICIENTS-MODULE-3, slide 1.25 Axial expansion produces a negative reactivity effect in a reactor core by…", null, null, "C374"],
  ["Control Rods", "Why are control rods the primary means of reactivity control in an SFR?", "Unlike LWRs, boron dilution in sodium is not possible.", "LP-REACTIVITY-COEFFICIENTS-MODULE-3, slide 1.16 Control rods", null, null, "C375"],
  ["Reactivity Coefficients", "Which acts faster, the coolant or the fuel temperature coefficient, and why?", "The fuel temperature coefficient is the quickest acting because fuel temperature changes immediately with power. The coolant coefficient is slow because heat must first reach the coolant.", "LP-REACTIVITY-COEFFICIENTS-MODULE-3, slide 1.5 Axial Expansion Coefficient", null, null, "C376"],
  // Control Rods (LP-CONTROL-RODS)
  ["Control Rods", "What are the advantages of boron carbide (B4C) as a control rod absorber?", "High absorption cross section, readily available and low cost, relatively easy to fabricate, and low radioactivity at end of life.", "DOE-1017-V2 (DOE-HDBK-1017/2-93), Control Materials, MS-05 p. 16", null, null, "C378"],
  ["Control Rods", "What does control rod worth depend on?", "Rod location and the neutron flux there. Rods near the core center generally have more worth than those near the edge.", "DOE-1019-V2 (DOE-HDBK-1019/2-93), Control Rods, NP-03 p. 52", null, {"f": "images/doe-1019-v2-np-03-fig10.png", "alt": "Differential rod worth against rod position: a bell-shaped curve peaking at the core center.", "cap": "Figure 10. Differential Control Rod Worth. Source: DOE-1019-V2 (DOE-HDBK-1019/2-93), NP-03 p. 52.", "at": "a"}, "C380"],
  ["Control Rods", "What are rod insertion limits designed to do?", "Minimize the consequences of an uncontrolled rod withdrawal, provide an even axial flux distribution, and provide adequate shutdown margin.", "LP-CONTROL-RODS, slide 1.36 Rod Insertion Limits", null, null, "C381"],
  ["Control Rods", "What is a key concept of flux shaping with control rods?", "Flux follows the control rods; withdrawing rods shifts flux upward.", "LP-CONTROL-RODS, slide 1.34 Flux Profiles", null, null, "C382"],
  ["Control Rods", "What is a reactor reflector?", "Material in or near the reactor that reflects neutrons back into the core.", "DOE-1017-V2 (DOE-HDBK-1017/2-93), Cladding and Reflectors, MS-05 p. 14", null, null, "C383"],
  ["Control Rods", "What happens to the control rods on a reactor scram?", "They are de-energized, and all partly or fully withdrawn rods drop into the core by gravity.", "LP-CONTROL-RODS, slide 1.37 Reactor Trip/Scram", null, null, "C384"],
  // Power Changes (LP-POWER-CHANGES)
  ["Reactor Kinetics and Neutron Sources", "How does core age affect startup rate for a given reactivity insertion?", "As the core ages and beta-eff decreases, SUR becomes larger in magnitude.", "LP-POWER-CHANGES, slide 1.21 KC P3449", null, null, "C385"],
  ["Reactor Kinetics and Neutron Sources", "What stable negative period follows a large negative reactivity insertion such as a scram, and what sets it?", "About -80 seconds (-1/3 dpm), set by Br-87, the longest-lived precursor (decay constant 0.0124 per second).", "DOE-1019-V2 (DOE-HDBK-1019/2-93), Reactor Operation, NP-04 p. 32", null, null, "C386"],
  ["Reactor Kinetics and Neutron Sources", "A subcritical reactor receives +0.15 %Δk/k of positive reactivity and becomes supercritical. What reactivity value is used to find its period?", "The net +0.05 %Δk/k in the core.", "LP-POWER-CHANGES, slide 1.18 KC P6825", null, null, "C387"],
  ["Reactor Kinetics and Neutron Sources", "When does a prompt drop usually occur?", "With a reactor scram, when a very large amount of negative reactivity is added.", "DOE-1019-V2 (DOE-HDBK-1019/2-93), Reactor Operation, NP-04 p. 31", null, null, "C388"],
  ["Brittle Fracture and Vessel Thermal Stress", "What operational limits reduce the severity of thermal shock?", "Heatup and cooldown rate limits, temperature limits for placing systems into operation, and specific temperatures for specific pressures for system operation.", "DOE-1017-V2 (DOE-HDBK-1017/2-93), Thermal Stress, MS-03 p. 5", null, null, "C389"],
  ["Brittle Fracture and Vessel Thermal Stress", "What is pressurized thermal shock (PTS)?", "Shock experienced by a thick-walled vessel due to the combined stresses from a rapid temperature and/or pressure change.", "DOE-1017-V2 (DOE-HDBK-1017/2-93), Pressurized Thermal Shock, MS-03 p. 6", null, null, "C390"],
  ["Brittle Fracture and Vessel Thermal Stress", "During system heatup, which vessel wall location is limiting, and why?", "The 3/4 T location. Pressure and temperature stresses there are both tensile and reinforce each other.", "DOE-1017-V2 (DOE-HDBK-1017/2-93), Pressurized Thermal Shock, MS-03 p. 7", null, {"f": "images/doe-1017-v2-ms-03-fig2.png", "alt": "Reactor vessel wall stress profile during heatup. Pressure stress and temperature-induced stress are plotted between the inner and outer wall, with tensile stress to the right and compressive stress to the left, and the 1/4T and 3/4T locations marked.", "cap": "Figure 2. Heatup Stress Profile. Source: DOE-1017-V2 (DOE-HDBK-1017/2-93), MS-03 p. 7.", "at": "a"}, "C391"],
  ["Brittle Fracture and Vessel Thermal Stress", "During system cooldown, which vessel wall location is limiting?", "The 1/4 T location, where pressure and temperature stresses are both tensile and reinforce each other.", "DOE-1017-V2 (DOE-HDBK-1017/2-93), Pressurized Thermal Shock, MS-03 p. 7", null, {"f": "images/doe-1017-v2-ms-03-fig3.png", "alt": "Reactor vessel wall stress profile during cooldown, with the same layout as the heatup profile. Pressure stress and temperature-induced stress are plotted between the inner and outer wall at the 1/4T and 3/4T locations.", "cap": "Figure 3. Cooldown Stress Profile. Source: DOE-1017-V2 (DOE-HDBK-1017/2-93), MS-03 p. 7.", "at": "a"}, "C392"],
  ["Brittle Fracture and Vessel Thermal Stress", "What three conditions does brittle fracture require?", "A flaw such as a crack, stress sufficient to develop a small deformation at the crack tip, and a temperature at or below NDT.", "DOE-1017-V2 (DOE-HDBK-1017/2-93), Brittle Fracture Mechanism, MS-04 p. 6", null, {"f": "images/doe-1017-v2-ms-04-fig3.png", "alt": "Stress against temperature relative to NDT, with fracture initiation curves for 1, 8, 12, and 24 inch flaws, the crack arrest curve, FTE, and FTP.", "cap": "Figure 3. Fracture Diagram. Source: DOE-1017-V2 (DOE-HDBK-1017/2-93), MS-04 p. 5.", "at": "a"}, "C393"],
  ["Brittle Fracture and Vessel Thermal Stress", "What is the nil-ductility transition (NDT) temperature?", "The temperature above which a material is ductile and below which it is brittle.", "DOE-1017-V2 (DOE-HDBK-1017/2-93), Brittle Fracture Mechanism, MS-04 p. 6", null, {"f": "images/doe-1017-v2-ms-04-fig2.png", "alt": "Graph of stress against temperature. Tensile strength and yield strength curves rise as temperature falls and meet at the NDT with no flaw, near 10 degrees F. The NDT with a small flaw is near 60 degrees F, and the crack arrest curve rises to the FTE and FTP points near 70 degrees F.", "cap": "Figure 2. Stress-Temperature Diagram for Crack Initiation and Arrest. Source: DOE-1017-V2 (DOE-HDBK-1017/2-93), MS-04 p. 3.", "at": "a"}, "C394"],
  ["Brittle Fracture and Vessel Thermal Stress", "Which components limit heatup and cooldown rates?", "Large components such as flanges, the reactor vessel head, and the vessel itself.", "DOE-1017-V2 (DOE-HDBK-1017/2-93), Heatup and Cooldown Rate Limits, MS-04 p. 13", null, null, "C395"],
  ["Brittle Fracture and Vessel Thermal Stress", "What causes thermal fatigue?", "Thermal stresses produced by cyclic changes in temperature.", "DOE-1017-V2 (DOE-HDBK-1017/2-93), Plant Material Problems, MS-05 p. 31", null, null, "C396"],
  ["Core Thermal Limits", "What operational limit lessens fuel pellet-cladding interaction (PCI)?", "Plant procedures limit the maximum permissible rate at which power may be increased.", "DOE-1017-V2 (DOE-HDBK-1017/2-93), Nuclear Reactor Core Problems, MS-05 p. 25", null, null, "C398"],
  ["Sensors and Detectors", "How does the resistance of an RTD change with temperature?", "It varies directly: as temperature increases, resistance increases, and as temperature decreases, resistance decreases.", "DOE-1013-V1 (DOE-HDBK-1013/1-92), Resistance Temperature Detectors, IC-01 p. 4", null, null, "C399"],
  ["Sensors and Detectors", "In a thermocouple, what does the voltmeter measure?", "The difference between the measuring-junction and reference-junction voltages, which is proportional to the difference in temperature.", "DOE-1013-V1 (DOE-HDBK-1013/1-92), Thermocouples, IC-01 p. 7", null, {"f": "images/doe-1013-v1-ic-01-fig6.png", "alt": "Two dissimilar metal wires joined at a hot measuring junction above a heat source and at a cold reference junction, with a voltmeter connected in the circuit.", "cap": "Figure 6. Simple Thermocouple Circuit. Source: DOE-1013-V1 (DOE-HDBK-1013/1-92), IC-01 p. 6.", "at": "a"}, "C400"],
  ["Sensors and Detectors", "When is a temperature bridge circuit considered balanced?", "When the sensing ammeter reads zero current.", "DOE-1013-V1 (DOE-HDBK-1013/1-92), Temperature Detection Circuitry, IC-01 p. 16", null, null, "C401"],
  ["Sensors and Detectors", "Why does a bourdon tube move as pressure rises?", "As pressure increases, the tube tends to restore to its original round cross-section, and this change causes the tube to straighten.", "DOE-1013-V1 (DOE-HDBK-1013/1-92), Pressure Detectors, IC-02 p. 3", null, {"f": "images/doe-1013-v1-ic-02-fig2.png", "alt": "Bourdon tube gauge. Inlet pressure enters a curved tube linked through a mechanical linkage and pinion to a pointer on a dial. Cross sections show the tube flattened with no internal pressure and rounder with internal pressure.", "cap": "Figure 2. Bourdon Tube. Source: DOE-1013-V1 (DOE-HDBK-1013/1-92), IC-02 p. 2.", "at": "a"}, "C402"],
  ["Sensors and Detectors", "How does a strain gauge sense pressure?", "It measures the pressure applied to a fine wire, usually arranged as a grid. The pressure change distorts the wire and changes its resistance.", "DOE-1013-V1 (DOE-HDBK-1013/1-92), Pressure Detection Circuitry, IC-02 p. 13", null, null, "C403"],
  ["Sensors and Detectors", "In a closed tank with a wet reference leg, how does transmitter output relate to tank level?", "The differential pressure and the transmitter output are inversely proportional to the tank level.", "DOE-1013-V1 (DOE-HDBK-1013/1-92), Level Detectors, IC-03 p. 9", null, {"f": "images/doe-1013-v1-ic-03-fig11.png", "alt": "Closed tank with a differential pressure transmitter. The high pressure side connects to a liquid-filled wet reference leg with a fill connection, tied into the tank at the maximum detectable level. The low pressure side connects to the tank at the minimum detectable level.", "cap": "Figure 11. Closed Tank, Wet Reference Leg. Source: DOE-1013-V1 (DOE-HDBK-1013/1-92), IC-03 p. 9.", "at": "a"}, "C404"],
  ["Sensors and Detectors", "By what three means is level density compensation accomplished?", "Electronic circuitry, pressure detector input, or instrument calibration.", "DOE-1013-V1 (DOE-HDBK-1013/1-92), Density Compensation, IC-03 p. 14", null, null, "C405"],
  ["Sensors and Detectors", "What are three major reasons for remote level indication?", "The measurement location may be far from the main facility, the level may be a long distance from the point of control, or the level may be in an unsafe or radioactive area.", "DOE-1013-V1 (DOE-HDBK-1013/1-92), Level Detection Circuitry, IC-03 p. 17", null, null, "C406"],
  ["Sensors and Detectors", "What does the extractor do in a differential pressure flow circuit?", "It electronically calculates the square root of the differential pressure and provides an output proportional to system flow.", "DOE-1013-V1 (DOE-HDBK-1013/1-92), Flow Circuitry, IC-04 p. 19", null, null, "C407"],
  ["Sensors and Detectors", "What does a basic synchro system consist of?", "A transmitter (synchro generator) and a receiver (synchro motor).", "DOE-1013-V1 (DOE-HDBK-1013/1-92), Synchro Equipment, IC-05 p. 4", null, {"f": "images/doe-1013-v1-ic-05-fig2.png", "alt": "Synchro transmitter wired to a synchro receiver.", "cap": "Figure 2. Simple Synchro System. Source: DOE-1013-V1 (DOE-HDBK-1013/1-92), IC-05 p. 3.", "at": "a"}, "C408"],
  ["Sensors and Detectors", "What is specific ionization?", "The number of ion pairs produced per centimeter of travel through matter.", "DOE-1013-V2 (DOE-HDBK-1013/2-92), Radiation Detection Terminology, IC-06 p. 1", null, null, "C409"],
  ["Sensors and Detectors", "What is gas amplification?", "The multiplication of electrons that occurs when ion pairs accelerate enough to cause secondary ionizations, and the resulting ions cause further ionizations.", "DOE-1013-V2 (DOE-HDBK-1013/2-92), Gas-Filled Detector, IC-06 p. 13", null, {"f": "images/doe-1013-v2-ic-06-fig8.png", "alt": "Graph of number of electrons collected, on a log scale, against detector voltage from 0 to about 1800 volts, showing the recombination region rising, the flat ionization region, and the rising proportional region.", "cap": "Figure 8. Gas Ionization Curve. Source: DOE-1013-V2 (DOE-HDBK-1013/2-92), IC-06 p. 20.", "at": "a"}, "C410"],
  ["Sensors and Detectors", "Why is a quenching gas added to a proportional counter?", "To give up electrons to the chamber gas, so that inaccuracies are not introduced by ionizations caused by the positive ion.", "DOE-1013-V2 (DOE-HDBK-1013/2-92), Proportional Counter, IC-06 p. 22", null, null, "C411"],
  ["Sensors and Detectors", "How is gamma sensitivity reduced in an ionization chamber?", "By reducing the amount of chamber gas or increasing the boron coated surface area.", "DOE-1013-V2 (DOE-HDBK-1013/2-92), Ionization Chamber, IC-06 p. 34", null, null, "C412"],
  ["Sensors and Detectors", "How does a compensated ion chamber cancel gamma current?", "The voltages are set so the gamma current in the boron-coated chamber cancels the gamma current in the uncoated chamber.", "DOE-1013-V2 (DOE-HDBK-1013/2-92), Compensated Ion Chamber, IC-06 p. 39", null, {"f": "images/doe-1013-v2-ic-06-fig19.png", "alt": "Two circuit drawings of a compensated ion chamber. A boron-lined chamber A and an unlined chamber B are connected to an electrometer with opposing voltage supplies, so the electrometer current equals neutron current minus gamma current.", "cap": "Figure 19. Compensated Ion Chamber. Source: DOE-1013-V2 (DOE-HDBK-1013/2-92), IC-06 p. 35.", "at": "a"}, "C413"],
  ["Sensors and Detectors", "What does a multichannel analyzer do in a gamma spectrometer?", "It separates the pulses based on pulse height.", "DOE-1013-V2 (DOE-HDBK-1013/2-92), Gamma Spectroscopy, IC-06 p. 50", null, {"f": "images/doe-1013-v2-ic-06-fig27.png", "alt": "Block diagram of a gamma spectrometer with a detector, amplifier, multichannel analyzer, and readout.", "cap": "Figure 27. Gamma Spectrometer Block Diagram. Source: DOE-1013-V2 (DOE-HDBK-1013/2-92), IC-06 p. 49.", "at": "a"}, "C414"],
  ["Sensors and Detectors", "What does decades per minute measure?", "The rate at which neutron flux is changing by a power of 10 in each minute.", "DOE-1013-V2 (DOE-HDBK-1013/2-92), Circuitry and Circuit Elements, IC-06 p. 62", null, null, "C415"],
  ["Controllers and Positioners", "What separates an open-loop from a closed-loop control system?", "In an open-loop system the control action is independent of the output. In a closed-loop system it depends on the output.", "DOE-1013-V2 (DOE-HDBK-1013/2-92), Principles of Control Systems, IC-07 p. 2", null, {"f": "images/doe-1013-v2-ic-07-fig3.png", "alt": "Block diagram of feedback: measured level is compared with desired level and fed back to the control action.", "cap": "Figure 3. Feedback in a Closed-Loop Control System. Source: DOE-1013-V2 (DOE-HDBK-1013/2-92), IC-07 p. 3.", "at": "a"}, "C416"],
  ["Controllers and Positioners", "What is the proportional band?", "The change in input required to produce a full range of change in the output due to the proportional control action.", "DOE-1013-V2 (DOE-HDBK-1013/2-92), Proportional Control Systems, IC-07 p. 27", null, null, "C417"],
  ["Controllers and Positioners", "What is an inherent disadvantage of proportional plus reset controllers subject to large error signals?", "Reset windup.", "DOE-1013-V2 (DOE-HDBK-1013/2-92), Proportional Plus Reset Control Systems, IC-07 p. 36", null, null, "C418"],
  ["Controllers and Positioners", "What does each action in a PID controller do?", "The proportional action responds to the error amplitude, the integral action eliminates the offset error, and the derivative action provides additional stability.", "DOE-1013-V2 (DOE-HDBK-1013/2-92), PID Control Systems, IC-07 p. 46", null, {"f": "images/doe-1013-v2-ic-07-fig30.png", "alt": "Curves of the proportional, reset, and rate actions and their combined output for a slowly increasing error.", "cap": "Figure 30. PID Control Action Responses. Source: DOE-1013-V2 (DOE-HDBK-1013/2-92), IC-07 p. 44.", "at": "a"}, "C419"],
  ["Brittle Fracture and Vessel Thermal Stress", "What is stress?", "The internal resistance of a material to the distorting effects of an external force or load.", "DOE-1017-V1 (DOE-HDBK-1017/1-93), Stress, MS-02 p. 6", null, null, "C420"],
  ["Brittle Fracture and Vessel Thermal Stress", "What is strain?", "The proportional dimensional change, or the intensity or degree of distortion, in a material under stress.", "DOE-1017-V1 (DOE-HDBK-1017/1-93), Strain, MS-02 p. 10", null, null, "C421"],
  ["Brittle Fracture and Vessel Thermal Stress", "What is plastic deformation?", "The dimensional change that does not disappear when the initiating stress is removed.", "DOE-1017-V1 (DOE-HDBK-1017/1-93), Strain, MS-02 p. 10", null, null, "C422"],
  ["Brittle Fracture and Vessel Thermal Stress", "State Hooke's Law.", "In the elastic range of a material, strain is proportional to stress.", "DOE-1017-V1 (DOE-HDBK-1017/1-93), Young's Modulus, MS-02 p. 14", null, null, "C423"],
  ["Brittle Fracture and Vessel Thermal Stress", "What is yield strength?", "The stress at which a predetermined amount of permanent deformation occurs.", "DOE-1017-V1 (DOE-HDBK-1017/1-93), Physical Properties, MS-02 p. 28", null, {"f": "images/doe-1017-v1-ms-02-fig5.png", "alt": "Stress-strain curve with stress on the vertical axis and elongation in percent on the horizontal axis. Numbered points mark the proportional limit, yield strength, ultimate tensile strength, and fracture point within about 1 percent elongation.", "cap": "Figure 5. Typical Brittle Material Stress-Strain Curve. Source: DOE-1017-V1 (DOE-HDBK-1017/1-93), MS-02 p. 22.", "at": "a"}, "C424"],
  ["Brittle Fracture and Vessel Thermal Stress", "What is ultimate tensile strength (UTS)?", "The maximum resistance to fracture.", "DOE-1017-V1 (DOE-HDBK-1017/1-93), Physical Properties, MS-02 p. 21", null, {"f": "images/doe-1017-v1-ms-02-fig5.png", "alt": "Stress-strain curve with stress on the vertical axis and elongation in percent on the horizontal axis. Numbered points mark the proportional limit, yield strength, ultimate tensile strength, and fracture point within about 1 percent elongation.", "cap": "Figure 5. Typical Brittle Material Stress-Strain Curve. Source: DOE-1017-V1 (DOE-HDBK-1017/1-93), MS-02 p. 22.", "at": "a"}, "C425"],
  ["Brittle Fracture and Vessel Thermal Stress", "What is creep?", "The permanent deformation that increases with time under constant load or stress.", "DOE-1017-V1 (DOE-HDBK-1017/1-93), Grain Structure and Boundary, MS-01 p. 9", null, null, "C426"],
  ["Basic Energy Concepts", "What is energy?", "The ability to do work.", "DOE-1010 (DOE-HDBK-1010-92), Energy and Work, CP-05 p. 5", null, null, "C427"],
  ["Basic Energy Concepts", "What is kinetic energy?", "The energy an object has because of its motion.", "DOE-1010 (DOE-HDBK-1010-92), Energy and Work, CP-05 p. 5", null, null, "C428"],
  ["Basic Energy Concepts", "What is potential energy?", "The energy of an object due to its position.", "DOE-1010 (DOE-HDBK-1010-92), Energy and Work, CP-05 p. 5", null, null, "C429"],
  ["Basic Energy Concepts", "How is the work done by a force defined?", "The product of the force and the distance the object moves in the direction of the force.", "DOE-1010 (DOE-HDBK-1010-92), Energy and Work, CP-05 p. 5", null, null, "C430"],
  ["Basic Energy Concepts", "State the law of conservation of energy.", "Energy cannot be created or destroyed, only altered in form.", "DOE-1010 (DOE-HDBK-1010-92), Law of Conservation of Energy, CP-05 p. 6", null, null, "C431"],
  ["Basic Energy Concepts", "What is power?", "The amount of energy used per unit time.", "DOE-1010 (DOE-HDBK-1010-92), Power, CP-05 p. 11", null, null, "C432"],
  ["Thermodynamic Units and Properties", "What are derived units?", "Units made up of a combination of units to describe various physical quantities, such as area or volume.", "DOE-1010 (DOE-HDBK-1010-92), Fundamental Dimensions, CP-01 p. 8", null, null, "C433"],
  ["Basic Energy Concepts", "State the conservation of momentum.", "If no net external force acts upon a system, the momentum of the system remains constant.", "DOE-1010 (DOE-HDBK-1010-92), Momentum Principles, CP-03 p. 10", null, null, "C434"],
  ["Sensors and Detectors", "What do thermocouples convert, and into what?", "Energy from temperature into a DC voltage.", "DOE-1011-V1 (DOE-HDBK-1011/1-92), DC Sources, ES-02 p. 11", null, null, "C435"],
  ["Breakers, Relays, and Disconnects", "What is a short circuit?", "A circuit with a path that has little or no resistance to current flow.", "DOE-1011-V1 (DOE-HDBK-1011/1-92), DC Circuit Terminology, ES-02 p. 22", null, null, "C436"],
  ["Breakers, Relays, and Disconnects", "What is an open circuit?", "A circuit that does not have a complete path for current flow.", "DOE-1011-V1 (DOE-HDBK-1011/1-92), DC Circuit Terminology, ES-02 p. 22", null, null, "C437"],
  ["Breakers, Relays, and Disconnects", "What does a shorted DC circuit do to circuit current?", "It causes a sudden and very large increase in circuit current.", "DOE-1011-V1 (DOE-HDBK-1011/1-92), DC Circuit Faults, ES-02 p. 69", null, {"f": "images/doe-1011-v1-es-02-fig56.png", "alt": "A battery and resistor R with a shorting connection across the resistor, and a fuse in the circuit.", "cap": "Figure 56. Shorted DC Circuit. Source: DOE-1011-V1 (DOE-HDBK-1011/1-92), ES-02 p. 68.", "at": "a"}, "C438"],
  ["Motors and Generators", "What causes hysteresis losses?", "Reversing current direction thousands of times in a coil.", "DOE-1011-V1 (DOE-HDBK-1011/1-92), Magnetic Circuits, ES-01 p. 44", null, null, "C439"],
  ["Breakers, Relays, and Disconnects", "State Kirchhoff's voltage law.", "The sum of the voltage drops around a closed loop is equal to the sum of the voltage sources of that loop.", "DOE-1011-V1 (DOE-HDBK-1011/1-92), Kirchhoff's Laws, ES-02 p. 48", null, null, "C440"],
  ["Breakers, Relays, and Disconnects", "State Kirchhoff's current law.", "The current arriving at any junction point in a circuit is equal to the current leaving that junction.", "DOE-1011-V1 (DOE-HDBK-1011/1-92), Kirchhoff's Laws, ES-02 p. 48", null, {"f": "images/doe-1011-v1-es-02-fig35.png", "alt": "Arrows for current arriving at and leaving junctions. The total arriving equals the total leaving.", "cap": "Figure 35. Illustration of Kirchhoff’s Current Law. Source: DOE-1011-V1 (DOE-HDBK-1011/1-92), ES-02 p. 46.", "at": "a"}, "C441"],
  ["Motors and Generators", "What three conditions are necessary to induce a voltage into a conductor?", "A magnetic field, a conductor, and relative motion between the two.", "DOE-1011-V2 (DOE-HDBK-1011/2-92), DC Generator Theory, ES-05 p. 12", null, null, "C442"],
  ["Motors and Generators", "How is the terminal voltage of a DC generator adjusted?", "By varying the field strength.", "DOE-1011-V2 (DOE-HDBK-1011/2-92), DC Generator Theory, ES-05 p. 12", null, null, "C443"],
  ["Motors and Generators", "What is counter-electromotive force (CEMF)?", "The induced voltage that acts to counter the applied voltage in a DC motor or a DC generator.", "DOE-1011-V2 (DOE-HDBK-1011/2-92), DC Equipment Terminology, ES-05 p. 2", null, null, "C444"],
  ["Motors and Generators", "Why do large DC motors need starting resistors?", "To prevent damage due to high currents while starting the motor.", "DOE-1011-V2 (DOE-HDBK-1011/2-92), DC Motor Operation, ES-06 p. 14", null, null, "C445"],
  ["Motors and Generators", "What two conditions produce a force on a conductor?", "The conductor must be carrying current, and it must be within a magnetic field.", "DOE-1011-V2 (DOE-HDBK-1011/2-92), DC Motor Theory, ES-06 p. 7", null, null, "C446"],
  ["Motors and Generators", "What is the purpose of a battery?", "To store chemical energy and convert it into electrical energy when the need arises.", "DOE-1011-V2 (DOE-HDBK-1011/2-92), Battery Theory, ES-04 p. 4", null, null, "C447"],
  ["Motors and Generators", "What is specific gravity?", "The ratio comparing the weight of any liquid to the weight of an equal volume of water.", "DOE-1011-V2 (DOE-HDBK-1011/2-92), Battery Terminology, ES-04 p. 1", null, {"f": "images/doe-1011-v2-es-04-fig6.png", "alt": "Graph of a lead-acid cell over time. During discharge, specific gravity and volts per cell fall. During charge, volts per cell jump and climb to full charge while specific gravity rises back toward its starting value.", "cap": "Figure 6. Voltage and Specific Gravity During Charge and Discharge. Source: DOE-1011-V2 (DOE-HDBK-1011/2-92), ES-04 p. 8.", "at": "a"}, "C448"],
  ["Motors and Generators", "What is the armature of an AC generator?", "The part in which output voltage is produced.", "DOE-1011-V3 (DOE-HDBK-1011/3-92), AC Generator Components, ES-10 p. 4", null, null, "C449"],
  ["Motors and Generators", "What is a prime mover?", "The component that is used to drive the AC generator.", "DOE-1011-V3 (DOE-HDBK-1011/3-92), AC Generator Components, ES-10 p. 1", null, null, "C450"],
  ["Motors and Generators", "What do slip rings do in an AC generator?", "They transfer power to and from the rotor.", "DOE-1011-V3 (DOE-HDBK-1011/3-92), AC Generator Components, ES-10 p. 4", null, {"f": "images/doe-1011-v3-es-10-fig1.png", "alt": "A basic AC generator in cutaway, with the rotor, stator, field, slip rings, and output labeled.", "cap": "Figure 1. Basic AC Generator. Source: DOE-1011-V3 (DOE-HDBK-1011/3-92), ES-10 p. 2.", "at": "a"}, "C451"],
  ["Motors and Generators", "What three requirements must be met to parallel AC generators?", "Their terminal voltages must be equal, their frequencies must be equal, and their output voltages must be in phase.", "DOE-1011-V3 (DOE-HDBK-1011/3-92), AC Generator Operation, ES-10 p. 14", null, null, "C452"],
  ["Motors and Generators", "What is impedance?", "The total opposition to current flow in an AC circuit.", "DOE-1011-V3 (DOE-HDBK-1011/3-92), Impedance, ES-08 p. 18", null, null, "C453"],
  ["Motors and Generators", "In the power triangle shown, what does the angle θ represent?", "The angle between voltage and current.", "DOE-1011-V3 (DOE-HDBK-1011/3-92), Power Triangle, ES-09 p. 16", null, {"f": "images/doe-1011-v3-es-09-fig1.png", "alt": "Right triangle with true power P in watts along the base, reactive power Q in VARS on the vertical side, apparent power S in VA along the hypotenuse, and the angle theta between the base and the hypotenuse.", "cap": "Figure 1. Power Triangle. Source: DOE-1011-V3 (DOE-HDBK-1011/3-92), ES-09 p. 2.", "at": "q"}, "C454"],
  ["Controllers and Positioners", "What is the purpose of a voltage regulator?", "To maintain the output voltage of a generator at a desired value.", "DOE-1011-V3 (DOE-HDBK-1011/3-92), Voltage Regulators, ES-11 p. 4", null, {"f": "images/doe-1011-v3-es-11-fig1.png", "alt": "Block diagram of a voltage regulator: sensing and reference circuits feed a comparison circuit, then an amplifier and signal output circuit to the generator field, with a feedback path.", "cap": "Figure 1. Voltage Regulator Block Diagram. Source: DOE-1011-V3 (DOE-HDBK-1011/3-92), ES-11 p. 2.", "at": "a"}, "C455"],
  ["Motors and Generators", "What is slip in an AC motor?", "The percentage difference between the speed of the rotor and the speed of the rotating magnetic field.", "DOE-1011-V4 (DOE-HDBK-1011/4-92), AC Motor Theory, ES-12 p. 8", null, null, "C456"],
  ["Motors and Generators", "Why is a synchronous motor not self-starting?", "Torque is only developed when running at synchronous speed.", "DOE-1011-V4 (DOE-HDBK-1011/4-92), AC Motor Types, ES-12 p. 15", null, null, "C457"],
  ["Motors and Generators", "What is starting torque in an induction motor?", "The value of torque at 100% slip, normally 150 to 200% of full-load torque.", "DOE-1011-V4 (DOE-HDBK-1011/4-92), AC Motor Theory, ES-12 p. 7", null, {"f": "images/doe-1011-v4-es-12-fig4.png", "alt": "Graph of percent full-load torque against percent slip for an induction motor. Torque rises linearly from zero to a breakdown torque peak of about 300 percent near 25 percent slip, then falls to a starting torque of about 150 percent at 100 percent slip.", "cap": "Figure 4. Torque vs Slip. Source: DOE-1011-V4 (DOE-HDBK-1011/4-92), ES-12 p. 7.", "at": "a"}, "C458"],
  ["Motors and Generators", "What is a transformer turns ratio?", "The ratio of turns of wire in the primary winding to the number of turns of wire in the secondary winding.", "DOE-1011-V4 (DOE-HDBK-1011/4-92), Transformer Theory, ES-13 p. 2", null, null, "C459"],
  ["Sensors and Detectors", "What does a megger measure?", "Insulation resistance.", "DOE-1011-V4 (DOE-HDBK-1011/4-92), Test Equipment, ES-14 p. 30", null, null, "C460"],
  ["Sensors and Detectors", "How is a ground detector connected?", "Out of circuit to ground.", "DOE-1011-V4 (DOE-HDBK-1011/4-92), Other Electrical Measuring Devices, ES-14 p. 27", null, {"f": "images/doe-1011-v4-es-14-fig16.png", "alt": "Three-phase bus with phases A, B, and C, each connected through a transformer to a ground detector lamp, with a switch S connecting the lamp circuit to ground.", "cap": "Figure 16. Ground Detector Lamp Circuit. Source: DOE-1011-V4 (DOE-HDBK-1011/4-92), ES-14 p. 26.", "at": "a"}, "C461"],
  ["Breakers, Relays, and Disconnects", "What is the purpose of a circuit breaker?", "To provide a means for connecting and disconnecting circuits of relatively high capacities without causing damage to them.", "DOE-1011-V4 (DOE-HDBK-1011/4-92), Circuit Breakers, ES-15 p. 14", null, null, "C462"],
  ["Breakers, Relays, and Disconnects", "What are the three most commonly-used automatic trip features for a circuit breaker?", "Overcurrent, underfrequency, and undervoltage.", "DOE-1011-V4 (DOE-HDBK-1011/4-92), Circuit Breakers, ES-15 p. 14", null, null, "C463"],
  ["Breakers, Relays, and Disconnects", "What does a motor controller do?", "It controls and protects the operation of a motor.", "DOE-1011-V4 (DOE-HDBK-1011/4-92), Motor Controllers, ES-15 p. 20", null, null, "C464"],
  ["Demineralizers and Ion Exchangers", "What is corrosion?", "The deterioration of a material due to interaction with its environment.", "DOE-1015-V1 (DOE-HDBK-1015/1-93), Corrosion Theory, CH-02 p. 2", null, null, "C465"],
  ["Demineralizers and Ion Exchangers", "What is crud?", "Corrosion products in the form of finely divided, insoluble oxide particles suspended in the reactor coolant or loosely adhered to metal surfaces, or activated corrosion and wear products.", "DOE-1015-V1 (DOE-HDBK-1015/1-93), Crud and Galvanic Corrosion, CH-02 p. 25", null, null, "C466"],
  ["Demineralizers and Ion Exchangers", "What is scale?", "Deposition on piping surfaces from the formation of insoluble compounds from normally soluble salts.", "DOE-1015-V1 (DOE-HDBK-1015/1-93), Crud and Galvanic Corrosion, CH-02 p. 25", null, null, "C467"],
  ["Demineralizers and Ion Exchangers", "What is galvanic corrosion?", "Corrosion that results when two dissimilar metals with different potentials are placed in electrical contact in an electrolyte.", "DOE-1015-V1 (DOE-HDBK-1015/1-93), Crud and Galvanic Corrosion, CH-02 p. 23", null, {"f": "images/doe-1015-v1-ch-02-fig10.png", "alt": "Cross section of an iron pipe joined to a copper pipe with a solution containing copper salt flowing through. Iron ions leave the iron pipe near the junction, copper deposits there, and electrons flow through the metal.", "cap": "Figure 10. Galvanic Corrosion at Iron-Copper Pipe Junction. Source: DOE-1015-V1 (DOE-HDBK-1015/1-93), CH-02 p. 24.", "at": "a"}, "C468"],
  ["Demineralizers and Ion Exchangers", "State Le Chatelier's principle.", "If a stress is applied to an equilibrium, the system will adjust to minimize the effect of the stress.", "DOE-1015-V1 (DOE-HDBK-1015/1-93), Chemical Equations, CH-01 p. 45", null, null, "C469"],
  ["Brittle Fracture and Vessel Thermal Stress", "What is stress corrosion cracking (SCC)?", "A type of intergranular attack corrosion that occurs at the grain boundaries under tensile stress.", "DOE-1015-V1 (DOE-HDBK-1015/1-93), Specialized Corrosion, CH-02 p. 31", null, null, "C470"],
  ["Demineralizers and Ion Exchangers", "What are the three general reasons to treat water for impurities?", "To minimize corrosion, to minimize radiation levels in the reactor facility, and to minimize fouling of heat transfer surfaces.", "DOE-1015-V2 (DOE-HDBK-1015/2-93), Purpose of Water Treatment, CH-04 p. 2", null, null, "C471"],
  ["Demineralizers and Ion Exchangers", "What does ion exchange do?", "It controls the purity and pH of water by removing undesirable ions and replacing them with acceptable ones.", "DOE-1015-V2 (DOE-HDBK-1015/2-93), Water Treatment Processes, CH-04 p. 3", null, {"f": "images/doe-1015-v2-ch-04-fig3.png", "alt": "Ion exchange vessel with influent water entering at the top, a bed of ion exchange resin beads with an anion bed above a cation bed, retention screens, agitators, and effluent purified water leaving near the bottom. Alkali and acid regenerant lines and a regenerant drain are shown.", "cap": "Figure 3. Schematic Diagram of a Typical Ion Exchanger. Source: DOE-1015-V2 (DOE-HDBK-1015/2-93), CH-04 p. 8.", "at": "a"}, "C472"],
  ["Demineralizers and Ion Exchangers", "What does demineralize mean?", "Removing impurities from incoming water by exchanging impure ions with H+ and OH- ions, resulting in pure water.", "DOE-1015-V2 (DOE-HDBK-1015/2-93), Water Treatment Processes, CH-04 p. 13", null, null, "C473"],
  ["Demineralizers and Ion Exchangers", "What is a mixed-bed demineralizer?", "A vessel containing resin that is a uniform mixture of cation and anion resins.", "DOE-1015-V2 (DOE-HDBK-1015/2-93), Water Treatment Processes, CH-04 p. 13", null, null, "C474"],
  ["Demineralizers and Ion Exchangers", "How may resin performance be monitored?", "With a history curve that plots DF with respect to time.", "DOE-1015-V2 (DOE-HDBK-1015/2-93), Water Treatment Processes, CH-04 p. 11", null, {"f": "images/doe-1015-v2-ch-04-fig4.png", "alt": "Graph of decontamination factor DF against time. DF stays high, then falls through a point marked X, exhaustion, and levels off at a low value.", "cap": "Figure 4. Typical History Curve. Source: DOE-1015-V2 (DOE-HDBK-1015/2-93), CH-04 p. 11.", "at": "a"}, "C475"],
  ["Demineralizers and Ion Exchangers", "How is the radiation-driven decomposition of reactor water suppressed?", "By adding excess hydrogen.", "DOE-1015-V2 (DOE-HDBK-1015/2-93), Effects of Radiation on Water Chemistry, CH-03 p. 11", null, null, "C476"],
  ["Valves", "In what position do P&IDs show valves unless otherwise stated?", "In their \"normal\" position.", "DOE-1016-V1 (DOE-HDBK-1016/1-93), Reading Engineering P&IDs, PR-02 p. 16", null, {"f": "images/doe-1016-v1-pr-02-fig17.png", "alt": "Chart of P&ID valve status symbols: closed, open, and throttled valves, locked open marked LO, locked closed marked LC, fails open marked FO, fails closed marked FC, fails as is marked FAI, and a three-way valve with one port open and one closed.", "cap": "Figure 17. Valve Status Symbols. Source: DOE-1016-V1 (DOE-HDBK-1016/1-93), PR-02 p. 16.", "at": "a"}, "C477"],
  ["Valves", "What kinds of items have common P&ID symbols?", "Valves, valve operators, process piping, instrumentation, and common system components.", "DOE-1016-V1 (DOE-HDBK-1016/1-93), Engineering Fluids Diagrams and Prints, PR-02 p. 15", null, {"f": "images/doe-1016-v1-pr-02-fig1.png", "alt": "Chart of P&ID valve symbols with alternatives for globe, gate, ball, needle, butterfly, plug, diaphragm, three-way, four-way, check, stop check, angle, and relief valves, plus pipe reducer, rupture disc, and pressure regulator.", "cap": "Figure 1. Valve Symbols. Source: DOE-1016-V1 (DOE-HDBK-1016/1-93), PR-02 p. 3.", "at": "a"}, "C478"],
  ["Breakers, Relays, and Disconnects", "How is polarity shown on a transformer in an electrical diagram?", "By dots placed on the primary and secondary windings.", "DOE-1016-V1 (DOE-HDBK-1016/1-93), Electrical Diagrams and Schematics, PR-03 p. 17", null, null, "C479"],
  ["Breakers, Relays, and Disconnects", "In what state are relays normally drawn on electrical diagrams?", "In the de-energized state.", "DOE-1016-V1 (DOE-HDBK-1016/1-93), Electrical Diagrams and Schematics, PR-03 p. 17", null, null, "C480"],
  ["Controllers and Positioners", "What does a block diagram present?", "The flow or functional information about a circuit, but not a detailed depiction of it.", "DOE-1016-V2 (DOE-HDBK-1016/2-93), Electronic Diagrams, Prints, and Schematics, PR-04 p. 17", null, null, "C481"],
  ["Controllers and Positioners", "What does an electronic schematic diagram present?", "Detailed information about the circuit, each of its components, and how they are wired into the circuit.", "DOE-1016-V2 (DOE-HDBK-1016/2-93), Electronic Diagrams, Prints, and Schematics, PR-04 p. 17", null, null, "C482"],
  ["Controllers and Positioners", "What are the three types of logic time delay devices?", "Type One delays the output for a specified time. Type Two only generates an output for the specified time. Type Three outputs for the specified time when triggered, regardless of input duration.", "DOE-1016-V2 (DOE-HDBK-1016/2-93), Engineering Logic Diagrams, PR-05 p. 10", null, null, "C483"],
  ["Controllers and Positioners", "How many basic symbols are used on logic diagrams?", "Seven.", "DOE-1016-V2 (DOE-HDBK-1016/2-93), Engineering Logic Diagrams, PR-05 p. 10", null, {"f": "images/doe-1016-v2-pr-05-fig3.png", "alt": "Table of AND, NAND, OR, NOR, and NOT logic symbols as drawn in the IEEE/ANSI, R113J, NEMA, MIL, IEC, Allen Bradley, and G.E. conventions.", "cap": "Figure 3. Basic Logic Symbols. Source: DOE-1016-V2 (DOE-HDBK-1016/2-93), PR-05 p. 5.", "at": "a"}, "C484"],
  ["Steam", "What is saturation?", "The combination of temperature and pressure at which a mixture of vapor and liquid can exist at equilibrium.", "DOE-1012-V1 (DOE-HDBK-1012/1-92), Change of Phase, HT-01 p. 39", null, null, "C485"],
  ["Steam", "What is a subcooled liquid?", "A liquid at a temperature below saturation temperature for its pressure.", "DOE-1012-V1 (DOE-HDBK-1012/1-92), Change of Phase, HT-01 p. 39", null, null, "C486"],
  ["Steam", "What is a superheated vapor?", "A vapor at a temperature above saturation temperature for its pressure.", "DOE-1012-V1 (DOE-HDBK-1012/1-92), Change of Phase, HT-01 p. 39", null, null, "C487"],
  ["Steam", "What is the critical point?", "The temperature and pressure above which there is no distinction between the liquid and vapor phases.", "DOE-1012-V1 (DOE-HDBK-1012/1-92), Change of Phase, HT-01 p. 39", null, {"f": "images/doe-1012-v1-ht-01-fig13.png", "alt": "Temperature-entropy diagram for water. A dome peaks at the critical point, with the liquid region on the left, the vapor region on the right, the liquid-vapor region under the dome, and the solid-vapor region at the bottom. Constant pressure lines P1 to P4 are shown.", "cap": "Figure 13. T-s Diagram for Water. Source: DOE-1012-V1 (DOE-HDBK-1012/1-92), HT-01 p. 46.", "at": "a"}, "C488"],
  ["Steam", "What is the triple point?", "The temperature and pressure at which all three phases can exist in equilibrium.", "DOE-1012-V1 (DOE-HDBK-1012/1-92), Change of Phase, HT-01 p. 39", null, null, "C489"],
  ["Steam", "What is quality?", "The fraction of the total mass of a mixture that is in the vapor phase.", "DOE-1012-V1 (DOE-HDBK-1012/1-92), Change of Phase, HT-01 p. 39", null, null, "C490"],
  ["Steam", "What is moisture content?", "The fraction of the total mass of a mixture that is in the liquid phase.", "DOE-1012-V1 (DOE-HDBK-1012/1-92), Change of Phase, HT-01 p. 39", null, null, "C491"],
  ["Steam", "What does a Mollier diagram plot?", "Enthalpy (h) versus entropy (s).", "DOE-1012-V1 (DOE-HDBK-1012/1-92), Property Diagrams and Steam Tables, HT-01 p. 52", null, null, "C492"],
  ["Thermodynamic Cycles", "What four processes make up the Rankine cycle?", "ab: liquid compressed with no change in entropy (ideal pump). bc: constant pressure heat transfer in the boiler. cd: constant entropy expansion with shaft work output (ideal turbine). da: constant pressure heat rejection to the condenser.", "DOE-1012-V1 (DOE-HDBK-1012/1-92), First Law of Thermodynamics, HT-01 p. 61", null, {"f": "images/doe-1012-v1-ht-01-fig19.png", "alt": "Two temperature-entropy diagrams of a Rankine cycle with points a, b, c, and d around the saturation dome and the rejected heat shaded below the cycle. The upper cycle reaches superheat at point c; the lower one does not.", "cap": "Figure 19. T-s Diagram with Rankine Cycles. Source: DOE-1012-V1 (DOE-HDBK-1012/1-92), HT-01 p. 61.", "at": "a"}, "C493"],
  ["Thermodynamic Cycles", "What is a cyclic process?", "The fluid passes through various processes and then eventually returns to the same state it began with.", "DOE-1012-V1 (DOE-HDBK-1012/1-92), First Law of Thermodynamics, HT-01 p. 61", null, null, "C494"],
  ["Thermodynamic Cycles", "What is the heat-rejection mechanism of a steam plant cycle?", "The condensation process.", "DOE-1012-V1 (DOE-HDBK-1012/1-92), First Law of Thermodynamics, HT-01 p. 62", null, null, "C495"],
  ["Thermodynamic Cycles", "What decreases cycle efficiency?", "The presence of friction, heat losses, and cycle inefficiencies.", "DOE-1012-V1 (DOE-HDBK-1012/1-92), Second Law of Thermodynamics, HT-01 p. 96", null, null, "C496"],
  ["Fission Product Poisons", "When does helium-3 become a significant neutron poison?", "When significant amounts of tritium are left in a reactor during a shutdown lasting longer than several months.", "DOE-1019-V2 (DOE-HDBK-1019/2-93), Samarium and Other Fission Product Poisons, NP-03 p. 47", null, null, "C504"],
  ["Fuel Depletion and Burnable Poisons", "What is a burnable neutron poison?", "A material with a high neutron absorption cross section that is converted into a material of relatively low absorption cross section as the result of neutron absorption.", "DOE-1019-V2 (DOE-HDBK-1019/2-93), Neutron Poisons, NP-03 p. 33", null, null, "C505"],
  ["PSAR: Nuclear Heat Supply Systems", "What is the primary purpose of the Reactor Core System (RCC)?", "Sustain a nuclear chain reaction for fission heat generation.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.1.1, p. 1.1-3", null, null, "C507"],
  ["PSAR: Nuclear Heat Supply Systems", "What is the primary purpose of the Reactor Enclosure System (RES)?", "Support the reactor core and contain the primary sodium coolant.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.1.2, p. 1.1-3", null, null, "C508"],
  ["PSAR: Nuclear Heat Supply Systems", "What is the primary purpose of the Guard Vessel (GV)?", "Provide a defense-in-depth coolant and functional containment boundary if the reactor vessel leaks.", "PSAR Rev 1, ML25276A288, Sec. 7.1.2.1.3, p. 7.1-17", null, null, "C509"],
  ["PSAR: Reactor Auxiliary Systems", "What is the primary purpose of the Reactor Air Cooling System (RAC)?", "Provide passive decay heat removal to the environment by natural convection of air.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.1.3, p. 1.1-4", null, null, "C510"],
  ["PSAR: Nuclear Heat Supply Systems", "What is the primary purpose of the Primary Heat Transport System (PHT)?", "Transport heat from the reactor core to the Intermediate Heat Transport System.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.1.4, p. 1.1-4", null, null, "C511"],
  ["PSAR: Nuclear Heat Supply Systems", "What is the primary purpose of the Primary Sodium Pumps (PSPs)?", "Provide the head to drive primary sodium flow.", "PSAR Rev 1, ML25276A288, Sec. 7.1.3.2.1, p. 7.1-60", null, null, "C512"],
  ["PSAR: Nuclear Heat Supply Systems", "What is the primary purpose of the Intermediate Heat Exchangers (IHXs)?", "Transfer heat from the primary sodium to the intermediate sodium.", "PSAR Rev 1, ML25276A288, Sec. 7.1.3.3.1, p. 7.1-62", null, null, "C513"],
  ["PSAR: Nuclear Heat Supply Systems", "What is the primary purpose of the Intermediate Heat Transport System (IHT)?", "Transport heat away from the PHT to the salt system or to the air coolers.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.1.5, p. 1.1-4", null, null, "C514"],
  ["PSAR: Reactor Auxiliary Systems", "What is the primary purpose of the Intermediate Air Cooling System (IAC)?", "Transfer heat from the intermediate sodium loops to the atmosphere.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.1.6, p. 1.1-5", null, null, "C515"],
  ["PSAR: Nuclear Heat Supply Systems", "What is the primary purpose of the Nuclear Island Salt System (NSS)?", "Remove heat from the IHT sodium-salt heat exchangers into the molten salt loop.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.2.1, p. 1.1-10", null, null, "C516"],
  ["PSAR: Reactor Auxiliary Systems", "What is the primary purpose of the Sodium Cover Gas System (SCG)?", "Control, monitor and supply inert argon gas to systems and components in the RXB, RAB and FHB.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.1.7, p. 1.1-5", null, null, "C517"],
  ["PSAR: Reactor Auxiliary Systems", "What is the primary purpose of the Sodium Processing System (SPS)?", "Monitor and remove contaminants such as cesium, oxygen and hydrogen from the liquid sodium.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.1.8, p. 1.1-6", null, null, "C518"],
  ["PSAR: Reactor Auxiliary Systems", "What is the primary purpose of the Control Rod Drive System (CRD)?", "Provide core reactivity control for power control, power shaping and reactor shutdown.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.1.9, p. 1.1-6", null, null, "C519"],
  ["PSAR: Integrated Controls Systems", "What is the primary purpose of the Reactor Protection System (RPS)?", "Automatically generate output signals to initiate reactor scram and engineered safety feature functions.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.1.11, p. 1.1-7", null, null, "C520"],
  ["PSAR: Integrated Controls Systems", "What is the primary purpose of the Nuclear Instrumentation System (XIS)?", "Sense neutron flux leakage from the core.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.1.12, p. 1.1-7", null, null, "C521"],
  ["PSAR: Integrated Controls Systems", "What is the primary purpose of the Radiation Monitoring System (RMS)?", "Provide radiation activity indications for systems, buildings and release pathways to protect personnel and the environment.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.1.13, p. 1.1-7", null, null, "C522"],
  ["PSAR: Integrated Controls Systems", "What is the primary purpose of the Reactor Instrumentation System (RIS)?", "Measure parameters such as hot pool level and temperature and send them to the RPS and NIC.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.1.14, p. 1.1-8", null, null, "C523"],
  ["PSAR: Integrated Controls Systems", "What is the primary purpose of the Nuclear Island Control System (NIC)?", "Group the non-safety I&C subsystems (RMC, CTC, UMC, AMC, FHC, PMC) that control the Nuclear Island.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.1.15, p. 1.1-8", null, null, "C524"],
  ["PSAR: Integrated Controls Systems", "What is the primary purpose of the Nuclear Island Distributed Control System (DCS)?", "Gather information from field sensors, interfaces and other I&C systems as the primary NIC subsystem.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.3.5, p. 1.1-13", null, null, "C525"],
  ["PSAR: Integrated Controls Systems", "What is the primary purpose of the Rod Monitoring and Control System (RMC)?", "Control and monitor the primary and secondary control rod assemblies.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.1.16, p. 1.1-8", null, null, "C526"],
  ["PSAR: Integrated Controls Systems", "What is the primary purpose of the Coolant Temperature Monitoring and Control System (CTC)?", "Monitor and control the flow control functions of the PHT, IHT, NSS, IAC and ESS.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.1.17, p. 1.1-9", null, null, "C527"],
  ["PSAR: Integrated Controls Systems", "What is the primary purpose of the Utility Monitoring and Control System (UMC)?", "Monitor and control the auxiliary electrical and ancillary systems.", "PSAR Rev 1, ML25276A288, Sec. 7.6.2.1, p. 7.6-7", null, null, "C528"],
  ["PSAR: Integrated Controls Systems", "What is the primary purpose of the Auxiliary Monitoring and Control System (AMC)?", "Monitor and control Nuclear Island auxiliary systems such as radwaste, cover gas and sodium processing.", "PSAR Rev 1, ML25276A288, Sec. 7.6.2.1, p. 7.6-6", null, null, "C529"],
  ["PSAR: Integrated Controls Systems", "What is the primary purpose of the Fuel Handling Supervisory Control System (FHC)?", "Serve as the supervisory control and data acquisition (SCADA) system for fuel handling.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.1.20, p. 1.1-10", null, null, "C530"],
  ["PSAR: Integrated Controls Systems", "What is the primary purpose of the Plant Monitoring and Control System (PMC)?", "Let operators monitor plant data and manually control equipment through the HMI, with no automatic control.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.1.21, p. 1.1-10", null, null, "C531"],
  ["PSAR: Fuel Handling Systems", "What is the primary purpose of the In-Vessel Fuel Handling System (FHI)?", "Manipulate core assembly positions during refueling and maintain the primary functional containment boundary when installed.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.3.1, p. 1.1-12", null, null, "C532"],
  ["PSAR: Fuel Handling Systems", "What is the primary purpose of the Ex-Vessel Fuel Handling System (FHE)?", "Facilitate the receipt, conditioning, storage, installation and removal of all core assemblies.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.3.2, p. 1.1-12", null, null, "C533"],
  ["PSAR: Fuel Handling Systems", "What is the primary purpose of the Ex-Vessel Handling Machine (EVHM)?", "Transfer core assemblies in sodium-filled pots between the reactor vessel and the Ex-Vessel Storage Tank.", "PSAR Rev 1, ML25276A288, Sec. 7.3.2.1.1, p. 7.3-17", null, null, "C534"],
  ["PSAR: Fuel Handling Systems", "What is the primary purpose of the Bottom Loading Transfer Cask (BLTC)?", "Transfer core assemblies between the new assembly preconditioning station, the Pool Immersion Cell and the EVST.", "PSAR Rev 1, ML25276A288, Sec. 7.3.2.1.2, p. 7.3-19", null, null, "C535"],
  ["PSAR: Fuel Handling Systems", "What is the primary purpose of the Ex-Vessel Storage Tank (EVST)?", "Provide a controlled sodium environment for temporary storage of new and irradiated core assemblies.", "PSAR Rev 1, ML25276A288, Sec. 7.3.2.1.3, p. 7.3-20", null, null, "C536"],
  ["PSAR: Fuel Handling Systems", "What is the primary purpose of the Water Pool Fuel Handling System (FHP)?", "Store irradiated core assemblies in a water-cooled pool.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.3.3, p. 1.1-12", null, null, "C537"],
  ["PSAR: Integrated Controls Systems", "What is the primary purpose of the Main Control Room (MCR)?", "Let operators initiate or take manual control of each function needed to control the plant and maintain safety.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.3.4, p. 1.1-13", null, null, "C538"],
  ["PSAR: Buildings and Structures", "What is the primary purpose of the Remote Shutdown Complex (RSC)?", "Provide a location to monitor safe shutdown conditions if the MCR is no longer habitable.", "PSAR Rev 1, ML25276A288, Sec. 7.8.4.1.1, p. 7.8-29", null, null, "C539"],
  ["PSAR: Electrical Systems", "What is the primary purpose of the Nuclear Island Auxiliary Electrical Systems?", "Distribute auxiliary electrical power to the Nuclear Island.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.3.6, p. 1.1-13", null, null, "C540"],
  ["PSAR: Electrical Systems", "What is the primary purpose of the NI AC Electrical Power Medium Voltage System (NMV)?", "Supply medium voltage loads, 6.9kV-480V transformers, and the PSP and ISP adjustable speed drives.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.3.6, p. 1.1-13", null, null, "C541"],
  ["PSAR: Electrical Systems", "What is the primary purpose of the NI AC Electrical Power Low Voltage System (NLV)?", "Supply 480V switchgear, motor control centers, switchboards and panelboards for NI auxiliary loads.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.3.6, p. 1.1-13", null, null, "C542"],
  ["PSAR: Electrical Systems", "What is the primary purpose of the NI Heat Tracing System (NHT)?", "Power heating cables on process lines and tanks to prevent freezing and crystallization of fluids such as sodium and molten salt.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.3.6, p. 1.1-13", null, null, "C543"],
  ["PSAR: Electrical Systems", "What is the primary purpose of the NI Uninterruptible AC Power Supply System (NUP)?", "Provide uninterruptible AC power to NI loads such as the RPS, XIS, RMS and CRD motor controllers.", "PSAR Rev 1, ML25276A288, Sec. 7.7.1.1, p. 7.7-1", null, null, "C544"],
  ["PSAR: Electrical Systems", "What is the primary purpose of the NI DC Power Supply System (NDC)?", "Provide continuous, stable DC power through four independent 250 VDC divisions, one per RPS division.", "PSAR Rev 1, ML25276A288, Sec. 7.7.1.3.2, p. 7.7-5", null, null, "C545"],
  ["PSAR: Radwaste Systems", "What is the primary purpose of the Gaseous Radwaste Processing System (RWG)?", "Process cover gas waste streams and hold them up so radioactive isotopes such as argon-41 decay.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.3.7, p. 1.1-14", null, null, "C546"],
  ["PSAR: Radwaste Systems", "What is the primary purpose of the Liquid Radwaste Processing System (RWL)?", "Collect, segregate, process, sample and monitor non-sodium, non-salt liquid radioactive waste.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.3.8, p. 1.1-14", null, null, "C547"],
  ["PSAR: Radwaste Systems", "What is the primary purpose of the Solid Radwaste Processing System (RWS)?", "Process wet and dry solid waste from plant systems.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.3.9, p. 1.1-14", null, null, "C548"],
  ["PSAR: Ancillary Systems", "What is the primary purpose of the Nuclear Island HVAC System (NHV)?", "Provide HVAC for personnel comfort, freeze protection and equipment operability.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.3.10, p. 1.1-14", null, null, "C549"],
  ["PSAR: Significant Support Systems and Components", "What is the primary purpose of the NI normal lighting system?", "Provide general indoor and outdoor lighting during operation, maintenance and testing.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.3.11, p. 1.1-15", null, null, "C550"],
  ["PSAR: Significant Support Systems and Components", "What is the primary purpose of the Nuclear Island Emergency Operating Lighting?", "Provide illumination in NI plant areas during a station blackout.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.3.17, p. 1.1-17", null, null, "C551"],
  ["PSAR: Significant Support Systems and Components", "What is the primary purpose of the NI Grounding and Earthing and Lightning Protection (NGL)?", "Protect personnel and equipment from transient over-voltages and provide a ground reference for instrument signals.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.3.11, p. 1.1-15", null, null, "C552"],
  ["PSAR: Significant Support Systems and Components", "What is the primary purpose of the Nuclear Island Plant Communication System?", "Provide an independent means of onsite and offsite communication in all modes, including emergencies.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.3.12, p. 1.1-15", null, null, "C553"],
  ["PSAR: Significant Support Systems and Components", "What is the primary purpose of the Nuclear Island Cranes and Hoists (NCH)?", "Lift and move approved loads within NI buildings.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.3.13, p. 1.1-16", null, null, "C554"],
  ["PSAR: Significant Support Systems and Components", "What is the primary purpose of the NI Air and Gas Distribution System (NGS)?", "Distribute and store argon as the cover gas for sodium-containing systems.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.3.15, p. 1.1-16", null, null, "C555"],
  ["PSAR: Significant Support Systems and Components", "What is the primary purpose of the Seismic Monitoring System (SMS)?", "Monitor ground motion and structural response so personnel can promptly assess an earthquake's effects.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.3.16, p. 1.1-16", null, null, "C556"],
  ["PSAR: Integrated Controls Systems", "What is the primary purpose of the Anticipatory Automatic Seismic Trip System (AST)?", "Scram the reactor before the peak seismic wave arrives in beyond-design-basis earthquakes.", "PSAR Rev 1, ML25276A288, Sec. 7.6.8.1, p. 7.6-75", null, null, "C557"],
  ["PSAR: Ancillary Systems", "What is the primary purpose of the Nuclear Island Fire Protection System (NFP)?", "Mitigate the effects of fire within and around the NI facilities.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.3.18, p. 1.1-18", null, null, "C558"],
  ["PSAR: Ancillary Systems", "What is the primary purpose of the NI Fire Water Distribution System (NFD)?", "Distribute fire water for hydrants and water-based fire suppression.", "PSAR Rev 1, ML25276A288, Sec. 7.5.2.1, p. 7.5-10", null, null, "C559"],
  ["PSAR: Ancillary Systems", "What is the primary purpose of the NI Fire Suppression System (NFS)?", "Suppress and control fire with water, clean agents and chemical means.", "PSAR Rev 1, ML25276A288, Sec. 7.5.2.1, p. 7.5-10", null, null, "C560"],
  ["PSAR: Ancillary Systems", "What is the primary purpose of the NI Fire Detection and Alarm System (NFA)?", "Detect smoke and fire, monitor and control suppression systems, and notify personnel.", "PSAR Rev 1, ML25276A288, Sec. 7.5.2.1, p. 7.5-10", null, null, "C561"],
  ["PSAR: Ancillary Systems", "What is the primary purpose of the Sodium Leak Detection, Collection, and Containment System (NNA)?", "Detect, collect and contain sodium leaks to mitigate sodium fires.", "PSAR Rev 1, ML25276A288, Sec. 7.5.2.1, p. 7.5-10", null, null, "C562"],
  ["PSAR: Buildings and Structures", "What is the primary purpose of the Reactor Building (RXB)?", "House the reactor and the associated SSCs that support reactor operation.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.4.2, p. 1.1-19", null, null, "C563"],
  ["PSAR: Buildings and Structures", "What is the primary purpose of the Fuel Handling Building (FHB)?", "House fuel receipt, refueling, storage and the spent fuel pool, plus radwaste equipment.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.4.3, p. 1.1-20", null, null, "C564"],
  ["PSAR: Buildings and Structures", "What is the primary purpose of the Reactor Auxiliary Building (RAB)?", "House functions and processes that support the IHT, SHXs, ISPs and SPS.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.4.4, p. 1.1-20", null, null, "C565"],
  ["PSAR: Buildings and Structures", "What is the primary purpose of the Nuclear Island Control Building (NCB)?", "Serve as the primary control center for the NI, housing the MCR.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.4.5, p. 1.1-20", null, null, "C566"],
  ["PSAR: Buildings and Structures", "What is the primary purpose of the Fuel Auxiliary Building (FAB)?", "Provide the centralized personnel entry and exit point for the major NI facilities.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.4.6, p. 1.1-21", null, null, "C567"],
  ["PSAR: Buildings and Structures", "What is the primary purpose of the Nuclear Island E-Modules?", "Contain NI electrical systems and components in prefabricated modules.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.4.8, p. 1.1-21", null, null, "C568"],
  ["PSAR: Nuclear Heat Supply Systems", "According to the PSAR, which functions does the Reactor Enclosure System (RES) provide during normal and off-normal conditions?", "Radionuclide retention, reactivity control, and reactor heat removal.", "PSAR Rev 1, ML25276A288, Sec. 7.1.2.1, p. 7.1-15", null, null, "C569"],
  ["PSAR: Reactor Auxiliary Systems", "Together with the PHT and the RES, the Reactor Air Cooling System (RAC) provides which function?", "The long-term emergency core cooling function.", "PSAR Rev 1, ML25276A288, Sec. 7.2.1.1, p. 7.2-1", null, null, "C570"],
  ["PSAR: Nuclear Heat Supply Systems", "During a design basis event, how does the Primary Heat Transport System (PHT) support decay heat removal?", "It facilitates natural circulation of primary sodium to carry heat to the reactor vessel walls, then to the guard vessel and the RAC.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.1.4, p. 1.1-4", null, null, "C571"],
  ["PSAR: Nuclear Heat Supply Systems", "If pumped flow is lost, how does the Intermediate Heat Transport System (IHT) support decay heat removal?", "Natural circulation of intermediate sodium through the IAC sodium-air heat exchangers.", "PSAR Rev 1, ML25276A288, Sec. 7.1.4.1, p. 7.1-75", null, null, "C572"],
  ["PSAR: Reactor Auxiliary Systems", "According to the PSAR, what is the primary and preferred means of reactor heat removal during low power and shutdown conditions?", "The Intermediate Air Cooling System (IAC).", "PSAR Rev 1, ML25276A288, Sec. 7.2.2.1, p. 7.2-13", null, null, "C573"],
  ["PSAR: Reactor Auxiliary Systems", "Which system controls the Control Rod Drive System (CRD) scram function?", "The Reactor Protection System (RPS).", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.1.9, p. 1.1-6", null, null, "C574"],
  ["PSAR: Nuclear Heat Supply Systems", "Why must the Reactor Core System (RCC) maintain its geometry during postulated accidents?", "To support the natural circulation flowpath through the core and allow control rod insertion for shutdown.", "PSAR Rev 1, ML25276A288, Sec. 7.1.1.2, p. 7.1-6", null, null, "C575"],
  ["PSAR: Integrated Controls Systems", "How does the Anticipatory Automatic Seismic Trip System (AST) scram the reactor?", "It sends actuation signals to the Reactor Trip Breakers through an interface device provided by the RPS.", "PSAR Rev 1, ML25276A288, Sec. 7.6.8.1, p. 7.6-75", null, null, "C576"],
  ["PSAR: Integrated Controls Systems", "Where does the Nuclear Instrumentation System (XIS) send its conditioned neutron flux signals?", "To the RPS and the NIC, for protective, control and monitoring functions.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.1.12, p. 1.1-7", null, null, "C577"],
  ["PSAR: Integrated Controls Systems", "Which leak detection parameters does the Reactor Instrumentation System (RIS) provide to the RPS?", "Reactor vessel to guard vessel annulus liquid sodium leak detection.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.1.14, p. 1.1-8", null, null, "C578"],
  ["PSAR: Integrated Controls Systems", "Which Radiation Monitoring System subsystem gives operators early indication of abnormal radiological conditions in a process, such as failed fuel?", "Process radiation monitoring.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.1.13, p. 1.1-8", null, null, "C579"],
  ["PSAR: Integrated Controls Systems", "What is the primary function of the RMS effluent radiation monitoring subsystem?", "Protect public health and safety and assure off-site exposure stays within 10 CFR 20 limits.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.1.13, p. 1.1-8", null, null, "C580"],
  ["PSAR: Nuclear Heat Supply Systems", "Why is the annulus between the reactor vessel and guard vessel inerted with argon?", "To minimize the potential for sodium-air reaction.", "PSAR Rev 1, ML25276A288, Sec. 7.1.2.1.3, p. 7.1-18", null, null, "C581"],
  ["PSAR: Fuel Handling Systems", "What does transferring core assemblies in a shielded and inert environment provide in the Ex-Vessel Fuel Handling System?", "Radiation shielding, radionuclide retention, and a medium for removal of decay heat.", "PSAR Rev 1, ML25276A288, Sec. 7.3.2.1, p. 7.3-17", null, null, "C582"],
  ["PSAR: Fuel Handling Systems", "Which functions does the Water Pool Fuel Handling System (FHP) provide for stored fuel?", "Core assembly cooling, spent fuel reactivity control, fission product containment, and radiation shielding.", "PSAR Rev 1, ML25276A288, Sec. 7.3.1.1, p. 7.3-1", null, null, "C583"],
  ["PSAR: Radwaste Systems", "Which fundamental safety function does the Gaseous Radwaste Processing System (RWG) support?", "Retaining radionuclides.", "PSAR Rev 1, ML25276A288, Sec. 7.4.1.1, p. 7.4-1", null, null, "C584"],
  ["PSAR: Buildings and Structures", "How does the Reactor Building substructure support decay heat removal during design basis accidents?", "It supports and protects the RES and RAC so the geometry for passive residual heat removal is maintained.", "PSAR Rev 1, ML25276A288, Sec. 7.8.1.1.2, p. 7.8-3", null, null, "C585"],
  ["PSAR: Buildings and Structures", "What radionuclide retention role does the Reactor Auxiliary Building substructure have?", "It provides an enveloping boundary for radionuclide retention in the SPS cells.", "PSAR Rev 1, ML25276A288, Sec. 7.8.3.1.2, p. 7.8-21", null, null, "C586"],
  ["PSAR: Ancillary Systems", "In which building does the Nuclear Island HVAC System (NHV) provide a radionuclide retention function as part of the PRA defense line level four functions?", "The Reactor Building (RXB).", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.3.10, p. 1.1-15", null, null, "C587"],
  ["PSAR: Electrical Systems", "Which CRD function does the NI Uninterruptible AC Power Supply System (NUP) power through the control rod drive motor controllers?", "The scram follow motor drive-in function.", "PSAR Rev 1, ML25276A288, Sec. 7.7.1.1, p. 7.7-1", null, null, "C588"],
  ["PSAR: Significant Support Systems and Components", "What is the primary purpose of the Nuclear Island Major Maintenance Equipment (NME)?", "Install and remove the IVTM and FTL to support refueling operations.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.3.19, p. 1.1-18", null, null, "C589"],
  ["PSAR: Significant Support Systems and Components", "Why does the NME provide an inert environment?", "To prevent excess air ingress into the primary cover gas space and excess leakage into the Reactor Building during reactor operating mode 4.", "PSAR Rev 1, ML25276A288, Sec. 1.1.4.3.19, p. 1.1-18", null, null, "C590"],
  ["PSAR: Buildings and Structures", "What is the Reactor Building (RXB) superstructure?", "An above-grade steel framed structure supported on a concrete foundation independent from the RXB substructure.", "PSAR Rev 1, ML25276A288, Sec. 7.8.1.2, p. 7.8-7", null, null, "C591"],
  ["PSAR: Ancillary Systems", "What do guard pipes do in the event of a sodium leak?", "They act as a full secondary pressure boundary, designed to the same conditions as the protected system pipe.", "PSAR Rev 1, ML25276A288, Sec. 8.2.1.3, p. 8.2-2", null, null, "C592"],
  ["PSAR: Ancillary Systems", "What is a sodium catch pan?", "A steel-lined volume designed to retain the design-basis sodium leak volume plus margin.", "PSAR Rev 1, ML25276A288, Sec. 8.2.1.6, p. 8.2-2", null, null, "C593"],
  ["PSAR: Ancillary Systems", "What is a clamshell in the sodium leak design?", "A form of guard enclosure placed specifically where piping inspections are expected to be needed.", "PSAR Rev 1, ML25276A288, Sec. 7.5.2.3.4, p. 7.5-15", null, null, "C594"],
  ["PSAR: Ancillary Systems", "What is a cell in the sodium fire protection design?", "A room with a limited leak rate and known oxygen volume that is either actively inerted or becomes de facto inerted once a sodium leak consumes the limited available oxygen.", "PSAR Rev 1, ML25276A288, Sec. 7.5.2.3.4, p. 7.5-15", null, null, "C595"],
  ["PSAR: Ancillary Systems", "What provides supplemental sodium leak detection in non-inerted fire areas?", "Conventional fire detection.", "PSAR Rev 1, ML25276A288, Sec. 8.2.1.8, p. 8.2-3", null, null, "C596"],
  ["PSAR: Reactor Auxiliary Systems", "What does the plugging temperature indicator (PTI) provide in the Sodium Processing System?", "Continuous monitoring of the plugging temperature of the sodium, giving real-time indication of the overall sodium chemistry.", "PSAR Rev 1, ML25276A288, Sec. 7.2.4.3.1, p. 7.2-51", null, null, "C597"],
  ["PSAR: Fuel Handling Systems", "Where are new core assemblies placed after removal from the shipping container?", "In the assembly receipt inspection stand (ARIS).", "PSAR Rev 1, ML25276A288, Sec. 3.14.2.5, p. 3.14-6", null, null, "C598"],
  ["Thermodynamic Units and Properties", "What are the three unit conversion steps?", "Select the equivalent relationship from the conversion table, express the relationship as a conversion factor, then multiply the given quantity by the conversion factor.", "DOE-1010 (DOE-HDBK-1010-92), Unit Conversion, CP-01 p. 16", null, null, "C599"],
  ["Basic Energy Concepts", "What is the difference between a scalar quantity and a vector quantity?", "A scalar quantity has magnitude only. A vector quantity has both magnitude and direction.", "DOE-1010 (DOE-HDBK-1010-92), Scalar and Vector Quantities, CP-02 p. 1", null, null, "C600"],
  ["Basic Energy Concepts", "What is weight?", "The force exerted on an object due to gravity.", "DOE-1010 (DOE-HDBK-1010-92), Force and Weight, CP-04 p. 4", null, null, "C601"],
  ["Motors and Generators", "What does an inductor oppose, and how?", "A change in current flow, by the CEMF induced when the field collapses or expands.", "DOE-1011-V2 (DOE-HDBK-1011/2-92), Inductance, ES-03 p. 8", null, null, "C602"],
  ["Motors and Generators", "How is a capacitor constructed?", "Two conductors (plates) separated by a dielectric.", "DOE-1011-V2 (DOE-HDBK-1011/2-92), Capacitance, ES-03 p. 18", null, null, "C603"],
  ["Motors and Generators", "How are capacitors combined in series and in parallel?", "Capacitors in series are combined like resistors in parallel. Capacitors in parallel are combined like resistors in series.", "DOE-1011-V2 (DOE-HDBK-1011/2-92), Capacitance, ES-03 p. 13", null, null, "C604"],
  ["Motors and Generators", "How do effective (RMS) AC current and voltage relate to their maximum values?", "Effective current is 0.707 Imax. Effective voltage is 0.707 Emax.", "DOE-1011-V3 (DOE-HDBK-1011/3-92), Voltage, Current, and Frequency, ES-07 p. 10", null, null, "C605"],
  ["Motors and Generators", "What is phase angle used for?", "To compare two wave forms.", "DOE-1011-V3 (DOE-HDBK-1011/3-92), Voltage, Current, and Frequency, ES-07 p. 10", null, null, "C606"],
  ["Demineralizers and Ion Exchangers", "What are the components of an atom, and how is an atom classified chemically?", "Protons, neutrons, and electrons. An atom is classified chemically by the number of protons in its nucleus.", "DOE-1015-V1 (DOE-HDBK-1015/1-93), Characteristics of Atoms, CH-01 p. 11", null, null, "C607"],
  ["Demineralizers and Ion Exchangers", "What must be true to balance a chemical equation?", "The number of elemental constituents must be the same on each side of the equation.", "DOE-1015-V1 (DOE-HDBK-1015/1-93), Chemical Equations, CH-01 p. 45", null, null, "C608"],
  ["Demineralizers and Ion Exchangers", "What do pH and pOH each measure?", "pH is the negative logarithm of the hydrogen concentration in moles/liter. pOH is the negative logarithm of the hydroxyl concentration in moles/liter.", "DOE-1015-V1 (DOE-HDBK-1015/1-93), Acids, Bases, Salts, and pH, CH-01 p. 53", null, null, "C609"],
  ["Demineralizers and Ion Exchangers", "By which methods may toxic compounds enter the body?", "Ingestion, inhalation, and absorption.", "DOE-1015-V2 (DOE-HDBK-1015/2-93), Toxic Compounds, CH-05 p. 15", null, null, "C610"],
  ["Demineralizers and Ion Exchangers", "What hazard can an acid create when it reacts with metal?", "Hydrogen gas may be a byproduct, which is very explosive.", "DOE-1015-V2 (DOE-HDBK-1015/2-93), Corrosives, CH-05 p. 6", null, null, "C611"],
  ["Valves", "What does the title block of a drawing contain?", "The drawing title, the drawing number, the location, site, or vendor issuing the drawing, the design, review, and approval signatures, and the reference block.", "DOE-1016-V1 (DOE-HDBK-1016/1-93), Introduction to Print Reading, PR-01 p. 9", null, null, "C612"],
  ["Valves", "What does the grid system of a drawing do?", "It allows information to be more easily identified, using the coordinates provided by the grid.", "DOE-1016-V1 (DOE-HDBK-1016/1-93), Introduction to Print Reading, PR-01 p. 9", null, null, "C613"],
  ["Valves", "What is the purpose of fabrication, construction, and architectural drawings?", "Fabrication drawings provide the information necessary to manufacture and machine components. Construction drawings provide the information necessary to build and assemble structures and systems. Architectural drawings provide conceptual information about buildings and structures.", "DOE-1016-V2 (DOE-HDBK-1016/2-93), Engineering Fabrication, Construction, and Architectural Drawings, PR-06 p. 12", null, null, "C614"],
  ["Brittle Fracture and Vessel Thermal Stress", "What are the three common lattice structures in metals?", "Body-centered cubic, face-centered cubic, and hexagonal close-packed.", "DOE-1017-V1 (DOE-HDBK-1017/1-93), Common Lattice Types, MS-01 p. 6", null, {"f": "images/doe-1017-v1-ms-01-fig2.png", "alt": "Unit cells of body-centered cubic, face-centered cubic, and hexagonal close-packed lattices, with dots marking atoms.", "cap": "Figure 2. Common Lattice Types. Source: DOE-1017-V1 (DOE-HDBK-1017/1-93), MS-01 p. 7.", "at": "a"}, "C615"],
  ["Breakers, Relays, and Disconnects", "How should a breaker be positioned to completely de-energize a component?", "Racked out with control power fuses removed.", "LP-BREAKERS-RELAYS-AND-DISCONNECTS-PART-2, slide 1.22 Knowledge Check", null, null, "C616"],
  ["Breakers, Relays, and Disconnects", "What does loss of control power do to a breaker closing spring?", "It causes failure of the closing spring to charge.", "LP-BREAKERS-RELAYS-AND-DISCONNECTS-PART-2, slide 1.33 Circuit Breaker Control Power", null, null, "C617"],
  ["Controllers and Positioners", "What does a PLC do during operation?", "It scans inputs, sequentially evaluates functions (lines), and changes outputs if conditions are met.", "LP-DISTRIBUTED-CONTROL-SYSTEMS-DCS, slide 1.10 Programmable Logic Controllers (PLC)", null, null, "C618"],
  ["Controllers and Positioners", "In a fully redundant network, what happens to device communication when a line to one network hub fails?", "Communication to the device is retained by the redundant hub.", "LP-DISTRIBUTED-CONTROL-SYSTEMS-DCS, slide 1.24 Redundancy in Networks", null, null, "C619"],
  ["Heat Transfer and Heat Exchangers", "What is core thermal power (CTP)?", "Reactor power as a measure of heat input per unit time from the core to the primary coolant.", "LP-HEAT-TRANSFER, slide 1.41 Definitions", null, null, "C620"],
  ["Heat Transfer and Heat Exchangers", "What is percent reactor power, and how is it calculated?", "The percent of rated core thermal power at which the reactor is currently operating: (Actual CTP/Rated CTP) x 100%.", "LP-HEAT-TRANSFER, slide 1.41 Definitions", null, null, "C621"],
  ["Neutrons", "What is the macroscopic cross section?", "The probability of a given reaction occurring per unit length of travel of the neutron.", "DOE-1019-V1 (DOE-HDBK-1019/1-93), Nuclear Cross Sections and Neutron Flux, NP-02 p. 17", null, null, "C622"],
  ["Neutrons", "What is the reaction rate?", "The number of interactions of a particular type occurring in a cubic centimeter of material in a second.", "DOE-1019-V1 (DOE-HDBK-1019/1-93), Reaction Rates, NP-02 p. 22", null, null, "C623"],
  ["PSAR: Nuclear Heat Supply Systems", "What is the initial Natrium fuel, and what is its cladding?", "Sodium-bonded uranium - 10 weight percent Zirconium (U-10Zr), encapsulated by HT-9 ferritic-martensitic steel cladding.", "PSAR Rev 1, ML25276A288, Sec. 7.1.1.1, p. 7.1-1", null, null, "C624"],
  ["PSAR: Nuclear Heat Supply Systems", "What is the neutron-related purpose of the reflector assemblies?", "To reflect neutrons into the core's fueled region, which reduces core reactivity loss and limits radiation damage to permanent reactor structures.", "PSAR Rev 1, ML25276A288, Sec. 7.1.1.1, p. 7.1-3", null, null, "C625"],
  ["PSAR: Nuclear Heat Supply Systems", "What is tag gas in the fuel pins used for?", "To identify assemblies containing failed fuel pins, using an online fuel monitoring system.", "PSAR Rev 1, ML25276A288, Sec. 7.1.1.1, p. 7.1-3", null, null, "C626"],
  ["PSAR: Nuclear Heat Supply Systems", "What are the core inlet and outlet temperatures at 100% power and flow?", "Inlet 680°F (360°C). Outlet 950°F (510°C).", "PSAR Rev 1, ML25276A288, Sec. 7.1.1, Table 7.1.1-1, p. 7.1-12", null, null, "C627"],
  ["PSAR: Nuclear Heat Supply Systems", "Trace the primary coolant flow loop.", "Reactor core, hot pool, IHXs, cold pool, and PSPs.", "PSAR Rev 1, ML25276A288, Sec. 7.1.3.1, p. 7.1-50", null, null, "C628"],
  ["PSAR: Nuclear Heat Supply Systems", "What type of pumps are the Primary Sodium Pumps, and where are they?", "Two identical vertically-oriented centrifugal pumps located on opposite sides of the RV.", "PSAR Rev 1, ML25276A288, Sec. 7.1.3.2.1, p. 7.1-60", null, null, "C629"],
  ["PSAR: Nuclear Heat Supply Systems", "Why does PSP coastdown matter after a scram, PSP trip, or loss of offsite power?", "It establishes natural circulation flow sufficient to assure that fuel design limits are not exceeded.", "PSAR Rev 1, ML25276A288, Sec. 7.1.3.2.1, p. 7.1-60", null, null, "C630"],
  ["PSAR: Nuclear Heat Supply Systems", "After PSP coastdown on a loss of offsite power, what happens to primary flow?", "The pumps transition to a minimum flow if power is restored via the standby diesel generators. If power is not restored, flow reduces to natural circulation flow rates.", "PSAR Rev 1, ML25276A288, Sec. 7.1.3.1.2, p. 7.1-59", null, null, "C631"],
  ["PSAR: Nuclear Heat Supply Systems", "How is primary sodium raised to the hot zero power temperature during startup?", "The PSPs raise it.", "PSAR Rev 1, ML25276A288, Sec. 7.1.3.2.3, p. 7.1-61", null, null, "C632"],
  ["PSAR: Nuclear Heat Supply Systems", "What is the nominal PSP flow at the full power operating point?", "40,000 gpm (150 m3/s).", "PSAR Rev 1, ML25276A288, Sec. 7.1.3.2.3, Table 7.1.3-3, p. 7.1-67", "The source table gives both values, but 40,000 gpm is about 150 m3 per minute, not per second.", null, "C633"],
  ["PSAR: Nuclear Heat Supply Systems", "What type of heat exchangers are the IHXs?", "Vertical, counter-flow, single-pass, straight-tube type heat exchangers.", "PSAR Rev 1, ML25276A288, Sec. 7.1.3.3.1, p. 7.1-62", null, null, "C634"],
  ["PSAR: Nuclear Heat Supply Systems", "How would intermediate sodium leaking into primary sodium be detected?", "By IHT expansion tank level decrease and PHT hot pool level increase.", "PSAR Rev 1, ML25276A288, Sec. 7.1.3.3.3, p. 7.1-63", null, null, "C635"],
  ["PSAR: Nuclear Heat Supply Systems", "How is intermediate loop sodium flow rate controlled?", "By controlling ISP speed, with an adjustable speed drive unit that varies frequency and voltage of the input power to the pump motors.", "PSAR Rev 1, ML25276A288, Sec. 7.1.4.1, p. 7.1-75", null, null, "C636"],
  ["PSAR: Nuclear Heat Supply Systems", "Which abnormal conditions initiate emergency shutdown of the ISPs?", "Low level in an IHT expansion tank (trips the associated ISP), High-High primary sodium level (trips both ISPs), and High-High primary sodium temperature (trips both ISPs).", "PSAR Rev 1, ML25276A288, Sec. 7.1.4.3, p. 7.1-81", null, null, "C637"],
  ["PSAR: Nuclear Heat Supply Systems", "What limits how much intermediate sodium can siphon into the primary system after an IHX leak?", "Introduction of cover gas at the IHT piping high points prevents a siphon from forming.", "PSAR Rev 1, ML25276A288, Sec. 7.1.4.3, p. 7.1-80", null, null, "C638"],
  ["PSAR: Nuclear Heat Supply Systems", "Why is the IHT piping sloped?", "To allow for gravity drainage to drain tanks connected to piping low points.", "PSAR Rev 1, ML25276A288, Sec. 7.1.4.1, p. 7.1-75", null, null, "C639"],
  ["PSAR: Reactor Auxiliary Systems", "What does the Reactor Air Cooling System consist of?", "Four inlet and four outlet stacks, a Collector Cylinder Assembly (CCA), and associated inlet and outlet ducting.", "PSAR Rev 1, ML25276A288, Sec. 7.2.1.1, p. 7.2-1", null, null, "C640"],
  ["PSAR: Reactor Auxiliary Systems", "Why is the RAC inlet at a minimum elevation of 30 feet?", "It protects the inlet louvers from the external large missile (automobile) hazard.", "PSAR Rev 1, ML25276A288, Sec. 7.2.1.3, p. 7.2-6", null, null, "C641"],
  ["PSAR: Reactor Auxiliary Systems", "In IAC Active Mode, what moves the sodium and the air?", "The ISPs provide forced circulation of the intermediate sodium, and the IAC blowers provide forced airflow across the AHXs.", "PSAR Rev 1, ML25276A288, Sec. 7.2.2.3, p. 7.2-16", null, null, "C642"],
  ["PSAR: Reactor Auxiliary Systems", "What position are the AHX air dampers in during Mode-1, and why?", "Normally closed, to limit heat transferred from the intermediate sodium when the IAC is not required.", "PSAR Rev 1, ML25276A288, Sec. 7.2.2.1, p. 7.2-13", null, null, "C643"],
  ["PSAR: Reactor Auxiliary Systems", "How are sodium vapors and aerosols removed from the primary cover gas exhaust?", "The gas passes through the vapor trap, which consists of a preheater and vapor condenser, then through an aerosol filter.", "PSAR Rev 1, ML25276A288, Sec. 7.2.3.1.1, p. 7.2-22", null, null, "C644"],
  ["PSAR: Reactor Auxiliary Systems", "Which impurities are monitored in the primary cover gas?", "Hydrogen, oxygen, nitrogen, and methane.", "PSAR Rev 1, ML25276A288, Sec. 7.2.3.3, p. 7.2-34", null, null, "C645"],
  ["PSAR: Reactor Auxiliary Systems", "Which Primary SCG load has the highest delivered pressure?", "The SCRAM cylinders, which sets the minimum delivered pressure by NGA.", "PSAR Rev 1, ML25276A288, Sec. 7.2.3.1.1, p. 7.2-22", null, null, "C646"],
  ["PSAR: Reactor Auxiliary Systems", "How are the IHT loops filled with sodium from the drain tanks?", "By pneumatic loop fill: the Intermediate SCG provides gas pressure to the drain tanks.", "PSAR Rev 1, ML25276A288, Sec. 7.2.3.3, p. 7.2-35", null, null, "C647"],
  ["PSAR: Reactor Auxiliary Systems", "How does the intermediate SPS (SPS-I) differ from the primary SPS (SPS-P)?", "SPS-I does not contain a cesium trap or associated radiological monitoring.", "PSAR Rev 1, ML25276A288, Sec. 7.2.4.1, p. 7.2-41", null, null, "C648"],
  ["PSAR: Reactor Auxiliary Systems", "What reduces tritium levels in the primary coolant?", "The primary cold traps, along with hydrogen.", "PSAR Rev 1, ML25276A288, Sec. 7.2.4.3, p. 7.2-50", null, null, "C649"],
  ["PSAR: Reactor Auxiliary Systems", "What is the key process indicator for sodium purity?", "The saturation temperature, which correlates directly with impurity concentration.", "PSAR Rev 1, ML25276A288, Sec. 7.2.4.3.1, p. 7.2-51", null, null, "C650"],
  ["PSAR: Reactor Auxiliary Systems", "What material fills the cesium traps?", "Reticulated vitreous carbon.", "PSAR Rev 1, ML25276A288, Sec. 7.2.4.3, p. 7.2-50", null, null, "C651"],
  ["PSAR: Reactor Auxiliary Systems", "What does driveline scram follow provide?", "Assurance that the CRA is fully inserted, and CRA insertion position indication.", "PSAR Rev 1, ML25276A288, Sec. 7.2.5.1, p. 7.2-59", null, null, "C652"],
  ["PSAR: Reactor Auxiliary Systems", "What prevents control rod driveline motion when no demand signal is present?", "An electro-mechanical brake.", "PSAR Rev 1, ML25276A288, Sec. 7.2.5.1, p. 7.2-58", null, null, "C653"],
  ["PSAR: Integrated Controls Systems", "What does the Control Rod Drive System control interlock prevent?", "Withdrawal of more than one rod at a time.", "PSAR Rev 1, ML25276A288, Sec. 7.6.2.2.2, p. 7.6-12", null, null, "C654"],
  ["PSAR: Integrated Controls Systems", "Which high-high and low-low reactor scrams does the RPS provide as DL3 safety-related functions?", "High-high neutron flux, high-high hot pool temperature, high-high primary sodium level, high-high power-to-flow ratio, high-high cold pool temperature, high-high positive neutron flux rate, high-high negative neutron flux rate, and low-low primary sodium level.", "PSAR Rev 1, ML25276A288, Sec. 7.6.3.2.1, p. 7.6-23", null, null, "C655"],
  ["PSAR: Integrated Controls Systems", "Besides the high-high and low-low trips, which other DL3 reactor scrams does the RPS provide?", "Low power, high neutron flux; loss of primary sodium flow; and loss of power.", "PSAR Rev 1, ML25276A288, Sec. 7.6.3.2.1, p. 7.6-24", null, null, "C656"],
  ["PSAR: Integrated Controls Systems", "What do RPS outputs do on a loss of incoming power?", "They fail in the safe state, which is function DL3-RC2, reactor scram on loss of power.", "PSAR Rev 1, ML25276A288, Sec. 7.6.3.2.1, p. 7.6-24", null, null, "C657"],
  ["PSAR: Integrated Controls Systems", "What does each RPS divisional SVDU display?", "Parameters and status of the associated RPS division only.", "PSAR Rev 1, ML25276A288, Sec. 7.6.3.1, p. 7.6-18", null, null, "C658"],
  ["PSAR: Integrated Controls Systems", "How do the RPS and the NIC communicate?", "There is no direct communication from NIC systems to the RPS. One-way communication from RPS to the control systems is via a data diode or hardwired connection.", "PSAR Rev 1, ML25276A288, Sec. 7.6.2.2.2, p. 7.6-12", null, null, "C659"],
  ["PSAR: Integrated Controls Systems", "What detectors does the Nuclear Instrumentation System use, and which signal ranges do they provide?", "One High Temperature Fission Chamber detector for each division (four total). Each provides power range, wide range, and source range signals.", "PSAR Rev 1, ML25276A288, Sec. 7.6.4.1, p. 7.6-36", null, null, "C660"],
  ["PSAR: Integrated Controls Systems", "Where do operators get audible count rate indication?", "NST audible count rate devices in the MCR and FHCR, which provide source range indication via an audible signal.", "PSAR Rev 1, ML25276A288, Sec. 7.6.4.4, p. 7.6-46", null, null, "C661"],
  ["PSAR: Integrated Controls Systems", "What are the three main monitoring groups of the Radiation Monitoring System?", "Area Radiation Monitoring (ARM), Effluent Radiation Monitor (ERM), and Process Radiation Monitoring (PRM).", "PSAR Rev 1, ML25276A288, Sec. 7.6.6.1, p. 7.6-60", null, null, "C662"],
  ["PSAR: Integrated Controls Systems", "What does the AMC do when it receives a sodium leak detection signal for the SPS-P?", "It provides a signal to close the SPS-P pump supply side isolation valve and a signal to trip the SPS-P pump.", "PSAR Rev 1, ML25276A288, Sec. 7.6.2.2.1, p. 7.6-9", null, null, "C663"],
  ["PSAR: Integrated Controls Systems", "How is the Remote Shutdown Complex kept habitable?", "A manually initiated bottled air injection system provides habitability for three operators and has a 72-hour mission time.", "PSAR Rev 1, ML25276A288, Sec. 7.6.7.2, p. 7.6-72", null, null, "C664"],
  ["PSAR: Electrical Systems", "On a loss of all AC power, how long do the batteries keep the NUP inverters powered?", "72 hours for Divisions A and B, and 2 hours for Divisions C and D.", "PSAR Rev 1, ML25276A288, Sec. 7.7.1.3.1, p. 7.7-4", null, null, "C665"],
  ["PSAR: Electrical Systems", "What feeds each NUP inverter during normal operation?", "250 VDC from the respective division 250 VDC switchboard.", "PSAR Rev 1, ML25276A288, Sec. 7.7.1.3.1, p. 7.7-4", null, null, "C666"],
  ["PSAR: Electrical Systems", "Which isolation breakers get backup trip power from the NI DC Power Supply System?", "The Primary Sodium Pump, Intermediate Sodium Pump, and Sodium Processing System pump isolation breakers.", "PSAR Rev 1, ML25276A288, Sec. 7.7.1.1, p. 7.7-1", null, null, "C667"],
  ["PSAR: Nuclear Heat Supply Systems", "What are the four reactor operating modes?", "Mode-1: High Power Operation. Mode-2: Low Power Operation. Mode-3: Shutdown. Mode-4: Refuel.", "PSAR Rev 1, ML25276A288, Sec. 11.5.2, p. 11.5-1", null, null, "C668"],
  ["PSAR: Nuclear Heat Supply Systems", "When is Mode-2 entered during startup?", "When the reactor scram breakers are closed and more than one CRA is coupled to its CRDM driveline.", "PSAR Rev 1, ML25276A288, Sec. 11.5.2.2, p. 11.5-1", null, null, "C669"],
  ["PSAR: Nuclear Heat Supply Systems", "What defines each reactor operating mode?", "An inclusive combination of sodium temperature, control rod drive (CRD) status, and reactor cooling mechanism.", "PSAR Rev 1, ML25276A288, Sec. 11.5.2, p. 11.5-1", null, null, "C670"],
  ["PSAR: Fundamental Safety Functions", "How does the PSAR define shutdown margin?", "The amount of reactivity by which the reactor is subcritical, or would be subcritical from a given condition, assuming that all control rods are inserted with the exception of at least the highest worth control rod, which is assumed to be fully withdrawn.", "PSAR Rev 1, ML25276A288, Sec. 3.12.1.4, p. 3.12-2", null, null, "C671"],
  ["PSAR: Fundamental Safety Functions", "What does the loss of a primary 6.9 kilovolt bus at full power cause?", "The loss of one Primary Sodium Pump and one Intermediate Sodium Pump, followed by a reactor scram on high high power-to-flow ratio.", "PSAR Rev 1, ML25276A288, Sec. 3.6.1.4.1, p. 3.6-2", null, null, "C672"],
  ["PSAR: Fuel Handling Systems", "How is spent fuel kept subcritical in the Spent Fuel Pool?", "The storage racks control the relative spacing within the racks (geometry control) and use fixed borated neutron absorbers within the assembly storage cells. The pool does not employ soluble boron.", "PSAR Rev 1, ML25276A288, Sec. 7.3.1.1, p. 7.3-1", null, null, "C673"],
  ["PSAR: Fuel Handling Systems", "What does the Pool Immersion Cell (PIC) do?", "It transitions core assemblies being stored in a sodium environment to a water-filled environment.", "PSAR Rev 1, ML25276A288, Sec. 7.3.1.1, p. 7.3-2", null, null, "C674"],
  ["PSAR: Fuel Handling Systems", "Why is failed fuel placed in a helium-inerted failed fuel canister (FFC)?", "To prevent metallic uranium-water interactions and sodium-water reactions that can occur due to cladding failure in the sodium-bonded fuel.", "PSAR Rev 1, ML25276A288, Sec. 7.3.1.1, p. 7.3-2", null, null, "C675"],
  ["PSAR: Fuel Handling Systems", "What does the sodium-filled Core Assembly Pot (CAP) do for an irradiated core assembly?", "It acts as the heat sink and conduction path to assist in removing heat from the irradiated core assembly and preventing overheating of the fuel pins.", "PSAR Rev 1, ML25276A288, Sec. 7.3.2.1.1, p. 7.3-19", null, null, "C676"],
  ["PSAR: Fuel Handling Systems", "How soon after shutdown can the EVHM passive cooling system handle core assemblies?", "7 days after shutdown, following the installation of the IVTM and FTL.", "PSAR Rev 1, ML25276A288, Sec. 7.3.2.1.1, p. 7.3-18", null, null, "C677"],
  ["PSAR: Fuel Handling Systems", "What does the Fuel Transfer Lift (FTL) do?", "It is a vertical lift used to raise and lower core assemblies, located inside a Core Assembly Pot, into and out of the reactor.", "PSAR Rev 1, ML25276A288, Sec. 7.3.3.1, p. 7.3-41", null, null, "C678"],
  ["PSAR: Fuel Handling Systems", "What does the Rotatable Plug Jack (RPJ) do?", "It lifts the RPA off its static interface with the reactor head, transferring the weight onto the RPA bearing and allowing rotation.", "PSAR Rev 1, ML25276A288, Sec. 7.3.3.1, p. 7.3-41", null, null, "C679"],
  ["PSAR: Radwaste Systems", "What does the Gaseous Radwaste Processing System hold up for decay?", "Short-lived radioactive isotopes such as argon-41.", "PSAR Rev 1, ML25276A288, Sec. 7.4.1.1, p. 7.4-1", null, null, "C680"],
  ["PSAR: Ancillary Systems", "In radiologically controlled areas, which way does NHV control airflow?", "From areas of lesser potential contamination to areas of higher potential contamination.", "PSAR Rev 1, ML25276A288, Sec. 7.5.1.1, p. 7.5-1", null, null, "C681"],
  ["PSAR: Integrated Controls Systems", "Where are the AST seismic accelerometers located?", "In boreholes at four locations at 90-degree angles around the Reactor Building.", "PSAR Rev 1, ML25276A288, Sec. 7.6.8.1.2, p. 7.6-75", null, null, "C682"],
  ["PSAR: Fundamental Safety Functions", "Which reactor scram occurs on a loss of heat removal from one intermediate sodium loop at full power?", "High high cold pool temperature.", "PSAR Rev 1, ML25276A288, Sec. 3.7.2.1.1, p. 3.6-2", null, null, "C683"],
  ["PSAR: Fundamental Safety Functions", "What automatic actions follow an IHX tube break at full power?", "A reactor scram on high high primary sodium level, and the ISPs trip on high high primary sodium level.", "PSAR Rev 1, ML25276A288, Sec. 3.7.2.6.1, p. 3.7-4", null, null, "C684"],
  ["PSAR: Fundamental Safety Functions", "How is the reactor shut down in the local fuel fault event (blocked fuel subchannels)?", "Operators manually shut down the reactor due to exceeding failed fuel activity limits.", "PSAR Rev 1, ML25276A288, Sec. 3.7.5.1.1, p. 3.7-15", null, null, "C685"],
  ["PSAR: Fundamental Safety Functions", "In the DBE where the NSS heat removal changes at full power, how does a power runback end?", "A reactor power runback may be initiated, but a reactor scram occurs before the runback is complete.", "PSAR Rev 1, ML25276A288, Sec. 3.7.2.3.1, p. 3.7-3", null, null, "C686"],
  ["Thermodynamic Units and Properties", "What are the three fundamental dimensions?", "Length, mass, and time.", "DOE-1010 (DOE-HDBK-1010-92), Fundamental Dimensions, CP-01 p. 1", null, null, "C687"],
  ["Thermodynamic Units and Properties", "How does the handbook define mass?", "Mass is the amount of material present in an object.", "DOE-1010 (DOE-HDBK-1010-92), Fundamental Dimensions, CP-01 p. 1", null, null, "C688"],
  ["Thermodynamic Units and Properties", "What two related systems make up the SI system?", "The meter-kilogram-second (MKS) system and the centimeter-gram-second (CGS) system.", "DOE-1010 (DOE-HDBK-1010-92), Fundamental Dimensions, CP-01 p. 3", null, null, "C689"],
  ["Thermodynamic Units and Properties", "What must be done when the conversion table has no direct relationship between two units?", "Use multiple conversion factors, performing the conversion in several steps until the measurement is in the desired units.", "DOE-1010 (DOE-HDBK-1010-92), Unit Conversions, CP-01 p. 12", null, null, "C690"],
  ["Thermodynamic Units and Properties", "What are conversion factors based on?", "Relationships of equivalents from different measurement systems.", "DOE-1010 (DOE-HDBK-1010-92), Unit Conversions, CP-01 p. 9", null, null, "C691"],
  ["Basic Energy Concepts", "Name four examples of vector quantities.", "Displacement, velocity, acceleration, and force.", "DOE-1010 (DOE-HDBK-1010-92), Scalar and Vector Quantities, CP-02 p. 2", null, null, "C692"],
  ["Basic Energy Concepts", "What does the length of a drawn vector represent, and what does the arrow represent?", "The length represents the magnitude of the vector, and the arrow represents its direction.", "DOE-1010 (DOE-HDBK-1010-92), Scalar and Vector Quantities, CP-02 p. 2", null, null, "C693"],
  ["Basic Energy Concepts", "What are the components of a vector?", "Vectors which, when added, yield the vector.", "DOE-1010 (DOE-HDBK-1010-92), Vectors: Resultants and Components, CP-02 p. 10", null, null, "C694"],
  ["Basic Energy Concepts", "Which vector addition method is required for a high degree of accuracy?", "An analytical method using geometric and trigonometric functions.", "DOE-1010 (DOE-HDBK-1010-92), Graphic Method of Vector Addition, CP-02 p. 16", null, null, "C695"],
  ["Basic Energy Concepts", "State the Pythagorean Theorem.", "In any right triangle, the square of the length of the hypotenuse equals the sum of the squares of the lengths of the other two sides.", "DOE-1010 (DOE-HDBK-1010-92), Analytical Method of Vector Addition, CP-02 p. 23", null, {"f": "images/doe-1010-cp-02-fig24.png", "alt": "Right triangle with a 3 mile side and a 4 mile side. The hypotenuse R and the angle theta are the unknowns.", "cap": "Figure 24. Hypotenuse and Angle. Source: DOE-1010 (DOE-HDBK-1010-92), CP-02 p. 24.", "at": "a"}, "C696"],
  ["Basic Energy Concepts", "How is force related to the rate of change of momentum?", "The rate at which momentum changes with time is equal to the net force applied to an object.", "DOE-1010 (DOE-HDBK-1010-92), Momentum Principles, CP-03 p. 6", null, null, "C697"],
  ["Basic Energy Concepts", "Why is momentum a vector quantity?", "It results from the velocity of the object.", "DOE-1010 (DOE-HDBK-1010-92), Momentum Principles, CP-03 p. 5", null, null, "C698"],
  ["Basic Energy Concepts", "What is conserved in an elastic collision?", "Both momentum and kinetic energy.", "DOE-1010 (DOE-HDBK-1010-92), Momentum Principles, CP-03 p. 8", null, null, "C699"],
  ["Basic Energy Concepts", "State Newton's second law.", "The acceleration of a body is proportional to the net force acting on it and in the direction of that net force.", "DOE-1010 (DOE-HDBK-1010-92), Newton's Laws of Motion, CP-03 p. 1", null, null, "C700"],
  ["Basic Energy Concepts", "State the universal law of gravitation for two masses.", "The force is directly proportional to the product of the two masses and inversely proportional to the square of the distance between them.", "DOE-1010 (DOE-HDBK-1010-92), Newton's Laws of Motion, CP-03 p. 2", null, null, "C701"],
  ["Basic Energy Concepts", "What is inertia?", "The tendency of a body to resist a change in its state of motion.", "DOE-1010 (DOE-HDBK-1010-92), Force Equilibrium, CP-04 p. 12", null, null, "C702"],
  ["Basic Energy Concepts", "What is a normal force?", "Any perpendicular force with which any two surfaces are pressed against each other.", "DOE-1010 (DOE-HDBK-1010-92), Free-Body Diagrams, CP-04 p. 5", null, null, "C703"],
  ["Basic Energy Concepts", "How does the handbook define force?", "A vector quantity that tends to produce an acceleration of a body in the direction of its application.", "DOE-1010 (DOE-HDBK-1010-92), Force and Weight, CP-04 p. 2", null, null, "C704"],
  ["Basic Energy Concepts", "What direction do frictional forces act?", "Always opposite in direction to the motion, or impending motion, of the object.", "DOE-1010 (DOE-HDBK-1010-92), Types of Force, CP-04 p. 19", null, {"f": "images/doe-1010-cp-04-fig9.png", "alt": "A block on a surface with weight W and normal force N, then with applied force P and friction F, and a graph of friction force rising to FM and dropping to FK at motion.", "cap": "Figure 9. Frictional Forces. Source: DOE-1010 (DOE-HDBK-1010-92), CP-04 p. 18.", "at": "a"}, "C705"],
  ["Basic Energy Concepts", "Are fluid forces usually tensile or compressive?", "Fluid forces are almost always compressive forces.", "DOE-1010 (DOE-HDBK-1010-92), Types of Force, CP-04 p. 17", null, null, "C706"],
  ["Basic Energy Concepts", "What are the two categories of thermal and mechanical energy?", "Transient and stored.", "DOE-1010 (DOE-HDBK-1010-92), Energy and Work, CP-05 p. 1", null, null, "C707"],
  ["Basic Energy Concepts", "What is internal energy?", "The energy stored in a substance because of the motion and position of the particles of the substance.", "DOE-1010 (DOE-HDBK-1010-92), Energy and Work, CP-05 p. 3", null, null, "C708"],
  ["Basic Energy Concepts", "What is transient mechanical energy commonly called?", "Work.", "DOE-1010 (DOE-HDBK-1010-92), Energy and Work, CP-05 p. 3", null, null, "C709"],
  ["Basic Energy Concepts", "How many ft-lbf/s and watts equal one horsepower?", "550 ft-lbf/s and 745.7 watts.", "DOE-1010 (DOE-HDBK-1010-92), Power, CP-05 p. 9", null, null, "C710"],
  ["Basic Energy Concepts", "What is thermal power?", "The measure of thermal energy used per unit time.", "DOE-1010 (DOE-HDBK-1010-92), Power, CP-05 p. 8", null, null, "C711"],
  ["Basic Energy Concepts", "What is mechanical power?", "The rate at which work is done.", "DOE-1010 (DOE-HDBK-1010-92), Power, CP-05 p. 9", null, null, "C712"],
  ["Motors and Generators", "State the First Law of Electrostatics.", "Unlike charges attract each other, and like charges repel each other.", "DOE-1011-V1 (DOE-HDBK-1011/1-92), Atom and Its Forces, ES-01 p. 3", null, null, "C713"],
  ["Motors and Generators", "What is electromotive force (EMF)?", "The sum of the potential differences of all charged particles in the electrostatic field.", "DOE-1011-V1 (DOE-HDBK-1011/1-92), Atom and Its Forces, ES-01 p. 6", null, null, "C714"],
  ["Motors and Generators", "State the three ways to write Ohm's Law from E, I, and R.", "E = IR, I = E/R, and R = E/I. If any two of the values are known, the third can be calculated.", "DOE-1011-V1 (DOE-HDBK-1011/1-92), Units of Electrical Measurement, ES-01 p. 15", null, null, "C715"],
  ["Motors and Generators", "What is magnetic flux?", "The group of magnetic field lines emitted outward from the north pole of a magnet.", "DOE-1011-V1 (DOE-HDBK-1011/1-92), Magnetism, ES-01 p. 29", null, null, "C716"],
  ["Motors and Generators", "What is permeability?", "The ability of a material to concentrate magnetic lines of flux.", "DOE-1011-V1 (DOE-HDBK-1011/1-92), Magnetism, ES-01 p. 30", null, null, "C717"],
  ["Motors and Generators", "What two factors set the magnitude of an induced voltage?", "The number of turns of a coil, and how fast the conductor cuts across the magnetic lines of force, or flux.", "DOE-1011-V1 (DOE-HDBK-1011/1-92), Magnetic Circuits, ES-01 p. 42", null, null, "C718"],
  ["Breakers, Relays, and Disconnects", "What are the four types of circuit diagrams?", "Schematic, one-line, block, and wiring diagrams.", "DOE-1011-V1 (DOE-HDBK-1011/1-92), DC Circuit Terminology, ES-02 p. 22", null, null, "C719"],
  ["Breakers, Relays, and Disconnects", "How does a diode act in a rectifier?", "As a gate, which allows current to pass in one direction and blocks current in the other direction.", "DOE-1011-V1 (DOE-HDBK-1011/1-92), DC Sources, ES-02 p. 5", null, null, "C720"],
  ["Breakers, Relays, and Disconnects", "What is resistivity?", "The measure of the resistance a material imposes on current flow.", "DOE-1011-V1 (DOE-HDBK-1011/1-92), DC Circuit Terminology, ES-02 p. 16", null, null, "C721"],
  ["Breakers, Relays, and Disconnects", "Compare the equivalent resistance of a parallel circuit to its individual resistors.", "The equivalent resistance is always less than any of the individual parallel circuit resistors.", "DOE-1011-V1 (DOE-HDBK-1011/1-92), DC Circuit Terminology, ES-02 p. 21", null, null, "C722"],
  ["Breakers, Relays, and Disconnects", "What is the only current limit in a DC circuit?", "The circuit resistance.", "DOE-1011-V1 (DOE-HDBK-1011/1-92), DC Circuit Faults, ES-02 p. 68", null, null, "C723"],
  ["Breakers, Relays, and Disconnects", "What protects circuits against short circuits?", "Fuses.", "DOE-1011-V1 (DOE-HDBK-1011/1-92), DC Circuit Faults, ES-02 p. 68", null, null, "C724"],
  ["Motors and Generators", "How is the time constant for an inductor defined?", "The time required for the current either to increase to 63.2 percent of its maximum value or to decrease by 63.2 percent of its maximum value.", "DOE-1011-V2 (DOE-HDBK-1011/2-92), Inductance, ES-03 p. 5", null, {"f": "images/doe-1011-v2-es-03-fig7.png", "alt": "Graph of percent of maximum against time in time constants, with one curve rising to 63 percent and another falling, at one time constant.", "cap": "Figure 7. Time Constant. Source: DOE-1011-V2 (DOE-HDBK-1011/2-92), ES-03 p. 5.", "at": "a"}, "C725"],
  ["Motors and Generators", "How many time constants does it take for circuit parameters to reach their final value?", "After five time constants, circuit parameters normally reach their final value.", "DOE-1011-V2 (DOE-HDBK-1011/2-92), Inductance, ES-03 p. 6", null, null, "C726"],
  ["Motors and Generators", "What does a farad measure?", "Capacitance. A farad will store one coulomb of charge when one volt is applied across the plates.", "DOE-1011-V2 (DOE-HDBK-1011/2-92), Capacitance, ES-03 p. 11", null, null, "C727"],
  ["Motors and Generators", "What three things does the capacitance of a capacitor depend on?", "Area of the conductor plates, separation between the plates, and the dielectric constant of the insulation material.", "DOE-1011-V2 (DOE-HDBK-1011/2-92), Capacitance, ES-03 p. 11", null, null, "C728"],
  ["Motors and Generators", "How is the capacitive time constant defined?", "The time required for the capacitor to charge to 63.2 percent of its fully charged voltage.", "DOE-1011-V2 (DOE-HDBK-1011/2-92), Capacitance, ES-03 p. 16", null, {"f": "images/doe-1011-v2-es-03-fig18.png", "alt": "Graph of capacitor voltage as percent of maximum against time in time constants, rising to 63 percent at one time constant and near full at five.", "cap": "Figure 18. Capacitive Time Constant for Charging Capacitor. Source: DOE-1011-V2 (DOE-HDBK-1011/2-92), ES-03 p. 17.", "at": "a"}, "C729"],
  ["Motors and Generators", "What is a dry cell, and what is a wet cell?", "If the electrolyte is a paste, the cell is a dry cell. If the electrolyte is a solution, it is a wet cell.", "DOE-1011-V2 (DOE-HDBK-1011/2-92), Battery Terminology, ES-04 p. 1", null, null, "C730"],
  ["Motors and Generators", "What is an ampere-hour?", "A current of one ampere flowing for one hour.", "DOE-1011-V2 (DOE-HDBK-1011/2-92), Battery Terminology, ES-04 p. 2", null, null, "C731"],
  ["Motors and Generators", "What are the plates of a lead-acid battery made of?", "The positive plate is lead peroxide (PbO2), and the negative plate is sponge lead (Pb).", "DOE-1011-V2 (DOE-HDBK-1011/2-92), Battery Theory, ES-04 p. 6", null, {"f": "images/doe-1011-v2-es-04-fig5.png", "alt": "A lead-acid cell on charge connected to a charger, with the plates changing back to lead peroxide and sponge lead.", "cap": "Figure 5. Chemical Action During Charging. Source: DOE-1011-V2 (DOE-HDBK-1011/2-92), ES-04 p. 7.", "at": "a"}, "C732"],
  ["Motors and Generators", "Why is ventilation needed while a battery is charging?", "Hydrogen is highly explosive.", "DOE-1011-V2 (DOE-HDBK-1011/2-92), Battery Theory, ES-04 p. 7", null, null, "C733"],
  ["Motors and Generators", "What is the shelf life of a battery?", "The time a battery may be stored and not lose more than 10 percent of its original capacity.", "DOE-1011-V2 (DOE-HDBK-1011/2-92), Battery Operations, ES-04 p. 13", null, null, "C734"],
  ["Motors and Generators", "What temperature can damage a battery and cause early failure?", "Very high temperatures, 125°F and higher.", "DOE-1011-V2 (DOE-HDBK-1011/2-92), Battery Hazards, ES-04 p. 18", null, null, "C735"],
  ["Motors and Generators", "What is commutation?", "The positioning of the DC generator brushes so that the commutator segments change brushes at the same time the armature current changes direction.", "DOE-1011-V2 (DOE-HDBK-1011/2-92), DC Equipment Terminology, ES-05 p. 1", null, null, "C736"],
  ["Motors and Generators", "What are the four ratings of a DC generator?", "Voltage, current, power, and speed.", "DOE-1011-V2 (DOE-HDBK-1011/2-92), DC Generator Theory, ES-05 p. 10", null, null, "C737"],
  ["Motors and Generators", "What are eddy-currents?", "Circulating currents within the iron core.", "DOE-1011-V2 (DOE-HDBK-1011/2-92), DC Generator Theory, ES-05 p. 10", null, null, "C738"],
  ["Motors and Generators", "How are eddy-currents reduced?", "The armature and field cores are constructed from laminated steel sheets, insulated from one another.", "DOE-1011-V2 (DOE-HDBK-1011/2-92), DC Generator Theory, ES-05 p. 11", null, null, "C739"],
  ["Motors and Generators", "What is copper loss?", "The power lost as heat in the windings.", "DOE-1011-V2 (DOE-HDBK-1011/2-92), DC Generator Theory, ES-05 p. 10", null, null, "C740"],
  ["Motors and Generators", "What is a differentially-compounded generator?", "One whose two fields are wound so that their flux fields oppose one another.", "DOE-1011-V2 (DOE-HDBK-1011/2-92), DC Generator Construction, ES-05 p. 16", null, null, "C741"],
  ["Motors and Generators", "What two conditions produce the force in a DC motor's right-hand rule?", "The conductor must be carrying current, and it must be within a magnetic field.", "DOE-1011-V2 (DOE-HDBK-1011/2-92), DC Motor Theory, ES-06 p. 1", null, {"f": "images/doe-1011-v2-es-06-fig4.png", "alt": "A right hand with the forefinger along the magnetic field, the center finger along the current, and the thumb along the force on the conductor.", "cap": "Figure 4. Right-Hand Rule for Motors. Source: DOE-1011-V2 (DOE-HDBK-1011/2-92), ES-06 p. 3.", "at": "a"}, "C742"],
  ["Motors and Generators", "What is torque?", "That force which tends to produce and maintain rotation.", "DOE-1011-V2 (DOE-HDBK-1011/2-92), DC Motor Theory, ES-06 p. 4", null, null, "C743"],
  ["Motors and Generators", "How is the speed of a DC motor changed?", "By using resistors to vary the field current and, therefore, the field strength.", "DOE-1011-V2 (DOE-HDBK-1011/2-92), DC Motor Theory, ES-06 p. 7", null, null, "C744"],
  ["Motors and Generators", "How is a shunt-wound DC motor classified by speed?", "As a constant speed motor, even though the speed does slightly decrease as load is increased.", "DOE-1011-V2 (DOE-HDBK-1011/2-92), Types of DC Motors, ES-06 p. 9", null, {"f": "images/doe-1011-v2-es-06-fig8.png", "alt": "Graph of torque against speed for a shunt-wound motor, falling slowly, then dropping rapidly at high speed.", "cap": "Figure 8. Torque-vs-Speed for a Shunt-Wound DC Motor. Source: DOE-1011-V2 (DOE-HDBK-1011/2-92), ES-06 p. 9.", "at": "a"}, "C745"],
  ["Motors and Generators", "What is the advantage of a series-wound motor?", "It develops a large torque and can be operated at low speed.", "DOE-1011-V2 (DOE-HDBK-1011/2-92), Types of DC Motors, ES-06 p. 10", null, {"f": "images/doe-1011-v2-es-06-fig9.png", "alt": "Graph of torque against speed for a series-wound motor, very high at low speed and falling steeply as speed rises.", "cap": "Figure 9. Torque-vs-Speed for a Series-Wound Motor. Source: DOE-1011-V2 (DOE-HDBK-1011/2-92), ES-06 p. 10.", "at": "a"}, "C746"],
  ["Motors and Generators", "To what value do starting resistors usually limit starting current?", "125 to 200 percent of full load current.", "DOE-1011-V2 (DOE-HDBK-1011/2-92), DC Motor Operation, ES-06 p. 12", null, null, "C747"],
  ["Motors and Generators", "What is the peak voltage of an AC sine wave?", "The maximum voltage for an AC sine wave. The value of Emax occurs at 90°.", "DOE-1011-V3 (DOE-HDBK-1011/3-92), AC Generation Analysis, ES-07 p. 5", null, {"f": "images/doe-1011-v3-es-07-fig3.png", "alt": "A rotating loop beside one cycle of a sine wave, with numbered points marking the phase around the cycle.", "cap": "Figure 3. Voltage Sine Wave. Source: DOE-1011-V3 (DOE-HDBK-1011/3-92), ES-07 p. 4.", "at": "a"}, "C748"],
  ["Motors and Generators", "What is phase angle?", "The fraction of a cycle, in degrees, that has gone by since a voltage or current has passed through a given value.", "DOE-1011-V3 (DOE-HDBK-1011/3-92), AC Generation Analysis, ES-07 p. 7", null, null, "C749"],
  ["Motors and Generators", "How much rotation generates one cycle of the sine wave?", "One cycle is generated when the coil rotates 2π radians.", "DOE-1011-V3 (DOE-HDBK-1011/3-92), AC Generation Analysis, ES-07 p. 9", null, null, "C750"],
  ["Motors and Generators", "What kind of values are normally assumed for AC current and voltage?", "RMS values.", "DOE-1011-V3 (DOE-HDBK-1011/3-92), AC Generation Analysis, ES-07 p. 5", null, null, "C751"],
  ["Motors and Generators", "Convert a peak value to an effective (RMS) value.", "Effective value (RMS) = peak value x 0.707.", "DOE-1011-V3 (DOE-HDBK-1011/3-92), AC Generation Analysis, ES-07 p. 5", null, null, "C752"],
  ["Motors and Generators", "What is capacitive reactance?", "The opposition by a capacitor or a capacitive circuit to the flow of current.", "DOE-1011-V3 (DOE-HDBK-1011/3-92), Capacitance, ES-08 p. 6", null, null, "C753"],
  ["Motors and Generators", "What is net reactance?", "The difference between inductive and capacitive reactance.", "DOE-1011-V3 (DOE-HDBK-1011/3-92), Impedance, ES-08 p. 10", null, {"f": "images/doe-1011-v3-es-08-fig5.png", "alt": "Phasor diagram with resistance on the zero axis, inductive reactance up, capacitive reactance down, and impedance Z as the vector sum.", "cap": "Figure 5. Relationship Between Resistance, Reactance, and Impedance. Source: DOE-1011-V3 (DOE-HDBK-1011/3-92), ES-08 p. 10.", "at": "a"}, "C754"],
  ["Motors and Generators", "What does impedance in an AC circuit correspond to in a DC circuit?", "The resistance of a DC circuit.", "DOE-1011-V3 (DOE-HDBK-1011/3-92), Impedance, ES-08 p. 11", null, null, "C755"],
  ["Motors and Generators", "What are diagrams of rotating voltage and current vectors called?", "Phasor diagrams.", "DOE-1011-V3 (DOE-HDBK-1011/3-92), Inductance, ES-08 p. 3", null, null, "C756"],
  ["Motors and Generators", "What is the impedance of a series R-C-L circuit at resonance?", "It is equal to the circuit resistance.", "DOE-1011-V3 (DOE-HDBK-1011/3-92), Resonance, ES-08 p. 19", null, null, "C757"],
  ["Motors and Generators", "How is impedance found in a parallel R-C-L circuit?", "It equals the voltage divided by the total current.", "DOE-1011-V3 (DOE-HDBK-1011/3-92), Impedance, ES-08 p. 15", null, {"f": "images/doe-1011-v3-es-08-fig10.png", "alt": "A resistor, an inductor, and a capacitor in parallel across an AC source, with branch currents.", "cap": "Figure 10. Simple Parallel R-C-L Circuit. Source: DOE-1011-V3 (DOE-HDBK-1011/3-92), ES-08 p. 16.", "at": "a"}, "C758"],
  ["Motors and Generators", "In what units are apparent, true, and reactive power measured?", "Apparent power in volt-amperes (VA), true power in watts, and reactive power in volt-amperes-reactive (VAR).", "DOE-1011-V3 (DOE-HDBK-1011/3-92), Power Triangle, ES-09 p. 2", null, null, "C759"],
  ["Motors and Generators", "Over what range can power factor vary?", "From 1, when the phase angle is 0°, to 0, when the phase angle is 90°.", "DOE-1011-V3 (DOE-HDBK-1011/3-92), Power Triangle, ES-09 p. 4", null, null, "C760"],
  ["Motors and Generators", "What does ELI the ICE man help you remember?", "ELI: in an inductive circuit, current lags voltage. ICE: in a capacitive circuit, current leads voltage.", "DOE-1011-V3 (DOE-HDBK-1011/3-92), Power Triangle, ES-09 p. 4", null, null, "C761"],
  ["Motors and Generators", "How far apart are the three voltages of a three-phase generator?", "Each is 120° out of phase with the other voltages.", "DOE-1011-V3 (DOE-HDBK-1011/3-92), Three-Phase Circuits, ES-09 p. 17", null, null, "C762"],
  ["Motors and Generators", "What is a delta connection?", "The three phases are connected in series to form a closed loop.", "DOE-1011-V3 (DOE-HDBK-1011/3-92), Three-Phase Circuits, ES-09 p. 18", null, null, "C763"],
  ["Motors and Generators", "What is a wye connection?", "The three common ends of each phase are connected at a common point, and the other three ends are connected to a 3φ line.", "DOE-1011-V3 (DOE-HDBK-1011/3-92), Three-Phase Circuits, ES-09 p. 18", null, null, "C764"],
  ["Motors and Generators", "What does the magnitude of AC voltage from a generator depend on?", "The field strength and the speed of the rotor.", "DOE-1011-V3 (DOE-HDBK-1011/3-92), AC Generator Theory, ES-10 p. 5", null, null, "C765"],
  ["Motors and Generators", "What three conditions must be met before paralleling AC generators, in short?", "Equal terminal voltages, equal frequencies, and output voltages in phase.", "DOE-1011-V3 (DOE-HDBK-1011/3-92), AC Generator Operation, ES-10 p. 10", null, null, "C766"],
  ["Motors and Generators", "How is phase matched when paralleling generators?", "With a synchroscope.", "DOE-1011-V3 (DOE-HDBK-1011/3-92), AC Generator Operation, ES-10 p. 10", null, null, "C767"],
  ["Motors and Generators", "What is efficiency of an AC generator?", "The ratio of the useful power output to the total power input.", "DOE-1011-V3 (DOE-HDBK-1011/3-92), AC Generator Theory, ES-10 p. 7", null, null, "C768"],
  ["Motors and Generators", "Which type of AC generator do small units usually use?", "A stationary field and a rotating armature.", "DOE-1011-V3 (DOE-HDBK-1011/3-92), AC Generator Operation, ES-10 p. 10", null, {"f": "images/doe-1011-v3-es-10-fig6.png", "alt": "A rotating field with slip rings and brushes for DC excitation, inside a stationary armature that carries the AC output.", "cap": "Figure 6. Simple AC Generator - Rotating Field, Stationary Armature. Source: DOE-1011-V3 (DOE-HDBK-1011/3-92), ES-10 p. 11.", "at": "a"}, "C769"],
  ["Motors and Generators", "What is motoring?", "A frequency mismatch causes the generator with the lower frequency to be picked up as a load on the other generator.", "DOE-1011-V3 (DOE-HDBK-1011/3-92), AC Generator Operation, ES-10 p. 10", null, null, "C770"],
  ["Controllers and Positioners", "What does the comparison circuit of a voltage regulator produce?", "An error signal, from comparing the reference voltage to the sensed voltage.", "DOE-1011-V3 (DOE-HDBK-1011/3-92), Voltage Regulators, ES-11 p. 2", null, {"f": "images/doe-1011-v3-es-11-fig1.png", "alt": "Block diagram of a voltage regulator: sensing and reference circuits feed a comparison circuit, then an amplifier and signal output circuit to the generator field, with a feedback path.", "cap": "Figure 1. Voltage Regulator Block Diagram. Source: DOE-1011-V3 (DOE-HDBK-1011/3-92), ES-11 p. 2.", "at": "a"}, "C771"],
  ["Controllers and Positioners", "What does the sensing circuit of a voltage regulator do?", "It senses the output voltage of the AC generator.", "DOE-1011-V3 (DOE-HDBK-1011/3-92), Voltage Regulators, ES-11 p. 2", null, {"f": "images/doe-1011-v3-es-11-fig1.png", "alt": "Block diagram of a voltage regulator: sensing and reference circuits feed a comparison circuit, then an amplifier and signal output circuit to the generator field, with a feedback path.", "cap": "Figure 1. Voltage Regulator Block Diagram. Source: DOE-1011-V3 (DOE-HDBK-1011/3-92), ES-11 p. 2.", "at": "a"}, "C772"],
  ["Controllers and Positioners", "What does the amplification circuit of a voltage regulator do?", "It takes the signal from the comparison circuit and amplifies the milliamp input to an amp output.", "DOE-1011-V3 (DOE-HDBK-1011/3-92), Voltage Regulators, ES-11 p. 2", null, {"f": "images/doe-1011-v3-es-11-fig1.png", "alt": "Block diagram of a voltage regulator: sensing and reference circuits feed a comparison circuit, then an amplifier and signal output circuit to the generator field, with a feedback path.", "cap": "Figure 1. Voltage Regulator Block Diagram. Source: DOE-1011-V3 (DOE-HDBK-1011/3-92), ES-11 p. 2.", "at": "a"}, "C773"],
  ["Motors and Generators", "What is breakdown torque?", "The maximum value of torque of an induction motor.", "DOE-1011-V4 (DOE-HDBK-1011/4-92), AC Motor Theory, ES-12 p. 7", null, null, "C774"],
  ["Motors and Generators", "What is pull-out torque?", "The maximum value of torque that a motor can develop without losing synchronism.", "DOE-1011-V4 (DOE-HDBK-1011/4-92), AC Motor Types, ES-12 p. 13", null, null, "C775"],
  ["Motors and Generators", "Why must the rotor of an induction motor turn slower than the stator field?", "So that relative motion exists between the two.", "DOE-1011-V4 (DOE-HDBK-1011/4-92), AC Motor Theory, ES-12 p. 5", null, {"f": "images/doe-1011-v4-es-12-fig3.png", "alt": "An induction motor rotor between stator poles, with the rotating stator field and induced rotor current.", "cap": "Figure 3. Induction Motor. Source: DOE-1011-V4 (DOE-HDBK-1011/4-92), ES-12 p. 5.", "at": "a"}, "C776"],
  ["Motors and Generators", "What makes the three stator fields of a three-phase motor 120° apart?", "The currents in the three windings are 120° out of phase.", "DOE-1011-V4 (DOE-HDBK-1011/4-92), AC Motor Theory, ES-12 p. 1", null, {"f": "images/doe-1011-v4-es-12-fig1.png", "alt": "A three-phase stator shown one phase at a time and then with all three phases together.", "cap": "Figure 1. Three-Phase Stator. Source: DOE-1011-V4 (DOE-HDBK-1011/4-92), ES-12 p. 2.", "at": "a"}, "C777"],
  ["Motors and Generators", "What is a step-up transformer?", "One whose secondary voltage is greater than its primary voltage.", "DOE-1011-V4 (DOE-HDBK-1011/4-92), Transformer Theory, ES-13 p. 5", null, null, "C778"],
  ["Motors and Generators", "How do transformer current and voltage relate?", "The current in the windings is inversely proportional to the voltage in the windings.", "DOE-1011-V4 (DOE-HDBK-1011/4-92), Transformer Theory, ES-13 p. 7", null, null, "C779"],
  ["Motors and Generators", "What is the voltage ratio of a transformer equal to?", "The turns ratio.", "DOE-1011-V4 (DOE-HDBK-1011/4-92), Transformer Theory, ES-13 p. 5", null, null, "C780"],
  ["Motors and Generators", "What is the primary winding of a transformer?", "The coil that is energized from an AC source.", "DOE-1011-V4 (DOE-HDBK-1011/4-92), Transformer Theory, ES-13 p. 3", null, null, "C781"],
  ["Motors and Generators", "Where are power transformers used?", "In electronic circuits, in many different types and applications.", "DOE-1011-V4 (DOE-HDBK-1011/4-92), Transformer Types, ES-13 p. 17", null, null, "C782"],
  ["Sensors and Detectors", "What is the loading effect of a voltmeter?", "The reduction in measured voltage caused by the meter drawing current from the circuit.", "DOE-1011-V4 (DOE-HDBK-1011/4-92), Voltmeters, ES-14 p. 6", null, null, "C783"],
  ["Sensors and Detectors", "Why is a component removed from the circuit for an ohm meter reading?", "If a parallel path exists, current flows in the path of least resistance and gives an erroneous reading.", "DOE-1011-V4 (DOE-HDBK-1011/4-92), Ohm Meters, ES-14 p. 15", null, {"f": "images/doe-1011-v4-es-14-fig9.png", "alt": "A simple ohm meter: a battery, a meter movement, and resistor Ro in series, with terminals a and b connected to an unknown resistance.", "cap": "Figure 9. Simple Ohm Meter Circuit. Source: DOE-1011-V4 (DOE-HDBK-1011/4-92), ES-14 p. 15.", "at": "a"}, "C784"],
  ["Sensors and Detectors", "How many wattmeters are normally used for three-phase power measurements?", "Two.", "DOE-1011-V4 (DOE-HDBK-1011/4-92), Wattmeters, ES-14 p. 21", null, null, "C785"],
  ["Sensors and Detectors", "What is the most commonly used multimeter?", "The volt-ohm-milliammeter (VOM).", "DOE-1011-V4 (DOE-HDBK-1011/4-92), Test Equipment, ES-14 p. 28", null, null, "C786"],
  ["Sensors and Detectors", "What does a ground detector detect?", "Conductor insulation resistance to ground.", "DOE-1011-V4 (DOE-HDBK-1011/4-92), Other Electrical Measuring Devices, ES-14 p. 24", null, null, "C787"],
  ["Breakers, Relays, and Disconnects", "What is the difference between an LVP and an LVR controller?", "Both de-energize the motor on low voltage. An LVP keeps it from restarting automatically, and an LVR restarts it when normal voltage is restored.", "DOE-1011-V4 (DOE-HDBK-1011/4-92), Motor Controllers, ES-15 p. 19", null, {"f": "images/doe-1011-v4-es-15-fig13.png", "alt": "LVR controller circuit with a START-RUN switch, contactor coil M, and overloads on the motor lines.", "cap": "Figure 13. LVR Controller. Source: DOE-1011-V4 (DOE-HDBK-1011/4-92), ES-15 p. 19.", "at": "a"}, "C788"],
  ["Breakers, Relays, and Disconnects", "What must be done before operating a disconnect?", "Open the breaker first. Never operate a disconnect under load.", "LP-BREAKERS-RELAYS-AND-DISCONNECTS-PART-1 (Breakers, Relays, and Disconnects Part 1.docx), slide 1.24 Knowledge Check", null, null, "C789"],
  ["Breakers, Relays, and Disconnects", "How is a breaker in the TRIP FREE position reset?", "It must be positioned to the OPEN position first.", "LP-BREAKERS-RELAYS-AND-DISCONNECTS-PART-2 (Breakers, Relays, and Disconnects Part 2.docx), slide 1.41 Resetting a Breaker", null, null, "C790"],
  ["Breakers, Relays, and Disconnects", "What protects a circuit from an overcurrent condition only?", "A fuse.", "DOE-1011-V4 (DOE-HDBK-1011/4-92), System Components and Protection Devices, ES-15 p. 5", null, null, "C791"],
  ["Breakers, Relays, and Disconnects", "What is a leg in a power distribution system?", "A current-carrying conductor intended to deliver power to or from a load, normally at an electrical potential other than ground.", "DOE-1011-V4 (DOE-HDBK-1011/4-92), Wiring Schemes and Grounding, ES-15 p. 22", null, null, "C792"],
  ["Thermodynamic Units and Properties", "How do intensive and extensive properties differ?", "An intensive property is independent of the amount of mass. An extensive property varies directly with the mass.", "DOE-1012-V1 (DOE-HDBK-1012/1-92), Thermodynamic Properties, HT-01 p. 4", null, null, "C793"],
  ["Thermodynamic Processes", "How do isolated, closed, and open systems differ?", "Isolated: neither mass nor energy crosses the boundary. Closed: only energy crosses. Open: both mass and energy cross.", "DOE-1012-V1 (DOE-HDBK-1012/1-92), Thermodynamic Systems and Processes, HT-01 p. 27", null, null, "C794"],
  ["Basic Energy Concepts", "What does entropy quantify?", "The energy of a substance that is no longer available to perform useful work.", "DOE-1012-V1 (DOE-HDBK-1012/1-92), Energy, Work, and Heat, HT-01 p. 22", null, null, "C795"],
  ["Thermodynamic Cycles", "What is the Carnot efficiency equation?", "η = (TH - TC)/TH, using absolute temperatures. It is an upper limit that no real system reaches.", "DOE-1012-V1 (DOE-HDBK-1012/1-92), Second Law of Thermodynamics, HT-01 p. 74", null, {"f": "images/doe-1012-v1-ht-01-fig21.png", "alt": "Carnot cycle as a rectangle on a T-s diagram between TH and TC, with points 1 to 4 and a sketch of an engine between TH and TC beside it.", "cap": "Figure 21. Carnot Cycle Representation. Source: DOE-1012-V1 (DOE-HDBK-1012/1-92), HT-01 p. 73.", "at": "a"}, "C796"],
  ["Thermodynamic Cycles", "How does a real expansion look on a T-s diagram compared with an ideal one?", "The ideal process is a vertical line. The real process slants slightly to the right because entropy increases.", "DOE-1012-V1 (DOE-HDBK-1012/1-92), Second Law of Thermodynamics, HT-01 p. 77", null, {"f": "images/doe-1012-v1-ht-01-fig24.png", "alt": "T-s diagram with ideal and real compression and expansion paths drawn between two constant pressure lines.", "cap": "Figure 24. Expansion and Compression Processes on T-s Diagram. Source: DOE-1012-V1 (DOE-HDBK-1012/1-92), HT-01 p. 78.", "at": "a"}, "C797"],
  ["Steam", "What is the thumb rule for pressure in a water-solid system?", "Pressure rises about 100 psi for every 1 °F increase in temperature.", "DOE-1012-V1 (DOE-HDBK-1012/1-92), Compression Processes, HT-01 p. 101", null, null, "C798"],
  ["Heat Transfer and Heat Exchangers", "What are the three modes of heat transfer?", "Conduction, convection, and radiation.", "DOE-1012-V2 (DOE-HDBK-1012/2-92), Heat Transfer Terminology, HT-02 p. 2", null, null, "C799"],
  ["Heat Transfer and Heat Exchangers", "What is the equation for convection heat transfer?", "Q̇ = hA∆T.", "DOE-1012-V2 (DOE-HDBK-1012/2-92), Convection Heat Transfer, HT-02 p. 19", null, null, "C800"],
  ["Heat Transfer and Heat Exchangers", "What is a black body?", "A body that emits the maximum amount of heat for its absolute temperature.", "DOE-1012-V2 (DOE-HDBK-1012/2-92), Radiant Heat Transfer, HT-02 p. 26", null, null, "C801"],
  ["Heat Transfer and Heat Exchangers", "What are the advantages of a counter-flow heat exchanger?", "More uniform temperature difference, lower thermal stress, and a cold outlet that can approach the hot inlet temperature.", "DOE-1012-V2 (DOE-HDBK-1012/2-92), Heat Exchangers, HT-02 p. 33", null, {"f": "images/doe-1012-v2-ht-02-fig10.png", "alt": "Temperature against length: parallel flow curves start far apart and converge, and counter-flow curves stay about evenly spaced.", "cap": "Figure 10. Heat Exchanger Temperature Profiles. Source: DOE-1012-V2 (DOE-HDBK-1012/2-92), HT-02 p. 33.", "at": "a"}, "C802"],
  ["Steam", "What is DNB?", "Departure from nucleate boiling: the point of transition from nucleate boiling to film boiling.", "DOE-1012-V2 (DOE-HDBK-1012/2-92), Boiling Heat Transfer, HT-02 p. 42", null, {"f": "images/doe-1012-v2-ht-02-fig13.png", "alt": "Heat flux against temperature difference, rising through natural convection and nucleate boiling to a peak, falling through partial film boiling, and rising again in film boiling.", "cap": "Figure 13. Boiling Heat Transfer Curve. Source: DOE-1012-V2 (DOE-HDBK-1012/2-92), HT-02 p. 42.", "at": "a"}, "C803"],
  ["Thermal Hydraulics", "How do temperature, flow, and power relate in the core?", "At constant flow, temperature varies directly with power. At constant power, temperature varies inversely with flow.", "DOE-1012-V2 (DOE-HDBK-1012/2-92), Heat Generation, HT-02 p. 45", null, null, "C804"],
  ["Thermal Hydraulics", "About how much does decay heat fall after shutdown, per the handbook?", "From roughly 7% of prior power to about 2% within the first hour and 1% within the first day.", "DOE-1012-V2 (DOE-HDBK-1012/2-92), Decay Heat, HT-02 p. 52", null, null, "C805"],
  ["Core Thermal Limits", "What is FCCI?", "Fuel Cladding Chemical Interaction: metallic fuel reacting with the cladding at high temperature to form a low melting point eutectic.", "ML19149A371, Fast Reactor Fuels, slide 24", null, null, "C806"],
  ["Fluid Statics and Dynamics", "What are the Reynolds number limits for flow regimes?", "Below 2000 is laminar. Above 3500 is turbulent. Between them is transitional.", "DOE-1012-V3 (DOE-HDBK-1012/3-92), Laminar and Turbulent Flow, HT-03 p. 20", null, null, "C807"],
  ["Fluid Statics and Dynamics", "What is the term head with respect to fluid flow?", "A reference to pressure, as the height in feet of a column of water that a given pressure will support.", "DOE-1012-V3 (DOE-HDBK-1012/3-92), Bernoulli's Equation, HT-03 p. 23", null, null, "C808"],
  ["Pumps", "What are the pump laws?", "Flow varies with speed, head with the square of speed, and power with the cube of speed.", "DOE-1012-V3 (DOE-HDBK-1012/3-92), Centrifugal Pumps, HT-03 p. 49", null, null, "C809"],
  ["Steam", "What is two-phase flow?", "The simultaneous flow of liquid and vapor, such as water and steam.", "DOE-1012-V3 (DOE-HDBK-1012/3-92), Two-Phase Fluid Flow, HT-03 p. 41", null, null, "C810"],
  ["Thermal Hydraulics", "What are the indications of natural circulation in the sodium system?", "Core exit temperature rising initially and then stabilizing, and air heated by a sodium to air heat exchanger with stable sodium temperatures.", "LP-THERMAL-HYDRAULICS (Thermal Hydraulics.docx), slide 1.36 Indications of Natural Circulation", null, null, "C811"],
  ["Sensors and Detectors", "How does an RTD respond to a temperature rise?", "Its resistance increases, because resistance varies directly with temperature.", "DOE-1013-V1 (DOE-HDBK-1013/1-92), Resistance Temperature Detectors (RTDs), IC-01 p. 4", null, null, "C812"],
  ["Sensors and Detectors", "What is a dual-element RTD?", "An RTD with two sensing elements, of which only one is normally connected. The second can be used if the first fails.", "DOE-1013-V1 (DOE-HDBK-1013/1-92), Functional Uses of Temperature Detectors, IC-01 p. 8", null, null, "C813"],
  ["Sensors and Detectors", "What is a contact pyrometer?", "A portable thermocouple used to read temperature on accessible equipment.", "DOE-1013-V1 (DOE-HDBK-1013/1-92), Functional Uses of Temperature Detectors, IC-01 p. 8", null, null, "C814"],
  ["Sensors and Detectors", "What are the three methods of bridge compensation for ambient temperature?", "Measuring circuit resistor selection, electronic circuitry design, and three or four wire RTD circuits.", "DOE-1013-V1 (DOE-HDBK-1013/1-92), Temperature Detection Circuitry, IC-01 p. 15", null, null, "C815"],
  ["Sensors and Detectors", "How does an open RTD fail compared with a shorted RTD?", "Open reads very high temperature. Shorted reads very low temperature.", "DOE-1013-V1 (DOE-HDBK-1013/1-92), Temperature Detection Circuitry, IC-01 p. 14", null, null, "C816"],
  ["Sensors and Detectors", "What is a bourdon tube?", "A thin-walled, flattened tube bent into an arc. Pressure inside tends to straighten it, and the tip movement positions a pointer or develops a signal.", "DOE-1013-V1 (DOE-HDBK-1013/1-92), Pressure Detectors, IC-02 p. 2", null, {"f": "images/doe-1013-v1-ic-02-fig2.png", "alt": "Curved bourdon tube fixed at one end, with its tip linked to a pointer on a scale.", "cap": "Figure 2. Bourdon Tube. Source: DOE-1013-V1 (DOE-HDBK-1013/1-92), IC-02 p. 2.", "at": "a"}, "C817"],
  ["Sensors and Detectors", "What are the three environmental concerns for pressure instruments?", "Atmospheric pressure, ambient temperature, and humidity.", "DOE-1013-V1 (DOE-HDBK-1013/1-92), Pressure Detector Functional Uses, IC-02 p. 4", null, null, "C818"],
  ["Sensors and Detectors", "What must oppose a metallic bellows in practice?", "A spring, so the bellows' travel stays on the compression side.", "DOE-1013-V1 (DOE-HDBK-1013/1-92), Pressure Detectors, IC-02 p. 2", null, {"f": "images/doe-1013-v1-ic-02-fig1.png", "alt": "Metallic bellows with input pressure from below, moving a pointer on a scale.", "cap": "Figure 1. Basic Metallic Bellows. Source: DOE-1013-V1 (DOE-HDBK-1013/1-92), IC-02 p. 1.", "at": "a"}, "C819"],
  ["Sensors and Detectors", "What does a strain gauge measure?", "The pressure applied to a fine wire, through the resistance change caused by distortion of the wire.", "DOE-1013-V1 (DOE-HDBK-1013/1-92), Pressure Detection Circuitry, IC-02 p. 6", null, {"f": "images/doe-1013-v1-ic-02-fig3.png", "alt": "Fine wire grid strain gauge with force applied, and a flexible backing.", "cap": "Figure 3. Strain Gauge. Source: DOE-1013-V1 (DOE-HDBK-1013/1-92), IC-02 p. 7.", "at": "a"}, "C820"],
  ["Sensors and Detectors", "What three kinds of change can a pressure transducer produce?", "A change in resistance, inductance, or capacitance.", "DOE-1013-V1 (DOE-HDBK-1013/1-92), Pressure Detection Circuitry, IC-02 p. 6", null, null, "C821"],
  ["Sensors and Detectors", "What are the two groups of level measuring devices?", "Direct methods and inferred methods.", "DOE-1013-V1 (DOE-HDBK-1013/1-92), Level Detectors, IC-03 p. 1", null, null, "C822"],
  ["Sensors and Detectors", "How is differential pressure related to level with a wet reference leg?", "They are inversely proportional. Differential pressure is zero at maximum level.", "DOE-1013-V1 (DOE-HDBK-1013/1-92), Level Detectors, IC-03 p. 9", null, {"f": "images/doe-1013-v1-ic-03-fig11.png", "alt": "Closed tank with a filled reference leg to the high pressure side and the tank connection to the low pressure side.", "cap": "Figure 11. Closed Tank, Wet Reference Leg. Source: DOE-1013-V1 (DOE-HDBK-1013/1-92), IC-03 p. 9.", "at": "a"}, "C823"],
  ["Sensors and Detectors", "How is differential pressure related to level with a dry reference leg?", "Directly. Rising differential pressure means rising indicated level.", "LP-LEVEL-DETECTORS (Level Detectors.docx), slide 1.8 The most important slide of this section!!", null, null, "C824"],
  ["Sensors and Detectors", "What are the three methods of density compensation in level detection?", "Electronic circuitry, pressure detector input, and instrument calibration.", "DOE-1013-V1 (DOE-HDBK-1013/1-92), Density Compensation, IC-03 p. 13", null, null, "C825"],
  ["Sensors and Detectors", "What are the three reasons for remote level indication?", "Locations far from the main facility, a level far from the point of control, and an unsafe or radioactive area.", "DOE-1013-V1 (DOE-HDBK-1013/1-92), Level Detection Circuitry, IC-03 p. 15", null, null, "C826"],
  ["Sensors and Detectors", "How is flow related to differential pressure in a head flow meter?", "Flow rate is proportional to the square root of the differential pressure.", "DOE-1013-V1 (DOE-HDBK-1013/1-92), Flow Circuitry, IC-04 p. 18", null, null, "C827"],
  ["Sensors and Detectors", "What are the three kinds of orifice plates?", "Concentric, eccentric, and segmental.", "DOE-1013-V1 (DOE-HDBK-1013/1-92), Head Flow Meters, IC-04 p. 3", null, {"f": "images/doe-1013-v1-ic-04-fig2.png", "alt": "Three orifice plates: concentric with a center hole, eccentric with an offset hole, and segmental with a partial opening.", "cap": "Figure 2. Orifice Plates. Source: DOE-1013-V1 (DOE-HDBK-1013/1-92), IC-04 p. 3.", "at": "a"}, "C828"],
  ["Sensors and Detectors", "What are the major disadvantages of a venturi tube?", "High initial costs for installation and difficulty in installation and inspection.", "DOE-1013-V1 (DOE-HDBK-1013/1-92), Head Flow Meters, IC-04 p. 4", null, {"f": "images/doe-1013-v1-ic-04-fig3.png", "alt": "Venturi tube with a converging inlet, a cylindrical throat, and a diverging recovery cone.", "cap": "Figure 3. Venturi Tube. Source: DOE-1013-V1 (DOE-HDBK-1013/1-92), IC-04 p. 4.", "at": "a"}, "C829"],
  ["Sensors and Detectors", "What does an extractor do in a flow detection circuit?", "It electronically calculates the square root of the differential pressure, giving an output proportional to system flow.", "DOE-1013-V1 (DOE-HDBK-1013/1-92), Flow Circuitry, IC-04 p. 18", null, {"f": "images/doe-1013-v1-ic-04-fig11.png", "alt": "Block diagram running from the differential pressure transmitter through the extractor to the indicator.", "cap": "Figure 11. Differential Pressure Flow Detection Block Diagram. Source: DOE-1013-V1 (DOE-HDBK-1013/1-92), IC-04 p. 17.", "at": "a"}, "C830"],
  ["Sensors and Detectors", "How is pump differential pressure related to pump flow?", "It is proportional to the square of pump flow.", "DOE-1013-V1 (DOE-HDBK-1013/1-92), Flow Circuitry, IC-04 p. 18", null, null, "C831"],
  ["Sensors and Detectors", "What is hunting in a synchro?", "The overshoot and undershoot that occur as the receiving device tries to match the sending device.", "DOE-1013-V1 (DOE-HDBK-1013/1-92), Synchro Equipment, IC-05 p. 2", null, null, "C832"],
  ["Sensors and Detectors", "How does a limit switch indicate position?", "An extension on a valve shaft trips it, giving an ON/OFF output that corresponds to valve position.", "DOE-1013-V1 (DOE-HDBK-1013/1-92), Switches, IC-05 p. 5", null, null, "C833"],
  ["Sensors and Detectors", "How can reed switches show incremental position?", "By using a large number of magnetic reed switches along the travel.", "DOE-1013-V1 (DOE-HDBK-1013/1-92), Switches, IC-05 p. 6", null, {"f": "images/doe-1013-v1-ic-05-fig4.png", "alt": "Reed switches beside a valve stem extension carrying a permanent magnet.", "cap": "Figure 4. Reed Switches. Source: DOE-1013-V1 (DOE-HDBK-1013/1-92), IC-05 p. 6.", "at": "a"}, "C834"],
  ["Sensors and Detectors", "What happens if potentiometer resistance increases or decreases?", "Erratic indicated valve position occurs.", "DOE-1013-V1 (DOE-HDBK-1013/1-92), Variable Output Devices, IC-05 p. 8", null, {"f": "images/doe-1013-v1-ic-05-fig5.png", "alt": "Valve stem connected to a variable resistor in a circuit with an indicator.", "cap": "Figure 5. Potentiometer Valve Position Indicator. Source: DOE-1013-V1 (DOE-HDBK-1013/1-92), IC-05 p. 8.", "at": "a"}, "C835"],
  ["Sensors and Detectors", "What do control rod interlocks do?", "They prevent outward motion of certain rods unless certain conditions are met.", "DOE-1013-V1 (DOE-HDBK-1013/1-92), Position Indication Circuitry, IC-05 p. 11", null, null, "C836"],
  ["Sensors and Detectors", "What is an electron-ion pair?", "The products of a single ionizing event.", "DOE-1013-V2 (DOE-HDBK-1013/2-92), Radiation Detection Terminology, IC-06 p. 1", null, null, "C837"],
  ["Sensors and Detectors", "What are the three methods of attenuating gamma rays?", "Photoelectric effect, compton scattering, and pair production.", "DOE-1013-V2 (DOE-HDBK-1013/2-92), Radiation Types, IC-06 p. 6", null, null, "C838"],
  ["Sensors and Detectors", "What are the names of the six detector voltage regions in order?", "Recombination, ionization, proportional, limited proportional, Geiger-Müller, and continuous discharge.", "DOE-1013-V2 (DOE-HDBK-1013/2-92), Detector Voltage, IC-06 p. 16", null, null, "C839"],
  ["Sensors and Detectors", "Which detector does each nuclear instrument range use?", "Source range: proportional counter. Intermediate range: compensated ion chamber. Power range: uncompensated ion chamber.", "DOE-1013-V2 (DOE-HDBK-1013/2-92), Circuitry and Circuit Elements, IC-06 p. 57", null, null, "C840"],
  ["Sensors and Detectors", "What does overcompensating a compensated ion chamber do?", "It blocks some neutron current too, so the meter reads low.", "DOE-1013-V2 (DOE-HDBK-1013/2-92), Compensated Ion Chamber, IC-06 p. 37", null, {"f": "images/doe-1013-v2-ic-06-fig19.png", "alt": "Two chambers wired so their currents oppose each other, with a shared meter.", "cap": "Figure 19. Compensated Ion Chamber. Source: DOE-1013-V2 (DOE-HDBK-1013/2-92), IC-06 p. 35.", "at": "a"}, "C841"],
  ["Sensors and Detectors", "What is the relationship between startup rate and reactor period?", "SUR = 26.06 / τ, with SUR in decades per minute and τ in seconds.", "DOE-1013-V2 (DOE-HDBK-1013/2-92), Circuitry and Circuit Elements, IC-06 p. 61", null, null, "C842"],
  ["Controllers and Positioners", "What are the three functional elements of an automatic control system?", "A measurement element, an error detection element, and a final control element.", "DOE-1013-V2 (DOE-HDBK-1013/2-92), Principles of Control Systems, IC-07 p. 4", null, {"f": "images/doe-1013-v2-ic-07-fig4.png", "alt": "Relationship of measurement, error detection, and final control elements around a process.", "cap": "Figure 4. Relationships of Functions and Elements in an Automatic Control System. Source: DOE-1013-V2 (DOE-HDBK-1013/2-92), IC-07 p. 5.", "at": "a"}, "C843"],
  ["Controllers and Positioners", "What is an actuating signal?", "The control action of the loop, equal to the algebraic sum of the reference input and feedback signals. It is also called the error signal.", "DOE-1013-V2 (DOE-HDBK-1013/2-92), Control Loop Diagrams, IC-07 p. 10", null, {"f": "images/doe-1013-v2-ic-07-fig8.png", "alt": "Feedback control block diagram: reference input to a summing point, control elements, the plant, controlled output, and feedback elements, with a disturbance input.", "cap": "Figure 8. Feedback Control System Block Diagram. Source: DOE-1013-V2 (DOE-HDBK-1013/2-92), IC-07 p. 9.", "at": "a"}, "C844"],
  ["Controllers and Positioners", "What is proportional band?", "The change in the controlled variable that causes full travel of the final control element.", "DOE-1013-V2 (DOE-HDBK-1013/2-92), Two Position Control Systems, IC-07 p. 21", null, {"f": "images/doe-1013-v2-ic-07-fig14.png", "alt": "Plots showing valve position following controlled temperature under proportional mode.", "cap": "Figure 14. Relation Between Valve Position and Controlled Variable Under Proportional Mode. Source: DOE-1013-V2 (DOE-HDBK-1013/2-92), IC-07 p. 20.", "at": "a"}, "C845"],
  ["Controllers and Positioners", "Why can't derivative control be used alone?", "A steady-state input produces a zero output in a differentiator.", "DOE-1013-V2 (DOE-HDBK-1013/2-92), Proportional Plus Rate Control Systems, IC-07 p. 38", null, null, "C846"],
  ["Controllers and Positioners", "What does each PID action do?", "Proportional responds to error amplitude, integral eliminates offset, and derivative adds stability.", "DOE-1013-V2 (DOE-HDBK-1013/2-92), PID Control Systems, IC-07 p. 46", null, {"f": "images/doe-1013-v2-ic-07-fig30.png", "alt": "Curves of the proportional, reset, and rate actions and their combined output for a slowly increasing error.", "cap": "Figure 30. PID Control Action Responses. Source: DOE-1013-V2 (DOE-HDBK-1013/2-92), IC-07 p. 44.", "at": "a"}, "C847"],
  ["Controllers and Positioners", "What does a positioner do?", "It regulates the supply air pressure to a pneumatic actuator by comparing demanded position with actual position.", "DOE-1013-V2 (DOE-HDBK-1013/2-92), Valve Actuators, IC-07 p. 55", null, {"f": "images/doe-1013-v2-ic-07-fig36.png", "alt": "Pneumatic actuator with a controller and a positioner connected by a feedback linkage.", "cap": "Figure 36. Pneumatic Actuator with Controller and Positioner. Source: DOE-1013-V2 (DOE-HDBK-1013/2-92), IC-07 p. 56.", "at": "a"}, "C848"],
  ["Controllers and Positioners", "What does fail-open mean on a pneumatic actuator?", "On a loss of supply air, the spring opens the valve. It is also called air-to-close, spring-to-open.", "DOE-1013-V2 (DOE-HDBK-1013/2-92), Valve Actuators, IC-07 p. 56", null, {"f": "images/doe-1013-v2-ic-07-fig35.png", "alt": "Pneumatic actuator: supply air above a rubber diaphragm, a spring below, and a stem to the control valve.", "cap": "Figure 35. Pneumatic Actuator: Air-to-Close/Spring-to-Open. Source: DOE-1013-V2 (DOE-HDBK-1013/2-92), IC-07 p. 54.", "at": "a"}, "C849"],
  ["Demineralizers and Ion Exchangers", "How do metals and nonmetals differ in forming ions?", "Metals tend to lose electrons to form positive ions. Nonmetals tend to gain electrons to form negative ions.", "DOE-1015-V1 (DOE-HDBK-1015/1-93), The Periodic Table, CH-01 p. 17", null, null, "C850"],
  ["Demineralizers and Ion Exchangers", "What are the three basic laws of chemical reactions?", "Conservation of Mass, Definite Proportions, and Multiple Proportions.", "DOE-1015-V1 (DOE-HDBK-1015/1-93), Chemical Bonding, CH-01 p. 32", null, null, "C851"],
  ["Demineralizers and Ion Exchangers", "What is normality?", "The number of equivalents of solute dissolved in one liter of solution.", "DOE-1015-V1 (DOE-HDBK-1015/1-93), Chemical Equations, CH-01 p. 38", null, null, "C852"],
  ["Demineralizers and Ion Exchangers", "How is a metallic bond formed?", "An atom shares the electrons in its outer shell with many other atoms.", "DOE-1015-V1 (DOE-HDBK-1015/1-93), Chemical Bonding, CH-01 p. 27", null, null, "C853"],
  ["Demineralizers and Ion Exchangers", "What is an alkali?", "A soluble salt, principally of sodium, potassium, magnesium, or calcium, that combines with acids to form neutral salts.", "DOE-1015-V1 (DOE-HDBK-1015/1-93), Acids, Bases, Salts, and pH, CH-01 p. 48", null, null, "C854"],
  ["Demineralizers and Ion Exchangers", "What is passivity?", "The characteristic of a metal that does not become active in the corrosion reaction, caused by a stable oxide layer.", "DOE-1015-V1 (DOE-HDBK-1015/1-93), Corrosion Theory, CH-02 p. 6", null, null, "C855"],
  ["Demineralizers and Ion Exchangers", "What is polarization?", "The decrease in cell potential caused by the operation of an electrochemical cell.", "DOE-1015-V1 (DOE-HDBK-1015/1-93), Corrosion Theory, CH-02 p. 7", null, null, "C856"],
  ["Demineralizers and Ion Exchangers", "What are the four methods used to chemically control general corrosion?", "Passivators and inhibitors, cathodic protection, removing corrosive agents, and chemical addition.", "DOE-1015-V1 (DOE-HDBK-1015/1-93), General Corrosion, CH-02 p. 16", null, null, "C857"],
  ["Demineralizers and Ion Exchangers", "What are the two locations susceptible to galvanic corrosion?", "A piping transition between two metals and a sacrificial anode.", "DOE-1015-V1 (DOE-HDBK-1015/1-93), Crud and Galvanic Corrosion, CH-02 p. 23", null, null, "C858"],
  ["Demineralizers and Ion Exchangers", "What is the minimum caustic concentration for caustic stress cracking?", "Greater than 10,000 ppm.", "DOE-1015-V1 (DOE-HDBK-1015/1-93), Specialized Corrosion, CH-02 p. 35", null, null, "C859"],
  ["Demineralizers and Ion Exchangers", "What are the nine reactor water chemistry parameters?", "pH, dissolved oxygen, hydrogen, total gas content, conductivity, chlorides, fluorine, boron, and radioactivity.", "DOE-1015-V2 (DOE-HDBK-1015/2-93), Chemistry Parameters, CH-03 p. 12", null, null, "C860"],
  ["Demineralizers and Ion Exchangers", "What is the effect of adding excess hydrogen to reactor water?", "It forces the equilibrium toward water, so oxygen is consumed.", "DOE-1015-V2 (DOE-HDBK-1015/2-93), Effects of Radiation on Water Chemistry (Synthesis), CH-03 p. 6", null, null, "C861"],
  ["Demineralizers and Ion Exchangers", "Why is dissolved oxygen controlled in reactor water?", "Because of its contribution to increased corrosion.", "DOE-1015-V2 (DOE-HDBK-1015/2-93), Chemistry Parameters, CH-03 p. 15", null, null, "C862"],
  ["Demineralizers and Ion Exchangers", "What does a fuel element failure do to the coolant?", "It gives large amounts of fission products a path to the coolant system.", "DOE-1015-V2 (DOE-HDBK-1015/2-93), Chemistry Parameters, CH-03 p. 28", null, null, "C863"],
  ["Demineralizers and Ion Exchangers", "What are the three reasons for using very pure water in a reactor facility?", "To minimize corrosion, radiation levels, and fouling of heat transfer surfaces.", "DOE-1015-V2 (DOE-HDBK-1015/2-93), Purpose of Water Treatment, CH-04 p. 1", null, null, "C864"],
  ["Demineralizers and Ion Exchangers", "What is a decontamination factor?", "The ratio of concentration or activity at the inlet to that at the effluent of an ion exchanger.", "DOE-1015-V2 (DOE-HDBK-1015/2-93), Water Treatment Processes, CH-04 p. 10", null, null, "C865"],
  ["Demineralizers and Ion Exchangers", "What is the difference between breakthrough and exhaustion?", "Breakthrough is when small amounts of impurity first appear in the effluent. Exhaustion is when essentially all exchange capacity has been used.", "DOE-1015-V2 (DOE-HDBK-1015/2-93), Dissolved Gases, Suspended Solids, and pH Control, CH-04 p. 24", null, null, "C866"],
  ["Demineralizers and Ion Exchangers", "What are the three basic methods of removing dissolved gases from water?", "Aeration, deaeration, and adding scavengers.", "DOE-1015-V2 (DOE-HDBK-1015/2-93), Dissolved Gases, Suspended Solids, and pH Control, CH-04 p. 17", null, null, "C867"],
  ["Demineralizers and Ion Exchangers", "How efficient is a resin bed as a filter?", "90% or less, compared with approximately 100% for most ion exchange.", "DOE-1015-V2 (DOE-HDBK-1015/2-93), Dissolved Gases, Suspended Solids, and pH Control, CH-04 p. 21", null, null, "C868"],
  ["Demineralizers and Ion Exchangers", "How long should eyes be irrigated after contact with a corrosive?", "With water for at least 15 minutes, and a physician should be consulted immediately.", "DOE-1015-V2 (DOE-HDBK-1015/2-93), Corrosives (Acids and Alkalies), CH-05 p. 1", null, null, "C869"],
  ["Demineralizers and Ion Exchangers", "How do acute and chronic poisoning differ?", "Acute is rapid absorption from sudden, severe exposure. Chronic is absorption of small doses over a long period of time.", "DOE-1015-V2 (DOE-HDBK-1015/2-93), Toxic Compounds, CH-05 p. 10", null, null, "C870"],
  ["Demineralizers and Ion Exchangers", "What does oxygen do to combustion?", "It does not burn, but it lowers the ignition point of flammable substances and greatly accelerates combustion.", "DOE-1015-V2 (DOE-HDBK-1015/2-93), Compressed Gases, CH-05 p. 19", null, null, "C871"],
  ["Demineralizers and Ion Exchangers", "How much do cryogenic liquids expand on vaporizing?", "They produce large volumes of gas. One volume of liquid nitrogen vaporizes to 696.5 volumes of gas at room temperature.", "DOE-1015-V2 (DOE-HDBK-1015/2-93), Compressed Gases, CH-05 p. 20", null, null, "C872"],
  ["Demineralizers and Ion Exchangers", "What is flash point?", "The minimum temperature at which a liquid gives off vapor in sufficient concentration to form an ignitible mixture with air near its surface.", "DOE-1015-V2 (DOE-HDBK-1015/2-93), Flammable and Combustible Liquids, CH-05 p. 31", null, null, "C873"],
  ["Demineralizers and Ion Exchangers", "What does a lead-acid battery produce while being charged?", "Hydrogen.", "DOE-1015-V2 (DOE-HDBK-1015/2-93), Compressed Gases, CH-05 p. 25", null, null, "C874"],
  ["Valves", "What five parts make up a generic engineering drawing?", "The title block, grid system, revision block, notes and legends, and the engineering drawing (graphic portion).", "DOE-1016-V1 (DOE-HDBK-1016/1-93), Introduction to Print Reading, PR-01 p. 2", null, null, "C875"],
  ["Valves", "What three things does a revision block entry provide?", "The revision number, a title or summary of the revision, and the date of the revision.", "DOE-1016-V1 (DOE-HDBK-1016/1-93), Introduction to Print Reading, PR-01 p. 6", null, {"f": "images/doe-1016-v1-pr-01-fig3.png", "alt": "Drawing sheet with the revision block ruled across the top of the sheet.", "cap": "Figure 3. Revision Block. Source: DOE-1016-V1 (DOE-HDBK-1016/1-93), PR-01 p. 6.", "at": "a"}, "C876"],
  ["Valves", "What are the five categories of engineering drawings?", "P&IDs, electrical single lines and schematics, electronic diagrams and schematics, logic diagrams and prints, and fabrication, construction, and architectural drawings.", "DOE-1016-V1 (DOE-HDBK-1016/1-93), Introduction to the Types of Drawings, Views, and Perspectives, PR-01 p. 10", null, null, "C877"],
  ["Valves", "What is the difference between the cloud method and the revision circle method?", "The cloud method shows changes from the most recent revision only. Revision circles stay on the drawing and show all revisions.", "DOE-1016-V1 (DOE-HDBK-1016/1-93), Introduction to Print Reading, PR-01 p. 7", null, {"f": "images/doe-1016-v1-pr-01-fig4.png", "alt": "Drawing with a change enclosed by a cloud shape and a triangle holding a revision number next to another change.", "cap": "Figure 4. Methods of Denoting Changes. Source: DOE-1016-V1 (DOE-HDBK-1016/1-93), PR-01 p. 7.", "at": "a"}, "C878"],
  ["Valves", "What do P&IDs present about the location of equipment?", "Only the relationship or sequence between components, not the actual physical relationships.", "DOE-1016-V1 (DOE-HDBK-1016/1-93), Introduction to the Types of Drawings, Views, and Perspectives, PR-01 p. 11", null, null, "C879"],
  ["Valves", "What are the three standard drawing formats?", "Single line, pictorial or double line, and cutaway.", "DOE-1016-V1 (DOE-HDBK-1016/1-93), Introduction to the Types of Drawings, Views, and Perspectives, PR-01 p. 16", null, null, "C880"],
  ["Valves", "What does the first letter of a control valve designator show?", "The parameter to be controlled by the valve: F flow, T temperature, L level, P pressure, or H hand.", "DOE-1016-V1 (DOE-HDBK-1016/1-93), Engineering Fluids Diagrams and Prints, PR-02 p. 6", null, {"f": "images/doe-1016-v1-pr-02-fig6.png", "alt": "Valves with balloons: FCV for flow, TCV for temperature, LCV for level, and PCV for pressure control valve.", "cap": "Figure 6. Control Valve Designations. Source: DOE-1016-V1 (DOE-HDBK-1016/1-93), PR-02 p. 6.", "at": "a"}, "C881"],
  ["Valves", "What may be assumed if no actuator is shown on a valve symbol?", "The valve is equipped only with a handwheel for manual operation.", "DOE-1016-V1 (DOE-HDBK-1016/1-93), Engineering Fluids Diagrams and Prints, PR-02 p. 4", null, {"f": "images/doe-1016-v1-pr-02-fig2.png", "alt": "Valve actuator symbols on a valve body: a dome for diaphragm, a box with M for electric motor, a box with S for solenoid, a box with H or a split box for piston, an angled line for reach rod, and a T for manual.", "cap": "Figure 2. Valve Actuator Symbols. Source: DOE-1016-V1 (DOE-HDBK-1016/1-93), PR-02 p. 4.", "at": "a"}, "C882"],
  ["Valves", "How does a P&ID show where an instrument is mounted?", "A plain circle is locally mounted, a solid line across the circle is board mounted, and a dashed line is behind the board.", "DOE-1016-V1 (DOE-HDBK-1016/1-93), Engineering Fluids Diagrams and Prints, PR-02 p. 11", null, {"f": "images/doe-1016-v1-pr-02-fig10.png", "alt": "Instrument location symbols: a plain circle for locally mounted, a circle with a solid line across it for board mounted, and a circle with a dashed line for behind the board. Examples of modifiers and transmitters follow.", "cap": "Figure 10. Transmitters and Instruments. Source: DOE-1016-V1 (DOE-HDBK-1016/1-93), PR-02 p. 11.", "at": "a"}, "C883"],
  ["Valves", "How does a fluid power drawing tell a pump from a motor?", "The point of the arrow touches the circle in a pump. The tail of the arrow touches the circle in a motor.", "DOE-1016-V1 (DOE-HDBK-1016/1-93), Fluid Power P&IDs, PR-02 p. 25", null, null, "C884"],
  ["Valves", "How does a fluid power drawing tell a hydraulic pump from a compressor?", "Hydraulic pumps have solid arrow heads. Pneumatic compressors have hollow arrow heads.", "DOE-1016-V1 (DOE-HDBK-1016/1-93), Fluid Power P&IDs, PR-02 p. 23", null, {"f": "images/doe-1016-v1-pr-02-fig19.png", "alt": "Circles with arrowheads touching the rim: a fixed displacement pump with a solid arrowhead, a variable displacement pump with a diagonal arrow through the circle, and a compressor with a hollow arrowhead.", "cap": "Figure 19. Fluid Power Pump and Compressor Symbols. Source: DOE-1016-V1 (DOE-HDBK-1016/1-93), PR-02 p. 23.", "at": "a"}, "C885"],
  ["Valves", "How are safety systems normally shown on a P&ID?", "In their standby or non-accident condition.", "DOE-1016-V1 (DOE-HDBK-1016/1-93), Reading Engineering P&IDs, PR-02 p. 16", null, null, "C886"],
  ["Valves", "In what position are solenoid-operated fluid power valves drawn?", "The de-energized position.", "DOE-1016-V1 (DOE-HDBK-1016/1-93), Fluid Power P&IDs, PR-02 p. 27", null, null, "C887"],
  ["Valves", "What are the three types of fluid power diagrams?", "Pictorial, cutaway, and schematic.", "DOE-1016-V1 (DOE-HDBK-1016/1-93), Fluid Power P&IDs, PR-02 p. 34", null, {"f": "images/doe-1016-v1-pr-02-fig31.png", "alt": "The same system as a cutaway diagram, with the internal parts of each component visible.", "cap": "Figure 31. Cutaway Fluid Power Diagram. Source: DOE-1016-V1 (DOE-HDBK-1016/1-93), PR-02 p. 34.", "at": "a"}, "C888"],
  ["Breakers, Relays, and Disconnects", "What does pole mean for a switch?", "The number of points at which current can enter a switch.", "DOE-1016-V1 (DOE-HDBK-1016/1-93), Electrical Diagrams and Schematics, PR-03 p. 3", null, null, "C889"],
  ["Breakers, Relays, and Disconnects", "What does throw mean for a switch?", "The number of circuits that each pole of a switch can complete or control.", "DOE-1016-V1 (DOE-HDBK-1016/1-93), Electrical Diagrams and Schematics, PR-03 p. 3", null, {"f": "images/doe-1016-v1-pr-03-fig3.png", "alt": "Typical switches with symbols for single pole and double pole, single throw and double throw switches, and normally open, normally closed, two-position, and multi-position pushbutton switches.", "cap": "Figure 3. Switches and Switch Symbols. Source: DOE-1016-V1 (DOE-HDBK-1016/1-93), PR-03 p. 3.", "at": "a"}, "C890"],
  ["Breakers, Relays, and Disconnects", "What do chevrons on a breaker symbol show?", "The point at which the breaker disconnects from the circuit when removed. The breaker is removable.", "DOE-1016-V1 (DOE-HDBK-1016/1-93), Electrical Diagrams and Schematics, PR-03 p. 6", null, {"f": "images/doe-1016-v1-pr-03-fig6.png", "alt": "A three-phase breaker drawn as three single-phase breaker symbols, and a removable breaker with chevrons on each side.", "cap": "Figure 6. Three-phase and Removable Breaker Symbols. Source: DOE-1016-V1 (DOE-HDBK-1016/1-93), PR-03 p. 6.", "at": "a"}, "C891"],
  ["Breakers, Relays, and Disconnects", "How do you match a relay to its contacts on a schematic?", "The number/letter code for each relay is carried by all associated contacts.", "DOE-1016-V1 (DOE-HDBK-1016/1-93), Electrical Diagrams and Schematics, PR-03 p. 14", null, {"f": "images/doe-1016-v1-pr-03-fig14.png", "alt": "Figure A: motor start circuit with relay coil M1 and holding contacts marked M1. Figure B: a relay and contact joined by a dashed line or a dashed box. Figure C: a switch and a second set of contacts joined by a dashed line.", "cap": "Figure 14. Examples of Relays and Relay Contacts. Source: DOE-1016-V1 (DOE-HDBK-1016/1-93), PR-03 p. 14.", "at": "a"}, "C892"],
  ["Breakers, Relays, and Disconnects", "What are ganged switches?", "Switches where the position of one affects another, shown by connecting them with a dashed line.", "DOE-1016-V1 (DOE-HDBK-1016/1-93), Electrical Diagrams and Schematics, PR-03 p. 15", null, {"f": "images/doe-1016-v1-pr-03-fig15.png", "alt": "Figure A: ganged breaker and switches joined by a dashed line. Figure B: two breakers joined by a dashed mechanical interlock line.", "cap": "Figure 15. Ganged Switch Symbology. Source: DOE-1016-V1 (DOE-HDBK-1016/1-93), PR-03 p. 15.", "at": "a"}, "C893"],
  ["Breakers, Relays, and Disconnects", "What are the common units for loads on a power distribution single line?", "Kilowatts (kW), unless otherwise stated.", "DOE-1016-V1 (DOE-HDBK-1016/1-93), Electrical Diagrams and Schematics, PR-03 p. 12", null, null, "C894"],
  ["Controllers and Positioners", "What are the two basic categories of electronic prints?", "Electronic schematics and block diagrams.", "DOE-1016-V2 (DOE-HDBK-1016/2-93), Electronic Diagrams, Prints, and Schematics, PR-04 p. 1", null, null, "C895"],
  ["Controllers and Positioners", "In what condition do electronic prints show relays and contacts?", "Always in the de-energized condition.", "DOE-1016-V2 (DOE-HDBK-1016/2-93), Electronic Diagrams, Prints, and Schematics, PR-04 p. 7", null, null, "C896"],
  ["Controllers and Positioners", "What is the first thing to look for on a detailed electronic schematic?", "The source and polarity of power.", "DOE-1016-V2 (DOE-HDBK-1016/2-93), Electronic Diagrams, Prints, and Schematics, PR-04 p. 7", null, null, "C897"],
  ["Controllers and Positioners", "What voltage type can be assumed on an electronic schematic unless stated otherwise?", "Direct Current (DC).", "DOE-1016-V2 (DOE-HDBK-1016/2-93), Electronic Diagrams, Prints, and Schematics, PR-04 p. 7", null, null, "C898"],
  ["Controllers and Positioners", "Which way does current flow through a transistor, using conventional current flow?", "From most positive to least positive, in the direction of the arrow on the emitter.", "DOE-1016-V2 (DOE-HDBK-1016/2-93), Electronic Diagrams, Prints, and Schematics, PR-04 p. 9", null, {"f": "images/doe-1016-v2-pr-04-fig7.png", "alt": "NPN transistor with positive supply, ground on the emitter, and a positive input, with current flowing in the direction of the arrow.", "cap": "Figure 7. NPN Transistor-Conducting. Source: DOE-1016-V2 (DOE-HDBK-1016/2-93), PR-04 p. 9.", "at": "a"}, "C899"],
  ["Controllers and Positioners", "How does a diode differ from a transistor?", "A diode has only one junction and conducts in only one direction.", "DOE-1016-V2 (DOE-HDBK-1016/2-93), Electronic Diagrams, Prints, and Schematics, PR-04 p. 10", null, null, "C900"],
  ["Controllers and Positioners", "What are the three basic types of logic gates?", "AND, OR, and NOT gates.", "DOE-1016-V2 (DOE-HDBK-1016/2-93), Engineering Logic Diagrams, PR-05 p. 4", null, null, "C901"],
  ["Controllers and Positioners", "When does an AND gate provide an output?", "When all its inputs are on.", "DOE-1016-V2 (DOE-HDBK-1016/2-93), Engineering Logic Diagrams, PR-05 p. 4", null, null, "C902"],
  ["Controllers and Positioners", "When is an OR gate off?", "Only when all of its inputs are off.", "DOE-1016-V2 (DOE-HDBK-1016/2-93), Engineering Logic Diagrams, PR-05 p. 4", null, null, "C903"],
  ["Controllers and Positioners", "When does a NAND gate provide an output?", "Except when all the inputs are on.", "DOE-1016-V2 (DOE-HDBK-1016/2-93), Engineering Logic Diagrams, PR-05 p. 4", null, null, "C904"],
  ["Controllers and Positioners", "What does the fraction in a COINCIDENCE gate symbol mean?", "The numerator is the number of inputs that must be on. The denominator is the total number of inputs.", "DOE-1016-V2 (DOE-HDBK-1016/2-93), Engineering Logic Diagrams, PR-05 p. 6", null, {"f": "images/doe-1016-v2-pr-05-fig5.png", "alt": "COINCIDENCE gates: AND gate symbols holding the fractions 2/4 and 2/3, for 2 of 4 and 2 of 3 functions.", "cap": "Figure 5. COINCIDENCE Gate. Source: DOE-1016-V2 (DOE-HDBK-1016/2-93), PR-05 p. 6.", "at": "a"}, "C905"],
  ["Controllers and Positioners", "When does an EXCLUSIVE OR gate provide an output?", "When only one of the inputs is on.", "DOE-1016-V2 (DOE-HDBK-1016/2-93), Engineering Logic Diagrams, PR-05 p. 6", null, {"f": "images/doe-1016-v2-pr-05-fig6.png", "alt": "EXCLUSIVE NOR and EXCLUSIVE OR symbols in several conventions, each with an added curved line at the back of the gate.", "cap": "Figure 6. EXCLUSIVE OR and EXCLUSIVE NOR Gates. Source: DOE-1016-V2 (DOE-HDBK-1016/2-93), PR-05 p. 6.", "at": "a"}, "C906"],
  ["Controllers and Positioners", "What does a Type-Two Time Delay Device do?", "It gives an output at once on the input, and holds it for a specified time after the input is removed.", "DOE-1016-V2 (DOE-HDBK-1016/2-93), Engineering Logic Diagrams, PR-05 p. 7", null, null, "C907"],
  ["Controllers and Positioners", "How many rows does a truth table need?", "Every combination of input signal: 2 raised to the power n, where n is the number of inputs.", "DOE-1016-V2 (DOE-HDBK-1016/2-93), Truth Tables and Exercises, PR-05 p. 11", null, null, "C908"],
  ["Brittle Fracture and Vessel Thermal Stress", "What are the five types of bonding in materials?", "Ionic, covalent, metallic, molecular, and hydrogen.", "DOE-1017-V1 (DOE-HDBK-1017/1-93), Bonding, MS-01 p. 1", null, {"f": "images/doe-1017-v1-ms-01-fig1.png", "alt": "Atoms arranged to show ionic bonding in sodium chloride, covalent in diamond, metallic in sodium, molecular in solid hydrogen, and hydrogen bonding in ice.", "cap": "Figure 1. Bonding Types. Source: DOE-1017-V1 (DOE-HDBK-1017/1-93), MS-01 p. 3.", "at": "a"}, "C909"],
  ["Brittle Fracture and Vessel Thermal Stress", "What is a crystal structure?", "Atoms arranged in a pattern that repeats periodically in a three-dimensional geometric lattice.", "DOE-1017-V1 (DOE-HDBK-1017/1-93), Common Lattice Types, MS-01 p. 6", null, null, "C910"],
  ["Brittle Fracture and Vessel Thermal Stress", "Which common lattice type gives high strength and low ductility?", "Body-centered cubic (BCC).", "DOE-1017-V1 (DOE-HDBK-1017/1-93), Common Lattice Types, MS-01 p. 8", null, {"f": "images/doe-1017-v1-ms-01-fig2.png", "alt": "Unit cells of body-centered cubic, face-centered cubic, and hexagonal close-packed lattices, with dots marking atoms.", "cap": "Figure 2. Common Lattice Types. Source: DOE-1017-V1 (DOE-HDBK-1017/1-93), MS-01 p. 7.", "at": "a"}, "C911"],
  ["Brittle Fracture and Vessel Thermal Stress", "What are the three phases of uranium metal?", "Alpha, room temperature to 663°C. Beta, 663°C to 764°C. Gamma, 764°C to 1133°C.", "DOE-1017-V1 (DOE-HDBK-1017/1-93), Polymorphism, MS-01 p. 14", null, {"f": "images/doe-1017-v1-ms-01-fig5.png", "alt": "Cooling curve for unalloyed uranium: temperature falls with steps at 1133°C for freezing, 764°C, and 663°C, showing the gamma, beta, and alpha phases.", "cap": "Figure 5. Cooling Curve for Unalloyed Uranium. Source: DOE-1017-V1 (DOE-HDBK-1017/1-93), MS-01 p. 12.", "at": "a"}, "C912"],
  ["Brittle Fracture and Vessel Thermal Stress", "Why is pure uranium not used as a fuel?", "Heating and cooling alpha phase uranium can cause drastic dimensional changes and gross distortions.", "DOE-1017-V1 (DOE-HDBK-1017/1-93), Polymorphism, MS-01 p. 13", null, {"f": "images/doe-1017-v1-ms-01-fig6.png", "alt": "Alpha uranium unit cell growing along two axes and shrinking along a third when heated from 0 to 300°C.", "cap": "Figure 6. Change in Alpha Uranium Upon Heating From 0 to 300°C. Source: DOE-1017-V1 (DOE-HDBK-1017/1-93), MS-01 p. 13.", "at": "a"}, "C913"],
  ["Brittle Fracture and Vessel Thermal Stress", "What are the three possible alloy microstructures?", "Solid solutions, a crystal with a metallic compound at each lattice point, and composites.", "DOE-1017-V1 (DOE-HDBK-1017/1-93), Alloys, MS-01 p. 15", null, null, "C914"],
  ["Brittle Fracture and Vessel Thermal Stress", "What are the four types of bulk defects?", "Inclusions, gas pockets, shrinking cavities, and welding or joining defects.", "DOE-1017-V1 (DOE-HDBK-1017/1-93), Imperfections in Metals, MS-01 p. 21", null, null, "C915"],
  ["Brittle Fracture and Vessel Thermal Stress", "What is the formula for stress?", "Stress equals force divided by cross-sectional area: σ = F/A.", "DOE-1017-V1 (DOE-HDBK-1017/1-93), Stress, MS-02 p. 6", null, null, "C916"],
  ["Brittle Fracture and Vessel Thermal Stress", "What are the six categories of stress?", "Residual, structural, pressure, flow, thermal, and fatigue stresses.", "DOE-1017-V1 (DOE-HDBK-1017/1-93), Stress, MS-02 p. 2", null, null, "C917"],
  ["Brittle Fracture and Vessel Thermal Stress", "What is elastic strain?", "A transitory dimensional change that exists only while the initiating stress is applied.", "DOE-1017-V1 (DOE-HDBK-1017/1-93), Strain, MS-02 p. 8", null, null, "C918"],
  ["Brittle Fracture and Vessel Thermal Stress", "What is Young's Modulus?", "The ratio of stress to strain, or the gradient of the stress-strain graph.", "DOE-1017-V1 (DOE-HDBK-1017/1-93), Young's Modulus, MS-02 p. 14", null, null, "C919"],
  ["Brittle Fracture and Vessel Thermal Stress", "What is ductility?", "The ability of a material to deform easily upon the application of a tensile force, or to withstand plastic deformation without rupture.", "DOE-1017-V1 (DOE-HDBK-1017/1-93), Physical Properties, MS-02 p. 28", null, null, "C920"],
  ["Brittle Fracture and Vessel Thermal Stress", "What is toughness?", "How a material reacts under sudden impacts, defined as the work required to deform one cubic inch of metal until it fractures.", "DOE-1017-V1 (DOE-HDBK-1017/1-93), Physical Properties, MS-02 p. 28", null, null, "C921"],
  ["Brittle Fracture and Vessel Thermal Stress", "What is hydrogen embrittlement of steel?", "Loss of ductility and strength from tiny cracks caused by the internal pressure of hydrogen or methane gas at the grain boundaries.", "DOE-1017-V1 (DOE-HDBK-1017/1-93), Hydrogen Embrittlement, MS-02 p. 37", null, {"f": "images/doe-1017-v1-ms-02-fig10.png", "alt": "Hydrogen from a corrosive solution enters the metal, forms CH4 at grain boundaries, and opens a crack.", "cap": "Figure 10. Hydrogen Embrittlement. Source: DOE-1017-V1 (DOE-HDBK-1017/1-93), MS-02 p. 38.", "at": "a"}, "C922"],
  ["Brittle Fracture and Vessel Thermal Stress", "What are the two causes of thermal shock?", "Nonuniform heating or cooling of a uniform material, and uniform heating or cooling of a nonuniform material.", "DOE-1017-V2 (DOE-HDBK-1017/2-93), Thermal Stress, MS-03 p. 1", null, null, "C923"],
  ["Brittle Fracture and Vessel Thermal Stress", "What is the equation for thermal stress in a constrained material?", "F/A = EαΔT.", "DOE-1017-V2 (DOE-HDBK-1017/2-93), Thermal Stress, MS-03 p. 3", null, null, "C924"],
  ["Brittle Fracture and Vessel Thermal Stress", "When is a vessel usually considered thick-walled?", "When its wall thickness is more than 5 percent to 10 percent of its radius.", "DOE-1017-V2 (DOE-HDBK-1017/2-93), Thermal Stress, MS-03 p. 4", null, null, "C925"],
  ["Brittle Fracture and Vessel Thermal Stress", "What plant transients have the greatest potential to cause thermal shock?", "Excessive heatup and cooldown, plant scrams, pressure excursions outside normal bands, and loss of coolant accidents.", "DOE-1017-V2 (DOE-HDBK-1017/2-93), Pressurized Thermal Shock, MS-03 p. 8", null, null, "C926"],
  ["Brittle Fracture and Vessel Thermal Stress", "What is ductile fracture?", "Fracture of a metal that can sustain substantial plastic strain or deformation before fracturing.", "DOE-1017-V2 (DOE-HDBK-1017/2-93), Brittle Fracture Mechanism, MS-04 p. 6", null, null, "C927"],
  ["Brittle Fracture and Vessel Thermal Stress", "What three conditions tend to mitigate crack initiation?", "Smaller grain size, higher temperature, and lower stress.", "DOE-1017-V2 (DOE-HDBK-1017/2-93), Brittle Fracture Mechanism, MS-04 p. 4", null, {"f": "images/doe-1017-v2-ms-04-fig2.png", "alt": "Stress against temperature: tensile strength curve A, yield strength curve B, tensile strength with flaw curve C, and crack arrest curve D. NDT with no flaw is at 10°F, NDT with a small flaw at 60°F, FTE at 70°F, and FTP where curves A and D meet.", "cap": "Figure 2. Stress-Temperature Diagram for Crack Initiation and Arrest. Source: DOE-1017-V2 (DOE-HDBK-1017/2-93), MS-04 p. 3.", "at": "a"}, "C928"],
  ["Brittle Fracture and Vessel Thermal Stress", "What five factors determine the fracture toughness of a metal?", "Metal composition, metal temperature, extent of deformations to the crystal structure, metal grain size, and metal crystalline form.", "DOE-1017-V2 (DOE-HDBK-1017/2-93), Brittle Fracture Mechanism, MS-04 p. 4", null, null, "C929"],
  ["Brittle Fracture and Vessel Thermal Stress", "How far above NDT are the FTE and FTP temperatures?", "FTE is normally about 60°F above NDT, and FTP about 120°F above NDT.", "DOE-1017-V2 (DOE-HDBK-1017/2-93), Brittle Fracture Mechanism, MS-04 p. 4", null, null, "C930"],
  ["Brittle Fracture and Vessel Thermal Stress", "Where is the safe operating region on an MPT curve?", "To the right of the curve.", "DOE-1017-V2 (DOE-HDBK-1017/2-93), Minimum Pressurization-Temperature Curves, MS-04 p. 7", null, null, "C931"],
  ["Brittle Fracture and Vessel Thermal Stress", "Why are soak times used?", "So heating can be carefully controlled, which minimizes thermal stresses.", "DOE-1017-V2 (DOE-HDBK-1017/2-93), Heatup and Cooldown Rate Limits, MS-04 p. 12", null, null, "C932"],
  ["Valves", "What are the two ways dimensions can be expressed on a drawing?", "Drafted to scale and measured from the drawing, or with the actual dimensions specified. The second is preferred.", "DOE-1016-V2 (DOE-HDBK-1016/2-93), Engineering Fabrication, Construction, and Architectural Drawings, PR-06 p. 5", null, null, "C933"],
  ["Valves", "What are the three methods of stating a tolerance on a drawing?", "An implied standard, a global tolerance in the title block or a note, or a tolerance stated with a specific dimension.", "DOE-1016-V2 (DOE-HDBK-1016/2-93), Engineering Fabrication, Construction, and Architectural Drawings, PR-06 p. 8", null, null, "C934"],
  ["Valves", "What are geometric tolerances?", "The maximum allowable variation of a form or its position from the perfect geometry implied on the drawing.", "DOE-1016-V2 (DOE-HDBK-1016/2-93), Engineering Fabrication, Construction, and Architectural Drawings, PR-06 p. 8", null, null, "C935"],
  ["Valves", "Why is one dimension often left off a toleranced drawing?", "The unspecified dimension absorbs the errors in the critical dimensions.", "DOE-1016-V2 (DOE-HDBK-1016/2-93), Engineering Fabrication, Construction, and Architectural Drawings, PR-06 p. 11", null, null, "C936"],
  ["Motors and Generators", "What is the compression ratio formula for a diesel engine?", "(Displacement volume + clearance volume) / clearance volume.", "DOE-1018-V1 (DOE-HDBK-1018/1-93), Diesel Engines, ME-01 p. 18", null, {"f": "images/doe-1018-v1-me-01-fig15.png", "alt": "Two piston and cylinder sketches, with the piston at bottom and at top of its travel, showing 16 units of volume compressed to 1 unit.", "cap": "Figure 15. Compression Ratio. Source: DOE-1018-V1 (DOE-HDBK-1018/1-93), ME-01 p. 18.", "at": "a"}, "C937"],
  ["Motors and Generators", "What are the bore and stroke of an engine?", "Bore is the diameter of the cylinder. Stroke is the distance the piston travels from the top of the cylinder to the bottom.", "DOE-1018-V1 (DOE-HDBK-1018/1-93), Diesel Engines, ME-01 p. 17", null, null, "C938"],
  ["Motors and Generators", "What five supporting systems does a diesel engine require?", "Cooling, lubrication, fuel injection, air intake, and exhaust.", "DOE-1018-V1 (DOE-HDBK-1018/1-93), Diesel Engines, ME-01 p. 12", null, null, "C939"],
  ["Motors and Generators", "How many crankshaft rotations does a two-stroke diesel take per cycle?", "One rotation, or 360°.", "DOE-1018-V1 (DOE-HDBK-1018/1-93), Fundamentals of the Diesel Cycle, ME-01 p. 25", null, null, "C940"],
  ["Motors and Generators", "What is valve overlap in a diesel engine?", "The time both the intake and exhaust valves are open, which lets fresh air scavenge exhaust gasses and cool the cylinder.", "DOE-1018-V1 (DOE-HDBK-1018/1-93), Fundamentals of the Diesel Cycle, ME-01 p. 23", null, {"f": "images/doe-1018-v1-me-01-fig16.png", "alt": "Cylinder sketch with both valves open while fresh air enters and scavenges the exhaust.", "cap": "Figure 16. Scavenging and Intake. Source: DOE-1018-V1 (DOE-HDBK-1018/1-93), ME-01 p. 22.", "at": "a"}, "C941"],
  ["Motors and Generators", "Why does a diesel engine need a governor?", "It is not self-speed-limiting, because the air entering is always the maximum amount. Speed depends only on the fuel injected.", "DOE-1018-V1 (DOE-HDBK-1018/1-93), Diesel Engines, ME-01 p. 3", null, null, "C942"],
  ["Controllers and Positioners", "What happens to a mechanical-hydraulic governor on loss of lube oil pressure?", "Its oil supply is cut off and it shuts down the engine.", "DOE-1018-V1 (DOE-HDBK-1018/1-93), Diesel Engine Speed, Fuel Controls, and Protection, ME-01 p. 34", null, {"f": "images/doe-1018-v1-me-01-fig28.png", "alt": "Three views of a simplified governor at normal speed, overspeed, and underspeed, showing flyweights, pilot valve, and buffer piston positions.", "cap": "Figure 28. Simplified Mechanical-Hydraulic Governor. Source: DOE-1018-V1 (DOE-HDBK-1018/1-93), ME-01 p. 35.", "at": "a"}, "C943"],
  ["Heat Exchangers and Condensers", "What are the two types of heat exchanger construction?", "Tube and shell, and plate.", "DOE-1018-V1 (DOE-HDBK-1018/1-93), Types of Heat Exchangers, ME-02 p. 2", null, {"f": "images/doe-1018-v1-me-02-fig1.png", "alt": "Tube and shell heat exchanger cut open, labeling the tube sheet, support plates, steam inlet, feedwater connections, and water box.", "cap": "Figure 1. Tube and Shell Heat Exchanger. Source: DOE-1018-V1 (DOE-HDBK-1018/1-93), ME-02 p. 3.", "at": "a"}, "C944"],
  ["Heat Exchangers and Condensers", "What are the four internal parts of a tube and shell heat exchanger named in DOE-HDBK-1018?", "Tubes, tube sheet, shell, and baffles.", "DOE-1018-V1 (DOE-HDBK-1018/1-93), Types of Heat Exchangers, ME-02 p. 2", null, {"f": "images/doe-1018-v1-me-02-fig1.png", "alt": "Tube and shell heat exchanger cut open, labeling the tube sheet, support plates, steam inlet, feedwater connections, and water box.", "cap": "Figure 1. Tube and Shell Heat Exchanger. Source: DOE-1018-V1 (DOE-HDBK-1018/1-93), ME-02 p. 3.", "at": "a"}, "C945"],
  ["Heat Exchangers and Condensers", "What is cross flow in a heat exchanger?", "One fluid flows perpendicular to the second, at a 90° angle. It is usually used where one fluid changes state.", "DOE-1018-V1 (DOE-HDBK-1018/1-93), Types of Heat Exchangers, ME-02 p. 6", null, {"f": "images/doe-1018-v1-me-02-fig5.png", "alt": "Cross flow: one fluid passes through tubes while the other crosses them at a right angle, with a graph of both temperatures.", "cap": "Figure 5. Cross Flow Heat Exchanger. Source: DOE-1018-V1 (DOE-HDBK-1018/1-93), ME-02 p. 6.", "at": "a"}, "C946"],
  ["Heat Exchangers and Condensers", "What is a hotwell?", "The bottom area of a condenser, where condensate collects and the condensate pump takes its suction.", "DOE-1018-V1 (DOE-HDBK-1018/1-93), Heat Exchanger Applications, ME-02 p. 15", null, {"f": "images/doe-1018-v1-me-02-fig9.png", "alt": "Single-pass condenser: cooling water flows through straight tubes between water boxes while steam condenses on the shell side and collects in the hotwell.", "cap": "Figure 9. Single-Pass Condenser. Source: DOE-1018-V1 (DOE-HDBK-1018/1-93), ME-02 p. 15.", "at": "a"}, "C947"],
  ["Heat Exchangers and Condensers", "What is condensate depression?", "The amount the condensate is cooled below saturation temperature, in degrees subcooled.", "DOE-1018-V1 (DOE-HDBK-1018/1-93), Heat Exchanger Applications, ME-02 p. 14", null, null, "C948"],
  ["Heat Exchangers and Condensers", "Why do large steam condensers run at a vacuum?", "To keep steam temperature and pressure as low as possible, which maximizes the difference between source and heat sink for highest cycle efficiency.", "DOE-1018-V1 (DOE-HDBK-1018/1-93), Heat Exchanger Applications, ME-02 p. 18", null, null, "C949"],
  ["Pumps", "What is the purpose of wearing rings in a centrifugal pump?", "They are replaceable rings that allow a small running clearance without wearing the actual impeller or casing.", "DOE-1018-V1 (DOE-HDBK-1018/1-93), Centrifugal Pumps, ME-03 p. 8", null, {"f": "images/doe-1018-v1-me-03-fig10.png", "alt": "Pump cross section labeling the casing, shaft, impeller, volute, stuffing box, gland, packing, lantern ring, and impeller and casing wearing rings.", "cap": "Figure 10. Centrifugal Pump Components. Source: DOE-1018-V1 (DOE-HDBK-1018/1-93), ME-03 p. 8.", "at": "a"}, "C950"],
  ["Pumps", "What is the required relationship between NPSHA and NPSHR?", "NPSHA must be greater than or equal to NPSHR to avoid cavitation.", "DOE-1018-V1 (DOE-HDBK-1018/1-93), Centrifugal Pump Operation, ME-03 p. 13", null, null, "C951"],
  ["Pumps", "What five changes can reduce cavitation?", "Raise suction pressure, lower liquid temperature, reduce suction head losses, reduce flow rate, and reduce impeller speed.", "DOE-1018-V1 (DOE-HDBK-1018/1-93), Centrifugal Pump Operation, ME-03 p. 13", null, null, "C952"],
  ["Pumps", "What is pump runout?", "The maximum flow a centrifugal pump can develop without damaging the pump.", "DOE-1018-V1 (DOE-HDBK-1018/1-93), Centrifugal Pump Operation, ME-03 p. 14", null, {"f": "images/doe-1018-v1-me-03-fig11.png", "alt": "Pump head against flow: head is highest at zero flow, at shutoff head, and falls in a downward curve to the runout flow.", "cap": "Figure 11. Centrifugal Pump Characteristic Curve. Source: DOE-1018-V1 (DOE-HDBK-1018/1-93), ME-03 p. 14.", "at": "a"}, "C953"],
  ["Pumps", "How is a centrifugal pump protected from dead-heading and from runout?", "Dead-heading: a recirculation line back to the supply source. Runout: an orifice or throttle valve just downstream of the discharge, and proper piping design.", "DOE-1018-V1 (DOE-HDBK-1018/1-93), Centrifugal Pump Operation, ME-03 p. 15", null, {"f": "images/doe-1018-v1-me-03-fig11.png", "alt": "Pump head against flow: head is highest at zero flow, at shutoff head, and falls in a downward curve to the runout flow.", "cap": "Figure 11. Centrifugal Pump Characteristic Curve. Source: DOE-1018-V1 (DOE-HDBK-1018/1-93), ME-03 p. 14.", "at": "a"}, "C954"],
  ["Pumps", "What are the three basic groups of positive displacement pumps?", "Reciprocating, rotary, and diaphragm.", "DOE-1018-V1 (DOE-HDBK-1018/1-93), Positive Displacement Pumps, ME-03 p. 18", null, {"f": "images/doe-1018-v1-me-03-fig12.png", "alt": "Single piston in a cylinder with suction and discharge check valves, shown on the suction stroke and the discharge stroke.", "cap": "Figure 12. Reciprocating Positive Displacement Pump Operation. Source: DOE-1018-V1 (DOE-HDBK-1018/1-93), ME-03 p. 19.", "at": "a"}, "C955"],
  ["Pumps", "What is the characteristic curve of an ideal positive displacement pump?", "A vertical line on a graph of head versus flow.", "DOE-1018-V1 (DOE-HDBK-1018/1-93), Positive Displacement Pumps, ME-03 p. 28", null, {"f": "images/doe-1018-v1-me-03-fig21.png", "alt": "Pump head against flow rate: the ideal curve is a vertical line, and the real curve leans toward lower flow at high head, showing slippage.", "cap": "Figure 21. Positive Displacement Pump Characteristic Curve. Source: DOE-1018-V1 (DOE-HDBK-1018/1-93), ME-03 p. 27.", "at": "a"}, "C956"],
  ["Valves", "What are the seven basic valve parts in objective 1.3 of ME-04?", "Body, bonnet, stem, actuator, packing, seat, and disk.", "DOE-1018-V2 (DOE-HDBK-1018/2-93), Valve Functions and Basic Parts, ME-04 p. 1", null, {"f": "images/doe-1018-v2-me-04-fig1.png", "alt": "Valve cross section labeling the actuator, packing, bonnet, stem, body, disk, and seat.", "cap": "Figure 1. Basic Parts of a Valve. Source: DOE-1018-V2 (DOE-HDBK-1018/2-93), ME-04 p. 2.", "at": "a"}, "C957"],
  ["Valves", "What is the primary pressure boundary of a valve?", "The body, sometimes called the shell.", "DOE-1018-V2 (DOE-HDBK-1018/2-93), Valve Functions and Basic Parts, ME-04 p. 2", null, null, "C958"],
  ["Valves", "What does a globe valve backseat do?", "It prevents system pressure from building against the valve packing.", "DOE-1018-V2 (DOE-HDBK-1018/2-93), Types of Valves, ME-04 p. 18", null, null, "C959"],
  ["Valves", "What is the main drawback of a globe valve?", "High head loss from two or more right angle turns of the fluid.", "DOE-1018-V2 (DOE-HDBK-1018/2-93), Types of Valves, ME-04 p. 15", null, null, "C960"],
  ["Valves", "What is a needle valve used for?", "Relatively fine adjustments in the amount of fluid flow.", "DOE-1018-V2 (DOE-HDBK-1018/2-93), Types of Valves, ME-04 p. 33", null, {"f": "images/doe-1018-v2-me-04-fig20.png", "alt": "Needle valve with a long, tapered point on the end of the stem entering the seat.", "cap": "Figure 20. Needle Valve. Source: DOE-1018-V2 (DOE-HDBK-1018/2-93), ME-04 p. 33.", "at": "a"}, "C961"],
  ["Valves", "What does a reducing valve do?", "It automatically reduces supply pressure to a preselected pressure.", "DOE-1018-V2 (DOE-HDBK-1018/2-93), Types of Valves, ME-04 p. 28", null, null, "C962"],
  ["Valves", "What is the difference between direct-acting and reverse-acting pneumatic actuators?", "Direct-acting: air closes the valve and the spring opens it. Reverse-acting: air opens the valve and the spring closes it.", "DOE-1018-V2 (DOE-HDBK-1018/2-93), Valve Actuators, ME-04 p. 47", null, {"f": "images/doe-1018-v2-me-04-fig34.png", "alt": "Pneumatic actuator with air pressure acting on a diaphragm above a spring, connected through the stem to the valve.", "cap": "Figure 34. Pneumatic Actuator. Source: DOE-1018-V2 (DOE-HDBK-1018/2-93), ME-04 p. 47.", "at": "a"}, "C963"],
  ["Valves", "How does a motor-operated valve fail on loss of power?", "As is.", "LP-VALVE-FUNDAMENTALS (Valve Fundamentals.docx), slide 1.47 Electric-Motor Actuator", null, null, "C964"],
  ["Brittle Fracture and Vessel Thermal Stress", "What is the preferred fuel cladding material for sodium-cooled fast reactors, according to DOE-HDBK-1017?", "Stainless steel.", "DOE-1017-V2 (DOE-HDBK-1017/2-93), Cladding and Reflectors, MS-05 p. 12", null, null, "C965"],
  ["Brittle Fracture and Vessel Thermal Stress", "What does a fast reactor reflector consist of?", "A dense element of high mass number, because neutron thermalization is not desirable.", "DOE-1017-V2 (DOE-HDBK-1017/2-93), Cladding and Reflectors, MS-05 p. 13", null, null, "C966"],
  ["Brittle Fracture and Vessel Thermal Stress", "Which materials shield low energy neutrons, high energy neutrons, and gamma rays best?", "Low energy neutrons: low mass number, hydrogenous materials. High energy neutrons: good inelastic scatterers such as iron. Gamma: high atomic mass number and high density, such as lead.", "DOE-1017-V2 (DOE-HDBK-1017/2-93), Shielding Materials, MS-05 p. 20", null, null, "C967"],
  ["Brittle Fracture and Vessel Thermal Stress", "What is fatigue failure?", "Fracture by progressive brittle cracking under repeated cyclic stresses considerably below normal strength.", "DOE-1017-V2 (DOE-HDBK-1017/2-93), Plant Material Problems, MS-05 p. 27", null, null, "C968"],
  ["Brittle Fracture and Vessel Thermal Stress", "What are a knock-on, a vacancy, and an interstitial?", "A knock-on is the displaced nucleus. A vacancy is the site it left. An interstitial is a permanently displaced atom sitting at a position other than a normal lattice site.", "DOE-1017-V2 (DOE-HDBK-1017/2-93), Atomic Displacement Due to Irradiation, MS-05 p. 34", null, null, "C969"],
  ["Brittle Fracture and Vessel Thermal Stress", "What does a large number of displacement spikes do to a metal?", "It generally increases hardness and decreases ductility.", "DOE-1017-V2 (DOE-HDBK-1017/2-93), Thermal and Displacement Spikes Due to Irradiation, MS-05 p. 35", null, null, "C970"],
  ["Brittle Fracture and Vessel Thermal Stress", "Which chemical bond is least resistant to radiation?", "The covalent bond.", "DOE-1017-V2 (DOE-HDBK-1017/2-93), Radiation Effects in Organic Compounds, MS-05 p. 46", null, null, "C971"],
  ["Brittle Fracture and Vessel Thermal Stress", "What problems does swelling of stainless steel cause in a fast reactor?", "Changes in coolant channel dimensions and interference with the free movement of control elements.", "DOE-1017-V2 (DOE-HDBK-1017/2-93), Effect Due to Neutron Capture, MS-05 p. 41", null, null, "C972"],
  ["Pumps", "What are the three common types of air compressors?", "Reciprocating, rotary, and centrifugal.", "DOE-1018-V2 (DOE-HDBK-1018/2-93), Air Compressors, ME-05 p. 1", null, null, "C973"],
  ["Pumps", "What are the three groups of rotary compressors?", "Slide vane-type, lobe-type, and liquid seal ring-type.", "DOE-1018-V2 (DOE-HDBK-1018/2-93), Air Compressors, ME-05 p. 4", null, null, "C974"],
  ["Pumps", "What is an aftercooler?", "A cooler on the discharge of a compressor that removes the heat generated during compression.", "DOE-1018-V2 (DOE-HDBK-1018/2-93), Air Compressors, ME-05 p. 7", null, {"f": "images/doe-1018-v2-me-05-fig7.png", "alt": "Tube-type compressor air cooler: air passes through the tubes from inlet to discharge while water flows through the shell from water inlet to water outlet.", "cap": "Figure 7. Compressor Air Cooler. Source: DOE-1018-V2 (DOE-HDBK-1018/2-93), ME-05 p. 7.", "at": "a"}, "C975"],
  ["Fluid Statics and Dynamics", "What equation relates force and pressure in a hydraulic piston?", "F = P x A.", "DOE-1018-V2 (DOE-HDBK-1018/2-93), Hydraulics, ME-05 p. 10", null, null, "C976"],
  ["Fluid Statics and Dynamics", "What does Pascal's Law say?", "Pressure in a fluid acts equally in all directions.", "DOE-1018-V2 (DOE-HDBK-1018/2-93), Hydraulics, ME-05 p. 10", null, null, "C977"],
  ["Steam", "What is the primary function of a boiler?", "To produce steam at a given pressure and temperature.", "DOE-1018-V2 (DOE-HDBK-1018/2-93), Boilers, ME-05 p. 14", null, null, "C978"],
  ["Steam", "What does a boiler's steam drum do?", "It separates the steam from the heated water.", "DOE-1018-V2 (DOE-HDBK-1018/2-93), Boilers, ME-05 p. 16", null, null, "C979"],
  ["Steam", "What does a boiler economizer do?", "It uses heat from the boiler exhaust gases to raise the temperature of the inlet feedwater.", "DOE-1018-V2 (DOE-HDBK-1018/2-93), Boilers, ME-05 p. 15", null, null, "C980"],
  ["Heat Exchangers and Condensers", "How is water cooled in a cooling tower?", "By direct contact of water and air.", "DOE-1018-V2 (DOE-HDBK-1018/2-93), Cooling Towers, ME-05 p. 19", null, {"f": "images/doe-1018-v2-me-05-fig11.png", "alt": "Cutaway of an induced draft cooling tower showing the fill and collecting basin, with a fan at the top.", "cap": "Figure 11. Induced Draft Cooling Tower. Source: DOE-1018-V2 (DOE-HDBK-1018/2-93), ME-05 p. 19.", "at": "a"}, "C981"],
  ["Demineralizers and Ion Exchangers", "What are the two groups of ion exchangers?", "Single-bed and mixed-bed.", "DOE-1018-V2 (DOE-HDBK-1018/2-93), Demineralizers, ME-05 p. 29", null, null, "C982"],
  ["Steam", "Where are steam traps installed?", "At low points in the system or machinery to be drained.", "DOE-1018-V2 (DOE-HDBK-1018/2-93), Steam Traps, ME-05 p. 39", null, null, "C983"],
  ["Demineralizers and Ion Exchangers", "What separates filtration from demineralization?", "Filtration removes suspended solids. Demineralization removes dissolved ions.", "DOE-1018-V2 (DOE-HDBK-1018/2-93), Filters and Strainers, ME-05 p. 40", null, null, "C984"],
  ["Demineralizers and Ion Exchangers", "What is the intent of a backwash?", "To flow liquid opposite to normal flow, creating a pressure that pushes debris off the strainer or filter.", "DOE-1018-V2 (DOE-HDBK-1018/2-93), Filters and Strainers, ME-05 p. 46", null, null, "C985"],
  ["Neutrons", "What is the Bohr model of the atom?", "A dense nucleus of protons and neutrons surrounded by electrons traveling in discrete orbits at fixed distances from the nucleus.", "DOE-1019-V1 (DOE-HDBK-1019/1-93), Atomic Nature of Matter, NP-01 p. 10", null, null, "C986"],
  ["Neutrons", "What is the atomic number?", "The number of protons in the nucleus.", "DOE-1019-V1 (DOE-HDBK-1019/1-93), Atomic Nature of Matter, NP-01 p. 10", null, null, "C987"],
  ["Neutrons", "What is the mass number?", "The total number of nucleons (protons and neutrons) in the nucleus.", "DOE-1019-V1 (DOE-HDBK-1019/1-93), Atomic Nature of Matter, NP-01 p. 10", null, null, "C988"],
  ["Neutrons", "What is mass defect?", "The difference between the mass of the atom and the sum of the masses of its constituent parts.", "DOE-1019-V1 (DOE-HDBK-1019/1-93), Mass Defect and Binding Energy, NP-01 p. 21", null, null, "C989"],
  ["Neutrons", "What is a becquerel?", "A unit of radioactivity equal to 1 disintegration per second.", "DOE-1019-V1 (DOE-HDBK-1019/1-93), Radioactivity, NP-01 p. 42", null, null, "C990"],
  ["Neutrons", "After how many half-lives can the remaining atoms usually be assumed negligible?", "5 to 7 half-lives.", "DOE-1019-V1 (DOE-HDBK-1019/1-93), Radioactivity, NP-01 p. 33", null, null, "C991"],
  ["Neutrons", "What is transient radioactive equilibrium?", "The parent and daughter nuclides decay at essentially the same rate.", "DOE-1019-V1 (DOE-HDBK-1019/1-93), Radioactivity, NP-01 p. 40", null, {"f": "images/doe-1019-v1-np-01-fig15.png", "alt": "Barium-140 and lanthanum-140 activities over time, with the daughter rising to match the parent.", "cap": "Figure 15. Transient Equilibrium in the Decay of Barium-140. Source: DOE-1019-V1 (DOE-HDBK-1019/1-93), NP-01 p. 41.", "at": "a"}, "C992"],
  ["Neutrons", "What is excitation energy?", "The amount of energy a nucleus has above its ground state.", "DOE-1019-V1 (DOE-HDBK-1019/1-93), Nuclear Fission, NP-01 p. 55", null, null, "C993"],
  ["Neutrons", "What is transmutation?", "Neutron absorption and subsequent decay, which changes one nuclide to another nuclide.", "DOE-1019-V1 (DOE-HDBK-1019/1-93), Nuclear Fission, NP-01 p. 55", null, null, "C994"],
  ["Fuel Depletion and Burnable Poisons", "What is conversion?", "Transmuting fertile material into fissile material, with less fissile material produced than consumed.", "DOE-1019-V1 (DOE-HDBK-1019/1-93), Nuclear Fission, NP-01 p. 55", null, null, "C995"],
  ["Neutrons", "How many neutrons are normally produced from every fission?", "Normally between two and three fast neutrons, most prompt and some delayed.", "DOE-1019-V1 (DOE-HDBK-1019/1-93), Prompt and Delayed Neutrons, NP-02 p. 32", null, null, "C996"],
  ["Neutrons", "What is the photoelectric effect?", "A gamma interacts with an orbiting electron, gives it all its energy, and the electron is ejected.", "DOE-1019-V1 (DOE-HDBK-1019/1-93), Interaction of Radiation With Matter, NP-01 p. 67", null, null, "C997"],
  ["Neutrons", "What is pair production?", "A gamma interacts with the electric field of a nucleus and is converted into an electron-positron pair.", "DOE-1019-V1 (DOE-HDBK-1019/1-93), Interaction of Radiation With Matter, NP-01 p. 67", null, null, "C998"],
  ["Reactor Kinetics and Neutron Sources", "What is an intrinsic neutron source?", "Neutron-producing reactions that always occur in reactor materials.", "DOE-1019-V1 (DOE-HDBK-1019/1-93), Neutron Sources, NP-02 p. 1", null, null, "C999"],
  ["Reactor Kinetics and Neutron Sources", "Why are source neutrons important?", "They keep the neutron population high enough to give a visible indication on the most sensitive instruments while shut down and during startup.", "DOE-1019-V1 (DOE-HDBK-1019/1-93), Neutron Sources, NP-02 p. 1", null, null, "C1000"],
  ["Neutrons", "What is a macroscopic cross section?", "The probability of a given reaction occurring per unit travel of the neutron.", "DOE-1019-V1 (DOE-HDBK-1019/1-93), Nuclear Cross Sections and Neutron Flux, NP-02 p. 8", null, null, "C1001"],
  ["Neutrons", "What is mean free path?", "The average distance traveled by a neutron before interaction.", "DOE-1019-V1 (DOE-HDBK-1019/1-93), Nuclear Cross Sections and Neutron Flux, NP-02 p. 10", null, null, "C1002"],
  ["Neutrons", "What is a reaction rate?", "The number of interactions of a particular type occurring in a cubic centimeter of material in a second.", "DOE-1019-V1 (DOE-HDBK-1019/1-93), Reaction Rates, NP-02 p. 22", null, null, "C1003"],
  ["Reactor Kinetics and Neutron Sources", "What are delayed neutrons released from?", "The decay of fission products called delayed neutron precursors.", "DOE-1019-V1 (DOE-HDBK-1019/1-93), Prompt and Delayed Neutrons, NP-02 p. 32", null, null, "C1004"],
  ["Neutrons", "What is the neutron generation time?", "The time required for neutrons from one generation to cause the fissions that produce the next generation.", "DOE-1019-V1 (DOE-HDBK-1019/1-93), Prompt and Delayed Neutrons, NP-02 p. 30", null, null, "C1005"],
  ["Neutrons", "At what energies are prompt neutrons born?", "Between 0.1 MeV and 10 MeV, with an average of about 2 MeV.", "DOE-1019-V1 (DOE-HDBK-1019/1-93), Neutron Flux Spectrum, NP-02 p. 37", null, null, "C1006"],
  ["Neutrons", "At what energies do most fissions occur in an SFR?", "At higher energies, above 10 keV. Moderation is avoided, and there are no thermal neutrons.", "ML19148A793 (ML19148A793.pdf), slide 3", null, null, "C1007"],
  ["Neutrons", "About what share of the fission rate in a fast reactor comes from U-238 threshold fission?", "About 10%. The threshold is at about 1 MeV.", "ML19148A793 (ML19148A793.pdf), slide 8", null, null, "C1008"],
  ["Neutron Life Cycle", "What is reactivity?", "The fractional change in neutron population per generation.", "DOE-1019-V2 (DOE-HDBK-1019/2-93), Reactivity, NP-03 p. 22", null, null, "C1009"],
  ["Neutron Life Cycle", "What is subcritical?", "The neutron population is decreasing each generation.", "DOE-1019-V2 (DOE-HDBK-1019/2-93), Neutron Life Cycle, NP-03 p. 15", null, null, "C1010"],
  ["Neutron Life Cycle", "What is supercritical?", "The neutron population is increasing each generation.", "DOE-1019-V2 (DOE-HDBK-1019/2-93), Neutron Life Cycle, NP-03 p. 15", null, null, "C1011"],
  ["Neutron Life Cycle", "In a fast reactor, what causes virtually all fissions?", "Fast neutrons.", "DOE-1019-V2 (DOE-HDBK-1019/2-93), Neutron Life Cycle, NP-03 p. 14", null, null, "C1012"],
  ["Reactivity Coefficients", "What are the three components of the reactivity change when sodium density falls?", "Spectral, leakage, and capture.", "LP-REACTIVITY-COEFFICIENTS-MODULE-1 (Reactivity Coefficients Module 1.docx), slide 1.11 Coolant Temperature Coefficient", null, null, "C1013"],
  ["Reactivity Coefficients", "Why is the fuel temperature coefficient called the prompt coefficient?", "An increase in reactor power causes an immediate change in fuel temperature.", "DOE-1019-V2 (DOE-HDBK-1019/2-93), Reactivity Coefficients, NP-03 p. 26", null, null, "C1014"],
  ["Reactivity Coefficients", "What effect does radial core expansion have on reactivity?", "A negative reactivity feedback, because core expansion gives more neutron leakage.", "LP-REACTIVITY-COEFFICIENTS-MODULE-3 (Reactivity Coefficients Module 3.docx), slide 1.4 Core Geometric Expansion", null, null, "C1015"],
  ["Control Rods", "What are the sodium reactor's control rods made of?", "Boron carbide pellets.", "PSAR Rev 1, ML25276A288, Sec. 7.1.1.3.1, p. 7.1-10", null, null, "C1016"],
  ["Control Rods", "What is integral control rod worth?", "The total reactivity worth of the rod at a particular degree of withdrawal from the core.", "DOE-1019-V2 (DOE-HDBK-1019/2-93), Control Rods, NP-03 p. 58", null, null, "C1018"],
  ["Control Rods", "What is differential control rod worth?", "The reactivity change per unit movement of a control rod.", "DOE-1019-V2 (DOE-HDBK-1019/2-93), Control Rods, NP-03 p. 58", null, null, "C1019"],
  ["Reactor Kinetics and Neutron Sources", "What is reactor startup rate?", "The number of factors of ten that reactor power changes in one minute.", "DOE-1019-V2 (DOE-HDBK-1019/2-93), Reactor Kinetics, NP-04 p. 21", null, null, "C1020"],
  ["Reactor Kinetics and Neutron Sources", "What is doubling time?", "The time required for reactor power to double.", "DOE-1019-V2 (DOE-HDBK-1019/2-93), Reactor Kinetics, NP-04 p. 21", null, null, "C1021"],
  ["Reactor Kinetics and Neutron Sources", "What is prompt drop?", "The small, immediate power decrease that follows a negative reactivity insertion.", "DOE-1019-V2 (DOE-HDBK-1019/2-93), Reactor Kinetics, NP-04 p. 22", null, null, "C1022"],
  ["Reactor Kinetics and Neutron Sources", "What does a dollar of reactivity equal?", "The effective delayed neutron fraction.", "DOE-1019-V2 (DOE-HDBK-1019/2-93), Reactor Kinetics, NP-04 p. 22", null, null, "C1023"],
  ["Reactor Operational Physics", "What is shutdown margin?", "The reactivity by which a reactor is or would be subcritical with all rods fully inserted except the highest worth rod, which is assumed fully withdrawn.", "DOE-1019-V2 (DOE-HDBK-1019/2-93), Reactor Operation, NP-04 p. 34", null, null, "C1024"],
  ["Reactor Operational Physics", "What reactor period follows a shutdown for most reactors?", "Around -80 seconds, or a startup rate of -1/3 DPM.", "DOE-1019-V2 (DOE-HDBK-1019/2-93), Reactor Operation, NP-04 p. 32", null, null, "C1025"],
  ["Reactor Operational Physics", "Why is a negative temperature coefficient ineffective at very low power?", "It is ineffective below the point of adding heat, because power changes there do not change temperature.", "DOE-1019-V2 (DOE-HDBK-1019/2-93), Reactor Operation, NP-04 p. 29", null, null, "C1026"],
  ["Demineralizers and Ion Exchangers", "What are the main forms of impurity in SFR sodium coolant?", "Hydrides, oxides, metallic compounds, and metallic and carbon particles.", "LP-COLD-TRAPS-AND-SODIUM-COOLANT-PURIFICATION (Cold Traps and Sodium Coolant Purification.docx), slide 1.2 Cold Traps and Sodium Coolant Purification", null, null, "C1027"],
  ["Demineralizers and Ion Exchangers", "Which impurities do sodium cold traps remove?", "Oxygen, hydrogen and carbon impurities, from the primary and intermediate sodium coolant loops.", "LP-COLD-TRAPS-AND-SODIUM-COOLANT-PURIFICATION (Cold Traps and Sodium Coolant Purification.docx), slide 1.7 Component Purpose", null, null, "C1028"],
  ["Demineralizers and Ion Exchangers", "What does a cold trap economizer do?", "It acts as a regenerative heat exchanger and pre-heats the clean sodium re-entering the system.", "LP-COLD-TRAPS-AND-SODIUM-COOLANT-PURIFICATION (Cold Traps and Sodium Coolant Purification.docx), slide 1.10 Cold Trap", null, null, "C1029"],
  ["Demineralizers and Ion Exchangers", "What sodium impurity level can a cold trap achieve?", "Under five parts per million (ppm).", "LP-COLD-TRAPS-AND-SODIUM-COOLANT-PURIFICATION (Cold Traps and Sodium Coolant Purification.docx), slide 1.10 Cold Trap", null, null, "C1030"],
  ["Demineralizers and Ion Exchangers", "What are the two ways to regenerate a sodium cold trap?", "Externally (ex-situ) or on-site (in-situ).", "LP-COLD-TRAPS-AND-SODIUM-COOLANT-PURIFICATION (Cold Traps and Sodium Coolant Purification.docx), slide 1.21 Regeneration", null, null, "C1031"],
  ["Demineralizers and Ion Exchangers", "Why can sodium hydroxide formation be a concern in sodium systems?", "It can lead to rapid and aggressive caustic stress corrosion cracking.", "LP-COLD-TRAPS-AND-SODIUM-COOLANT-PURIFICATION (Cold Traps and Sodium Coolant Purification.docx), slide 1.4 Importance of purifying sodium coolant", null, null, "C1032"],
  ["Demineralizers and Ion Exchangers", "What is adsorption, as used by RVC cesium filters?", "A process by which chemical bonds form between the adsorbed material and the surface of the filter media.", "LP-COLD-TRAPS-AND-SODIUM-COOLANT-PURIFICATION (Cold Traps and Sodium Coolant Purification.docx), slide 1.26 Reticulated Vitreous Carbon (RVC) Filters", null, null, "C1033"],
  ["Demineralizers and Ion Exchangers", "What caused the 1987 BN-600 transient?", "A chunk of impurities, formed from impurities in the cover gas, dropped from the reactor roof and disturbed core hydraulics and neutronics.", "LP-COLD-TRAPS-AND-SODIUM-COOLANT-PURIFICATION (Cold Traps and Sodium Coolant Purification.docx), slide 1.3 Safety Minute", null, null, "C1034"],
  ["Sensors and Detectors", "What part of a plugging temperature indicator do impurities deposit on?", "An orifice. The deposit reduces the flow, which a flow meter detects.", "LP-PLUGGING-TEMPERATURE-INDICATORS (Plugging Temperature Indicators.docx), slide 1.5 Sodium Purity Monitoring Theory", null, null, "C1035"],
  ["Sensors and Detectors", "What can plugging temperature indicators tell you about a cold trap?", "How effective it is, and when it should be placed in service if it is not operated continuously.", "LP-PLUGGING-TEMPERATURE-INDICATORS (Plugging Temperature Indicators.docx), slide 1.8 Cold Trap", null, null, "C1036"],
  ["Sensors and Detectors", "How did EBR-II discover copper in its primary sodium?", "By the irreversible plugging of the PTI in 1967. The source was the exposed bus bars of the primary auxiliary pump.", "LP-PLUGGING-TEMPERATURE-INDICATORS (Plugging Temperature Indicators.docx), slide 1.11 Advantages of PTI Fill-in-blank", null, null, "C1037"],
  ["Sensors and Detectors", "Since when have PTIs been used at EBR-II?", "Since the initial fill of sodium in the primary and secondary systems in 1963.", "LP-PLUGGING-TEMPERATURE-INDICATORS (Plugging Temperature Indicators.docx), slide 1.11 Advantages of PTI Fill-in-blank", null, null, "C1038"],
  ["Sensors and Detectors", "How do on-line PTIs avoid sample contamination?", "On-line systems avoid contamination of the sample by air or other foreign agents.", "LP-PLUGGING-TEMPERATURE-INDICATORS (Plugging Temperature Indicators.docx), slide 1.11 Advantages of PTI Fill-in-blank", null, null, "C1039"],
  ["Sensors and Detectors", "Name five ways of detecting sodium leaks listed in the NRC training slides.", "Smoke detectors, contact detectors (spark plugs), cable detectors, aerosol monitors and inspections.", "ML19149A433 (ML19149A433.pdf), slide 21", null, null, "C1040"],
  ["PSAR: Ancillary Systems", "What devices does Natrium SPS leak detection use?", "Devices such as wire and cable, spark plugs, and mutual inductance type sensors.", "PSAR Rev 1, ML25276A288, Sec. 7.2.4.2.2, p. 7.2-47", null, null, "C1041"],
  ["PSAR: Ancillary Systems", "What decides the type of sodium leak detector used at Natrium?", "The needs of the installation location and configuration.", "PSAR Rev 1, ML25276A288, Sec. 7.5.2.3.4, p. 7.5-16", null, null, "C1042"],
  ["PSAR: Ancillary Systems", "Where is smoke detection used for Natrium sodium leaks?", "In areas where sodium reactions may occur, such as Intermediate Air Cooling stacks.", "PSAR Rev 1, ML25276A288, Sec. 7.5.2.3.4, p. 7.5-16", null, null, "C1043"],
  ["PSAR: Ancillary Systems", "How is sodium buildup in the RV-GV annulus gas monitored?", "Through absolute filter differential pressure changes, oxygen concentrations and radiation levels.", "PSAR Rev 1, ML25276A288, Sec. 7.2.3.2.1, p. 7.2-28", null, null, "C1044"],
  ["PSAR: Nuclear Heat Supply Systems", "What are the Natrium primary and secondary control rods constructed of?", "Boron carbide pellets.", "PSAR Rev 1, ML25276A288, Sec. 7.1.1.3.1, p. 7.1-10", null, null, "C1045"],
  ["PSAR: Reactor Auxiliary Systems", "What is the key process indicator for sodium purity at Natrium?", "The saturation temperature, which correlates directly with impurity concentration.", "PSAR Rev 1, ML25276A288, Sec. 7.2.4.3.1, p. 7.2-51", null, null, "C1046"],
];
